item_ext_desc[904] = "[ffffff]一壇普通品質的陳年好酒，酒封還沒有打開！\n[-]\n[e76041]使用：增加1點酒量，獲得醉酒狀態，在篝火附近飲酒獲得大量經驗。（組隊情況下，每位元飲酒的隊友將提供額外5%的經驗加成）[-]\n[00ff00]限制：每日可飲用<%= curitem:common_limit_max_count() %>壇豪傑酒，今日尚可飲用<%= curitem:common_limit_remain_count() %>壇。[-]\n[3485ff]合成：每5個可合成1個更高品質的豪傑酒。[-]"
item_ext_desc[905] = "[ffffff]一壇[-][0077ff]精良品質[-][ffffff]的陳年好酒，正適合與一二知己共飲！\n[-]\n[e76041]使用：增加8點酒量，獲得醉酒狀態，在篝火附近飲酒獲得大量經驗。（組隊情況下，每位元飲酒的隊友將提供額外5%的經驗加成）[-]\n[00ff00]限制：每日可飲用<%= curitem:common_limit_max_count() %>壇豪傑酒，今日尚可飲用<%= curitem:common_limit_remain_count() %>壇。[-]\n[3485ff]合成：每5個可合成1個更高品質的豪傑酒。[-]"
