item_ext_desc[1551] = "[ffffff]這是身份的象徵，所有人看到羽翼上的光芒，都會由衷的表示尊重。[-]\n[e76041]使用後可獲得至尊幻化[-]"
item_ext_desc[1554] = "[ffffff]勿以善小而不為，勿以惡小而為之。\n[-]"
item_ext_desc[1555] = "[ffffff]古來沖陣扶危主，只有常山趙子龍。\n[-]"
item_ext_desc[1556] = "[ffffff]一生唯鞠躬盡瘁，終世得死而後已。\n[-]"
item_ext_desc[1557] = "[ffffff]看世間蒼天已死，舉目望黃天當立。\n[-]"
item_ext_desc[1558] = "[ffffff]當陽一喝驚天下，萬軍之中取首級。\n[-]"
item_ext_desc[1559] = "[ffffff]馬騎赤兔行千里，刀偃青龍過五關。\n[-]"
item_ext_desc[1560] = "[ffffff]有詩雲人中呂布，又豈知馬中赤兔。\n[-]"
item_ext_desc[1561] = "[ffffff]坊間盡笑黃阿醜，誰識智絕是孔明？\n[-]"
item_ext_desc[1562] = "[ffffff]榆錢不買千金笑，柳帶何須百寶妝？\n[-]"
item_ext_desc[1563] = "[ffffff]紫髯碧眼號英雄，虎踞龍盤坐江東。\n[-]"
item_ext_desc[1564] = "[ffffff]眉黛催成遊子恨，笑顏想斷故人腸。\n[-]"
item_ext_desc[1565] = "[ffffff]臨淵歎洛神淩波，卻奈何亦嫻亦靜。\n[-]"
item_ext_desc[1566] = "[ffffff]只許得沉魚落雁，不曾記閉月羞花。\n[-]"
item_ext_desc[1567] = "[ffffff]爭得魏王江山在，誰憶夏侯目已盲。\n[-]"
item_ext_desc[1568] = "[ffffff]寧教我負天下人，休教天下人負我。\n[-]"
item_ext_desc[1569] = "[ffffff]只因孟起前軍見，天下從此贊虎侯。\n[-]"
item_ext_desc[1570] = "[ffffff]敢問英雄誰得似，臍脂自照不須燈？\n[-]"
item_ext_desc[1571] = "[ffffff]了明月隨風而去，感天威而不復反。\n[-]"
item_ext_desc[1572] = "[ffffff]世知獨戰東南地，人稱江南小霸王。\n[-]"
item_ext_desc[1573] = "[ffffff]笑鎩孔明千百計，智平燕王十萬兵。\n[-]"
item_ext_desc[1574] = "[ffffff]九天仙降火神來，長驅直入蜀地開。\n[-]"
item_ext_desc[1575] = "[ffffff]香閨劍戟寒光在，洞房威武不須驚。\n[-]"
item_ext_desc[1576] = "[ffffff]子義昭名顯江表，無雙弓馬震雄獅。\n[-]"
item_ext_desc[1577] = "[ffffff]父死兄歿世間仇，永生莫敢忘腦後。\n[-]"
item_ext_desc[1578] = "[ffffff]懵懂死同草木朽，悟道生是為永生。\n[-]"
item_ext_desc[1579] = "[ffffff]舉世無雙奇女子，懇請沙場萬里行。\n[-]"
item_ext_desc[1580] = "[ffffff]江東仕女夢中郎，踏破荊州並蒂春。\n[-]"
item_ext_desc[1581] = "[ffffff]江東兒郎多踴躍，聞君入吳夜不啼。\n[-]"
item_ext_desc[1582] = "[ffffff]從來酬君重知己，一朝報友化仇嫌。\n[-]"
item_ext_desc[1583] = "[ffffff]神醫仙術比長桑，慧識如窺垣一方。\n[-]"
item_ext_desc[1584] = "[ffffff]自幼懷膽應無懼，不壯雄心誓不回！\n[-]"
item_ext_desc[1585] = "[ffffff]公瑾窘饑求子敬，一言才起數船歸。\n[-]"
item_ext_desc[1586] = "[ffffff]荊襄戰火綿無盡，白衣渡江一夜休。\n[-]"
item_ext_desc[1587] = "[ffffff]得保魏家江山在，拼得一死救梟雄。\n[-]"
item_ext_desc[1588] = "[ffffff]危身奉上數子孝，克敵艱險不辭難。\n[-]"
item_ext_desc[1589] = "[ffffff]秋風蕭瑟天氣涼，草木搖落露為霜。\n[-]"
item_ext_desc[1590] = "[ffffff]大丈夫志在四海，隔萬里猶比毗鄰。\n[-]"
item_ext_desc[1591] = "[ffffff]煙塵蔽野胡虜盛，舉目中原漢祚衰。\n[-]"
item_ext_desc[1592] = "[ffffff]累世公卿立大名，坐擁河北百萬兵。\n[-]"
item_ext_desc[1593] = "[ffffff]飛步淩雲遍九州，獨憑仙履自遨遊。\n[-]"
item_ext_desc[1594] = "[ffffff]老將白頭志氣大，鐵弓獨力鎮長沙。\n[-]"
item_ext_desc[1595] = "[ffffff]拼將一死存阿斗，勇決當憶女丈夫。\n[-]"
item_ext_desc[1596] = "[ffffff]鳳雛頻獻奇謀策，奈何一箭事成空。\n[-]"
item_ext_desc[1597] = "[ffffff]片語卻似春雷震，能使南陽起臥龍。\n[-]"
item_ext_desc[1598] = "[ffffff]打開禮包可以獲得綠色封魔帖。\n[-]"
item_ext_desc[1599] = "[ffffff]打開禮包可以獲得紫色封魔帖。\n[-]"
item_ext_desc[1600] = "[ffffff]週末簽到獲得的額外獎勵。\n[-]"
item_ext_desc[1601] = "[ffffff]剛剛採摘的美麗花朵，可以送給心儀的人表達心意，也可送給朋友增進友情。[-]\n[e76041]使用：打開送花介面[-]"
item_ext_desc[1602] = "[ffffff]幫助角色快速成長，使用可獲得10000經驗。經驗丹每日限制使用<%= curitem:common_limit_max_count() %>次。\n[-]\n[e76041]今日還可使用<%= curitem:common_limit_remain_count() %>次。[-]"
item_ext_desc[1603] = "[ffffff]用於神羽系統中對翅膀進行培養，培養有高機率暴擊喲！[-]"
item_ext_desc[1604] = "[ffffff]一旦威名驚蜀魏，吳王甯不敬書生。\n[-]"
item_ext_desc[1605] = "[ffffff]舉世無雙張儁乂，力擋蜀國百萬兵。\n[-]"
item_ext_desc[1606] = "[ffffff]領軍克日競千里，萬里疾行猛將軍。\n[-]"
item_ext_desc[1607] = "[ffffff]人道河北四亭柱，實為中原一棟樑！\n[-]"
item_ext_desc[1608] = "[ffffff]臨危畫戟全無用，卻需女子解重圍。\n[-]"
item_ext_desc[1609] = "[ffffff]征袍蜀錦手繡成，桃花馬上建功勳。\n[-]"
item_ext_desc[1610] = "[ffffff]賢後伴君輔國事，誰想子孫禍根存？\n[-]"
item_ext_desc[1611] = "[ffffff]慧眼如炬辨忠奸，二士爭功言在先。\n[-]"
item_ext_desc[1612] = "[ffffff]若無春華臨機變，哪有日後司馬家。\n[-]"
item_ext_desc[1613] = "[ffffff]自歎喪身猶不重，又道滅子複何愁？\n[-]"
item_ext_desc[1614] = "[ffffff]蜀從劉備傳阿斗，四十餘年成晉虜。\n[-]"
item_ext_desc[1615] = "[ffffff]江東黃蓋不知老，奮起風帆入北營。\n[-]"
item_ext_desc[1616] = "[ffffff]三分之計終成畫，秋風日暮斬文長。\n[-]"
item_ext_desc[1617] = "[ffffff]白髮蒼顏居西蜀，威名猶在鎮四方。\n[-]"
item_ext_desc[1618] = "[ffffff]公瑾深交如飲酒，不覺自醉複長眠。\n[-]"
item_ext_desc[1619] = "[ffffff]若無幼平奮身救，安有江東碧眼兒？\n[-]"
item_ext_desc[1620] = "[ffffff]白頭尚為江南表，勸君心懷王霸策。\n[-]"
item_ext_desc[1621] = "[ffffff]浮生寡欲不言笑，淡定旁觀醉裡人。\n[-]"
item_ext_desc[1622] = "[ffffff]文聘空有好武藝，終究不保荊襄存。\n[-]"
item_ext_desc[1623] = "[ffffff]夜夢泰山出紅日，勵志當為古賢臣。\n[-]"
item_ext_desc[1624] = "[ffffff]恃才身死皆自誤，非是曹公欲退兵。\n[-]"
item_ext_desc[1625] = "[ffffff]瓦罐難離井臺破，上將不免陣前亡。\n[-]"
item_ext_desc[1626] = "[ffffff]相貌堂堂心似鬼，龍袍加身是猢猻。\n[-]"
item_ext_desc[1627] = "[ffffff]呂布不從金石論，空負陳宮棟樑材。\n[-]"
item_ext_desc[1628] = "[ffffff]隨父軍征不畏死，笑駡吳狗賤偷生。\n[-]"
item_ext_desc[1629] = "[ffffff]英雄年少功未建，未死沙場卻殞身。\n[-]"
item_ext_desc[1630] = "[ffffff]英傑悍勇欲建功，可憐蒼天妒英雄。\n[-]"
item_ext_desc[1631] = "[ffffff]三代老陳功卓顯，還是江東韓義公。\n[-]"
item_ext_desc[1632] = "[ffffff]誰言丁奉行將木，尚能雪中奮短兵。\n[-]"
item_ext_desc[1633] = "[ffffff]率部奮武降青龍，夷陵一戰顯威名。\n[-]"
item_ext_desc[1634] = "[ffffff]震國威巴蜀皆驚，揚武聲江岷齊喑。\n[-]"
item_ext_desc[1635] = "[ffffff]於禁晚節終不保，歸來無顏見舊君。\n[-]"
item_ext_desc[1636] = "[ffffff]不到蜀地心不死，暮年卻作亡國人。\n[-]"
item_ext_desc[1637] = "[ffffff]蒼天有意玄德敗，臨行收去法孝直。\n[-]"
item_ext_desc[1638] = "[ffffff]粉骨碎身全無懼，只保麟主過江東。\n[-]"
item_ext_desc[1639] = "[ffffff]江東諸士亡國日，任人驅馳才思君。\n[-]"
item_ext_desc[1640] = "[ffffff]縱有將軍神機算，奈何吳主忌忠賢。\n[-]"
item_ext_desc[1641] = "[ffffff]奮勇驅師如虎豹，破軍斬陣若驚雷。\n[-]"
item_ext_desc[1642] = "[ffffff]一身轉戰三千里，一劍當關百萬兵。\n[-]"
item_ext_desc[1643] = "[ffffff]文若莫將張良比，死後無顏見漢君。\n[-]"
item_ext_desc[1644] = "[ffffff]河濟泰山猶是漢，不忍國賊坐關中。\n[-]"
item_ext_desc[1645] = "[ffffff]一心鑽營捧曹賊，不想還得活幾春？\n[-]"
item_ext_desc[1646] = "[ffffff]指點江山謀大勢，經緯天地棟樑材。\n[-]"
item_ext_desc[1647] = "[ffffff]陣斬關東十二將，力抗汜水拒諸侯。\n[-]"
item_ext_desc[1648] = "[ffffff]可憐中心昭日月，良策卻遭奉先疑。\n[-]"
item_ext_desc[1649] = "[ffffff]龐德抬棺陣前死，不效於禁跪祈生。\n[-]"
item_ext_desc[1650] = "[ffffff]遠慮深謀藏韜晦，未雨綢繆顯真才。\n[-]"
item_ext_desc[1651] = "[ffffff]往昔譖害田豐日，曾想今朝斷頭時？\n[-]"
item_ext_desc[1652] = "[ffffff]倘使符水化百病，公卿還需華佗醫？\n[-]"
item_ext_desc[1653] = "[ffffff]元直走馬薦臥龍，水鏡說得鳳雛來。\n[-]"
item_ext_desc[1654] = "[ffffff]俱是人間驍勇將，河北名將數顏良。\n[-]"
item_ext_desc[1656] = "[ffffff]天機不可洩露是也。\n[-]"
item_ext_desc[2032] = "[ffffff]盜神我來也的權杖，據說使用後盜神我來也即會出現。\n[-]\n[e76041]使用:使飛賊我來也現身！[-]"
