item_ext_desc[7020] = "[ffffff]穿行千萬界，方可洞天機。[-]\n出售給商店可獲得25本地術殘卷。[-]"
item_ext_desc[7041] = "[ffffff]就問你萌不萌！[-]"
item_ext_desc[7050] = "[ffffff]進入鎖妖塔需要消耗的物品。[-]"
item_ext_desc[7275] = "[ffffff]備周則意怠，常見則不疑，陰在陽之內，不在陽之對。[-]"
item_ext_desc[7276] = "[ffffff]共敵遜分敵，敵陽遜敵陰，戰敵遜誘敵，敵剛遜敵柔。[-]"
item_ext_desc[7277] = "[ffffff]敵明友未定，引友殺敵也，不自出力之，以損推演乎。[-]"
item_ext_desc[7278] = "[ffffff]困敵之勢者，不以明戰也，損剛且益柔，氣定且神閑。[-]"
item_ext_desc[7279] = "[ffffff]敵勢之害大，即就勢取利，夫剛決柔也，擊其害處也。[-]"
item_ext_desc[7280] = "[ffffff]敵志亂萃者，坤下兌上象，利其不自主，而取之不疑。[-]"
item_ext_desc[7287] = "[ffffff]誑也非誑也，實其所誑也，少陰少陽者，太陰太陽也。[-]"
item_ext_desc[7288] = "[ffffff]示之以動者，利靜而有主，明修其棧道，則益動而巽。[-]"
item_ext_desc[7289] = "[ffffff]陽乖於序亂，陰之以待逆，暴戾恣睢者，其勢自斃矣。[-]"
item_ext_desc[7290] = "[ffffff]夫信而安之，其陰以圖之，須備而後動，勿使其有變。[-]"
item_ext_desc[7291] = "[ffffff]其勢必有損，損陰以益陽，蟲來齧桃根，李樹代桃僵。[-]"
item_ext_desc[7292] = "[ffffff]微隙在所乘，微利在所得，敵之少陰者，夫其少陽也。[-]"
item_ext_desc[7366] = "[ffffff]疑之以叩實，察而後動乎，複動疑之者，其陰之媒也。[-]"
item_ext_desc[7367] = "[ffffff]有用者不借，無用者求借，匪我求童蒙，夫童蒙求我。[-]"
item_ext_desc[7368] = "[ffffff]待天以困之，用人以誘之，往蹇來連返，趨弱以逼強。[-]"
item_ext_desc[7369] = "[ffffff]逼則反兵乎，走則減勢乎，則累其氣力，亦消其鬥志。[-]"
item_ext_desc[7370] = "[ffffff]夫類以誘之，則終擊蒙也，攻之不下者，須利而誘之。[-]"
item_ext_desc[7371] = "[ffffff]夫摧堅奪魁，以解其體矣，龍戰於野者，則其道窮也。[-]"
item_ext_desc[7372] = "[ffffff]若不敵其力，而消其勢也，其下必沖上，兌下乾上象。[-]"
item_ext_desc[7373] = "[ffffff]乘其陰亂者，利其弱無主，隨勢其中也，以向晦入之。[-]"
item_ext_desc[7374] = "[ffffff]須存其形乎，方完其勢也，其友不疑者，其敵不動也。[-]"
item_ext_desc[7375] = "[ffffff]夫敵小弱者，可困而剝之，非恐其逸也，不利有攸往。[-]"
item_ext_desc[7376] = "[ffffff]形禁而勢格，利從近取之，害以遠隔之，上火下澤者。[-]"
item_ext_desc[7377] = "[ffffff]兩大之間者，敵脅以從之，我假以勢也，則有言不信。[-]"
item_ext_desc[7378] = "[ffffff]頻更其陣者，抽其勁旅者，待其自敗也，則曳其輪也。[-]"
item_ext_desc[7379] = "[ffffff]夫大淩小者，警以誘之也，剛中而應者，行險而順矣。[-]"
item_ext_desc[7380] = "[ffffff]寧偽作不為，不偽作妄為。其靜不露機，終雲雷屯也。[-]"
item_ext_desc[7381] = "[ffffff]假之以便也，唆之使前也，須斷其援應，陷之死地矣。[-]"
item_ext_desc[7382] = "[ffffff]夫借局佈勢，力小勢大也，夫鴻漸于陸，其羽可為儀。[-]"
item_ext_desc[7383] = "[ffffff]乘隙插足也，扼其主機也，誘戰而擒之，其漸之進也。[-]"
item_ext_desc[7384] = "[ffffff]兵強攻其將，將智伐其情，終將弱兵頹，其勢自萎也。[-]"
item_ext_desc[7385] = "[ffffff]夫虛者虛之，疑中生疑矣，其剛柔之際，奇而複奇也。[-]"
item_ext_desc[7386] = "[ffffff]其疑中之疑，其以假亂真，則比之自內，終不自失也。[-]"
item_ext_desc[7387] = "[ffffff]人不自害者，受害必真也，假真真假乎，間以得行矣。[-]"
item_ext_desc[7388] = "[ffffff]將多兵眾者，其不可以敵，須使其自累，以殺其勢也。[-]"
item_ext_desc[7389] = "[ffffff]夫全師避敵，以退為進者，其左次無咎，並未失常也。[-]"
