item_ext_desc[12175] = "[ffffff]打開後可隨機獲得地術殘頁、地術殘卷、無字天書殘卷、無字天書、通靈神章、通靈神冊、時裝碎片、靈妖魂魄、4級寶石禮包和3級隨機銘文其中1種道具。[-]\n[e76041]可通過週一福利活動集齊4張相同卡牌來獲得。[-]"
