item_ext_desc[12189] = "[ffffff]一個神秘的禮盒，打開似乎能獲得很多好東西。[-]\n[e76041]打開後概率獲得1個皇家月餅禮盒、坐騎包•地、通靈神冊、通靈神章、上古兵策、上古兵卷、上古兵書、魂魄碎片、小妖魂魄、靈妖魂魄，有較小概率獲得全新坐騎戎昭·聖、稀有坐騎桑陌。每包必得龍紋金元。[-]"
item_ext_desc[12190] = "[ffffff]可獲得中秋快樂四個字之一的稀有禮包。[-]\n[e76041]中秋節快樂！[-]"
item_ext_desc[12191] = "[ffffff]打開後可隨機獲得三國卡包、地術殘卷、稀有時裝以及各種珍貴道具。[-]\n[e76041]中秋節快樂！[-]"
item_ext_desc[12192] = "[ffffff]打開後可隨機獲得三國卡包、地術殘卷、稀有時裝以及各種珍貴道具。[-]\n[e76041]中秋節快樂！[-]"
