item_ext_desc[12203] = "[ffffff]看起來很好吃的糕點。[-]\n[e76041]李大白贈予的禮物，用於參與六龍慶典介面的重陽登高活動。(活動期間內，36級以上玩家方可參與)[-]"
item_ext_desc[12204] = "[ffffff]我有一壺酒，足以慰風塵。[-]\n[e76041]用於和李大白完成對詩任務，以及參與六龍慶典介面的重陽登高活動。(活動期間內，36級以上玩家方可參與)[-]"
item_ext_desc[12211] = "[ffffff]徒弟背叛師父所必須道具。[-]\n[e76041]只能身份為徒弟時才可使用，請謹慎使用。[-]"
item_ext_desc[12212] = "[ffffff]徒弟尊師所必須道具，對師父的無比尊重。[-]\n[e76041]只能身份為徒弟時才可使用。[-]"
item_ext_desc[12213] = "[ffffff]師父收徒時所必須擁有的道具。[-]\n[e76041]使用條件：兩人組隊，師父為隊長，擁有此道具，由師父向黃石老人提出拜師收徒申請。[-]"
