item_ext_desc[12216] = "[ffffff]師徒兩人情義的見證。[-]\n[e76041]師父擁有大量的師德值，決定師徒排行榜師父的名次。[-]"
item_ext_desc[12382] = "[ffffff]打開後可獲得六件基礎裝備。[-]\n[e76041]請不要輕易出售到商店，除非你已經不需要它們，否則後果很嚴重。[-]"
item_ext_desc[12446] = "[ffffff]一部奇特的典籍，使用後，出現無間道的相關任務。[-]\n[e76041]回歸禮包第一天獲得。[-]"
item_ext_desc[12447] = "[ffffff]一部奇特的典籍，使用後，出現九龍鼎的相關任務。[-]\n[e76041]回歸禮包第二天獲得。[-]"
