item_ext_desc[13080] = "[ffffff]打開後可隨機獲得5級皮料、5級原石、3-6級寶石禮包、3級保底符、高級鎖定符、馬草、靈羽、春秋遺物·勝戰、春秋遺物·敵戰、上古兵策。更有一定幾率獲得稀有坐騎醉仙、紫色品質的全新萬聖節寵物南瓜傑克、以及全新法器波板糖碎片。[-]\n[e76041]讓我們在這精彩的節日盡情搗蛋吧。[-]"
item_ext_desc[13081] = "[ffffff]打開後可隨機獲得夜明珠、造化石、紅色精華碎片、粉色精華碎片、橙色精華碎片、紫色精華碎片、3級隨機銘文、東周卡包·無雙、三國卡包·無雙、高級鎖定符、5級皮料、5級原石。更有一定幾率獲得全新稀有坐騎獅鷲、以及稀有坐騎流霜。[-]\n[e76041]這是一個魔法與神話共存的時代。[-]"
