item_ext_desc[13084] = "[ffffff]打開後可隨機獲得精華囊·人、小妖魂魄、靈妖魂魄、寶珠囊·地、靈羽、馬草、2-4級隨機銘文和5-7級寶石禮包。更有機率獲得全新稀有坐騎奇獸以及稀有坐騎朱炎。[-]"
