item_ext_desc[13575] = "[ffffff]打開後可隨機獲得地術殘卷（綁）、通靈神冊（綁）、春秋遺物·攻戰、春秋遺物·敵戰、精華囊·人、2級銘文、煉妖包·人等。有一定機率可獲得全新稀有坐騎駭翼（非綁）、稀有坐騎銀風（非綁）和稀有永久時裝斷水。[-]\n[e76041]节日快樂！[-]"
item_ext_desc[13576] = "[ffffff]感恩慶典獎勵。[-]\n[e76041]使用1：必定獲得1個火雞骨頭。\n使用2：隨機獲得三國卡包·卓越、三國卡包·無雙、3級寶石禮包、掃蕩令、委託令、紫色韜略果、馬草、光羽、滎陽城通牒、地術殘卷。[-]"
item_ext_desc[13577] = "[ffffff]感恩慶典獎勵。[-]\n[e76041]使用1：必定獲得1個火雞骨頭。\n使用2：隨機獲得人皇遺篇、5級寵物口糧、5級寶石禮包、3級隨機銘文、寶珠囊·地、馬草。[-]"
