item_ext_desc[13695] = "[ffffff]打開可隨機獲得上古兵書、競猜幣、精華囊·人、4級寵物口糧、春秋遺物·攻戰、春秋遺物·敵戰和3至8級隨機寶石。更有幾率獲得稀有坐騎淩月、稀有坐騎朱炎和坐騎碎片朱炎之輝。[-]\n[e76041]開啟後增加1點助威值（計入排行時可能存在5分鐘延遲）。[-]"
item_ext_desc[13696] = "[ffffff]必定獲得一枚坐騎碎片朱炎之輝，此外打開可隨機獲得上古兵書、5至9級隨機寶石或大量競猜幣、精華囊·人、4級寵物口糧、春秋遺物·攻戰、春秋遺物·敵戰。更有可觀幾率獲得稀有坐騎淩月、稀有坐騎朱炎。[-]\n[e76041]開啟後增加10點助威值（計入排行時可能存在5分鐘延遲）。[-]"
