item_ext_desc[13698] = "[ffffff]打開後可隨機獲得2-5級隨機銘文、坐騎包·地、煉妖包·地、寶珠囊·地、馬草、靈羽、小妖魂魄、靈妖魂魄、5級原石和5級皮料。更有機率獲得稀有坐騎醉仙和流霜。打開後必然獲得1個青銅碎片包。[-]"
