item_ext_desc[14593] = "[ffffff]使用後可免費自由兌換仙鹿、赤虹、雪月、50本地術殘卷中的一種。[-]"
item_ext_desc[14598] = "[ffffff]集齊100個該道具可合成1個坐騎兌換券。[-]\n[e76041]該坐騎兌換券可免費自由兌換乘風、步雨和驚雷中的一種。[-]"
item_ext_desc[14599] = "大風起兮雲飛揚，安得猛士兮守四方！[-]\n[e76041]收藏後暴傷減免+2%[-]"
