item_ext_desc[14777] = "[ffffff]打開後必定獲得1個黃色助威令和1個龍紋金元，隨機獲得競猜幣、光羽、通靈神冊、人皇遺篇、寶玉、寶珠囊·地、3級保底符、和3至4級寵物口糧。更有較低概率獲得稀有坐騎金羚、稀有坐騎滄羚。[-]"
item_ext_desc[14778] = "[ffffff]打開後必定獲得1個紫色助威令和10個龍紋金元，隨機獲得大量競猜幣、光羽、通靈神冊、人皇遺篇、寶玉、寶珠囊·地、3級保底符、和4至5級寵物口糧。更有可觀概率獲得稀有坐騎金羚、稀有坐騎滄羚。[-]"
item_ext_desc[14823] = "[ffffff]獲得一張神·趙雲卡牌。[-]"
item_ext_desc[14824] = "[ffffff]獲得一張神·張角卡牌。[-]"
item_ext_desc[14882] = "[ffffff]我從南蠻來，我回南蠻去！[-]\n[e76041]使用之後獲得雞年稀有坐騎—萌瑪。\n出售後可獲得25本地術殘卷。[-]"
item_ext_desc[14883] = "[ffffff]集齊100個該道具可合成1個綁定的完整的碧空。[-]\n[e76041]通過合成獲得的碧空是綁定的。[-]"
item_ext_desc[14887] = "[ffffff]可領取限時特效稱號<一生所愛>。[-]\n[e76041]稱號自使用後持續30天，到期後自動失效。\n裝備後可獲得主動屬性\n物理攻擊+4000\n法術攻擊+4000[-]"
item_ext_desc[14890] = "[ffffff]我跑起來，你只能看到一道光。[-]\n[e76041]使用之後獲得稀有坐騎—墨霜。[-]"
item_ext_desc[14891] = "[ffffff]我很喜歡我亮橙橙的毛髮。[-]\n[e76041]使用之後獲得稀有坐騎—灼雲。[-]"
