item_ext_desc[15561] = "[ffffff]打開後可隨機獲得無字天書、地術殘卷、通靈神冊、人皇遺篇等稀有道具。[-]"
item_ext_desc[15562] = "[ffffff]使用後可獲得1000點武士令。[-]"
item_ext_desc[15564] = "[ffffff]碧落有瑕，箐箐無霹。[-]\n[e76041]使用之後獲得稀有坐騎—青玉。[-]"
item_ext_desc[15565] = "[ffffff]使用後可獲得稀有幻化-青輝之羽。[-]"
item_ext_desc[15571] = "[ffffff]打開後可獲得一隻紫色品質的青木蠍寵物。[-]"
item_ext_desc[15572] = "[ffffff]打開後可隨機獲得波板糖碎片、3至5級寵物口糧、馬草、靈羽、2至3級隨機銘文和通靈神冊等。有較小機率獲得稀有聖獸坐騎玄武之靈和白虎之靈、稀有法器波板糖、全新時裝撲克醜皇。[-]"
item_ext_desc[15573] = "打開後可獲得永久稀有時裝—撲克醜皇。[-]"
item_ext_desc[15579] = "[ffffff]使用後可以獲得1000點武士令聲望。[-]"
item_ext_desc[15581] = "[ffffff]打開可以獲得1份霸主之賜禮包和1000點武士令。[-]\n[e76041][00ff00]霸主之賜：打開後可隨機獲得無字天書、地術殘卷、通靈神冊、人皇遺篇等稀有道具。[-]\n陣營戰首勝獎勵，獲得一場陣營戰勝利即可領取。[-]"
item_ext_desc[15582] = "[ffffff]打開後可隨機獲得靈羽、馬草、寶珠囊·地、造化石、夜明珠、光羽囊·地、6級寶石禮包和7級寶石禮包等。必然獲得錦旗，用於參加勞動節活動。有機率獲得稀有坐騎奇獸和全新坐騎水雲。[-]"
item_ext_desc[15584] = "[ffffff]龍爭虎鬥第六賽季單騎戰貪狼武神獎勵。[-]\n[e76041]使用：可獲得稱號“貪狼武神(1V1)”。\n主動屬性：物理攻擊+2500，法術攻擊+2500\n被動屬性：物理攻擊+500，法術攻擊+500[-]\n[ffff00]聽說單騎戰裏只有我是永久的稱號。[-]"
