item_ext_desc[15883] = "[ffffff]水仙欲上鯉魚去，一夜芙蓉紅淚多。[-]\n[e76041]使用之後獲得稀有坐騎—錦鯉。[-]"
item_ext_desc[15884] = "[ffffff]電閃雷鳴我狂嘯，氣吞山河氣壯雲。[-]\n[e76041]使用之後獲得稀有坐騎—龍牙。[-]"
item_ext_desc[15885] = "我愛此花香靜遠，一生低首紫羅蘭。[-]"
item_ext_desc[15886] = "打開禮包後可獲得限時30天的時裝—紫影香羅。[-]"
item_ext_desc[15887] = "[ffffff]可于王城大喬處兌換稀有商品。[-]\n[e76041]金元上紋著精緻的龍痕，一眼看去便知其頗具價值。[-]"
item_ext_desc[15888] = "[ffffff]打開後可隨機獲得5級皮料、5級原石、4級寵物口糧、5級寵物口糧、靈妖魂魄、魂魄包·地、3級隨機銘文、4級隨機銘文和5級隨機銘文。更有幾率獲得全新坐騎望舒和稀有坐騎淩月。\n必然獲得一枚龍紋金元。[-]\n[e76041]誰言寸草心，報得三春暉。[-]"
item_ext_desc[15891] = "靈之來兮敝日，青雲衣兮白霓裳。[-]"
item_ext_desc[15892] = "打開禮包後可獲得限時30天的時裝—青花裁雲。[-]"
item_ext_desc[15901] = "[ffffff]使用後可獲得稀有幻化-雀羽天蟬。[-]"
item_ext_desc[15902] = "[ffffff]使用後可獲得稀有幻化-冥魂黯羽。[-]"
item_ext_desc[15919] = "西風吹散白鷗群，秋色平分碧海雲。[-]\n[e76041]收藏後暴擊傷害+2%[-]"
item_ext_desc[15920] = "西風吹散白鷗群，秋色平分碧海雲。[-]"
item_ext_desc[15921] = "打開禮包後可獲得限時7天的時裝—碧海聽濤。[-]"
item_ext_desc[15922] = "[ffffff]使用後可免費自由兌換噗噗、應龍、破天、絕影中的一種。[-]\n[e76041]兌換券可在拍賣行交易。\n兌換後獲得的坐騎不可交易。[-]"
item_ext_desc[15925] = "[ffffff]鱗介尊神龍，走獸宗麒麟。[-]\n[e76041]使用之後獲得稀有坐騎—麒麟之靈。[-]"
item_ext_desc[15929] = "[ffffff]獲得一張神·呂布卡牌。[-]"
item_ext_desc[15930] = "[ffffff]獲得一張神·貂蟬卡牌。[-]"
