item_ext_desc[16012] = "[ffffff]可領取稱號<拾艾者·二>。[-]\n[e76041]裝備後可獲得主動屬性\n物理防禦+80\n生命+6400[-]"
item_ext_desc[16013] = "[ffffff]打開後可隨機獲得光羽、寶珠囊·地、春秋遺物·攻戰、魂魄包·人、煉妖包·地和5級寶石禮包。概率獲得龍旗，用於參加端午節活動。更有幾率獲得稀有坐騎萌瑪、稀有坐騎阿寶、全新法器火玲瓏和全新時裝金觥。[-]"
item_ext_desc[16014] = "[ffffff]打開後可隨機獲得3至4級隨機寶石、2級保底符、3級保底符、高級鎖定符、龍紋金元、2級體力丹*4、龍旗和夜明珠。更有極小概率獲得綁定稀有坐騎薔薇、綁定稀有坐騎銀風和綁定神羽幻化流光玄羽。[-]\n坐騎出售後可獲得25本地術殘卷。\n神羽出售後可獲得25本通靈神冊。[-]"
item_ext_desc[16024] = "[ffffff]別人笑我太癡呆，我汪他人看不穿。[-]\n[e76041]使用之後獲得稀有坐騎—二哈。[-]"
