item_ext_desc[16316] = "[ffffff]神聖寵物--海盜船長。[-]\n[e76041]使用1：打開後獲得紫色品質的寵物——海盜船長。\n使用2：打開後將無法在拍賣行交易。[-]\n[00ff00]海盜船長是神聖的寵物，必然能夠提升本職業對應的元素屬性攻擊。[-]"
