item_ext_desc[16323] = "[ffffff]流行在探寶者之間的一種象徵[-]\n[e76041]使用：使用後可獲得10積分，積分可在王城服裝店老闆處兌換獎品。[-]\n[ffff00]至於為什麼是在服裝店老闆處兌換？企劃似乎也解釋不清楚……[-]"
item_ext_desc[16324] = "[ffffff]一份古舊的老式地圖。[-]\n[e76041]作用：進入珍寶樓更深處的地圖。\n該道具請妥善保存，可用于後續珍寶樓活動。[-]"
