item_ext_desc[16589] = "[ffffff]一張神奇的符紙。[-]\n[e76041]使用：可自由兌換吉祥、破山·神、阿寶、薔薇中的一種。[-]\n[00ff00]限制：兌換券可在拍賣行交易，兌換後獲得的坐騎不可交易。[-]"
