item_ext_desc[16592] = "[ffffff]撲扇雙翼亦淩天，列紋四足難棄食。[-]\n[e76041]使用:可獲得稀有坐騎—獵空。[-]"
item_ext_desc[16635] = "[ffffff]我只是一塊碎片，積少成多可以獲得一個完整的“我”。[-]\n[e76041]使用：集齊100個此道具可合成1個綁定且完整的赤虹坐騎。[-]\n[00ff00]限制：通過合成獲得的赤虹是綁定的，無法上架拍賣行。[-]"
item_ext_desc[16636] = "[ffffff]一個神奇的禮袋，打開似乎能獲得很多好東西。[-]\n[e76041]使用1：必定獲得1個龍紋金元。\n使用2：隨機獲得魂魄包·人、魂魄包·地、光羽囊·人、光羽囊·地、精華囊·人、夜明珠、高級鎖定符、寶玉囊·人和通靈神冊。更有概率獲得全新稀有坐騎獵空和稀有坐騎飛炎。[-]"
item_ext_desc[16637] = "[ffffff]累計消費活動中所獲得稱號。[-]\n[e76041]使用：可獲得稱號“齊國公”\n主動屬性：生命+1000，法術防禦+20\n被動屬性：生命+500，法術防禦+10[-]"
