item_ext_desc[16640] = "[ffffff]集齊100個此碎片可合成一個完整的“我”。\n我可是神獸寵物蛋噢。[-]\n[e76041]\n使用：通過合成可獲得完整的巫師貓寵物蛋。[-]\n[00ff00]\n合成獲得巫師貓寵物蛋是綁定的，無法上架拍賣行。[-]"
