item_ext_desc[17242] = "[ffffff]傳記：冰雪皓凝霜，罩夜微涼。花明月暗夜未央，輕紗籠霧映羅裳。玲瓏榻上，素手舉杯盈酒香。\n今宵幾度難忘，花有清香，酒訴衷腸，絲竹鼓樂聲聲唱，聞燕舞鶯啼，賞星燭飛雪，不羨鴛鴦。[-]\n[e76041]\n使用:可獲得稀有坐騎—戀席。[-]"
item_ext_desc[17243] = "[ffffff]傳記：西北海外，有大荒之地，飛沙環繞，有山而不合，山外兩異獸守之，常人不能靠近。有英勇驍猛者潛入其中，見山內為一處上古之地，奇珍異獸遍佈，花草樹木無一不備，奇之。\n      攜一不知名幼獸歸去，不過十載，幼獸高壯如山，其面如龍，其聲如雷，威風凜凜，故取名龍威。\n[-]\n[e76041]使用:可獲得稀有坐騎—龍威。[-]"
item_ext_desc[17246] = "[ffffff]散發著神秘的力量。[-]\n[e76041]可以用來升級秘笈。[-]"
