item_ext_desc[17248] = "[ffffff]元宵節快樂！[-]\n[e76041]使用1：必定獲得1個龍紋金元。\n使用2：必定獲得1個元宵餡料。\n使用3：隨機獲得5級寶石禮包、人皇遺篇、上古兵策、上古兵卷、上古兵書、通靈神冊、通靈神章、靈妖魂魄。更有較低概率獲得稀有坐騎龍威、稀有坐騎如意。[-]"
item_ext_desc[17249] = "[ffffff]這是一個神秘的禮匣，裡面似乎有很多好東西。[-]\n[e76041]使用：隨機獲得4級寶石禮包、3級寶石禮包、春秋遺物·勝戰、春秋遺物·敵戰、3級隨機銘文、寶玉、精華囊·人。更有概率獲得稀有坐騎鎏光、稀有坐騎飛炎。[-]"
item_ext_desc[17250] = "[ffffff]黃帝之時，神農氏嘗百草並登載各種草石功效，相傳有續命功效。[-]\n[e76041]使用：可啟動秘笈《神農本草》。\n滿級屬性：生命+100000\n                 攻擊+4000\n                 物理防禦+1250\n                 法術防禦+1250\n滿級技能：生命低於30%時，自動恢復60%血量，此效果每50秒最多觸發一次[-]"
