item_ext_desc[17262] = "[ffffff]傳記：蠻夷族好戰，韌百物以為兵。得一奇獸，其狀如牛，蒼黑，一角，博聞者稱其為兕。\n周身覆以金盔，百兵不侵，所向披靡。然兕生性兇惡，唯超群絕倫，武藝高強者方可馴服。\n華夏人才濟濟，終有一人收其為坐騎，此後百戰百捷，名震天下。念敵皆懼兕強悍勇猛之姿，\n故改名為悍勇，望後世善用之。[-]\n[e76041]使用:可獲得稀有坐騎—悍勇。[-]"
