item_ext_desc[17267] = "[ffffff]乃曹操總結半生軍事生涯、在前人基礎上總結並創新軍事理論的成果。[-]\n[e76041]使用：可啟動秘笈《孟德新書》。\n滿級屬性：風元素攻擊+4165\n                 火元素攻擊+4165\n                 水元素攻擊+4165\n                 雷元素攻擊+4165\n滿級技能：擊敗敵對玩家時，立即清空所有技能冷卻，此效果每70秒最多觸發一次。[-]"
item_ext_desc[17268] = "[ffffff]春秋時孫武所著，共十三篇，兵學聖典，能大幅提升修習者戰鬥能力。[-]\n[e76041]使用：可啟動秘笈《孫子兵法》。\n滿級屬性：生命+100000\n                 攻擊+4000\n                 物理防禦+1240\n                 法術防禦+1240\n滿級技能：暴擊時，增加自身當前20%攻擊力，持續3秒，此效果每隔15秒最多觸發一次。[-]"
item_ext_desc[17269] = "[ffffff]戰國時縱橫家鼻祖“鬼穀子”王詡所著，力求“變動陰陽”，從而達到“以柔勝剛”的目的。[-]\n[e76041]使用：可啟動秘笈《鬼穀子》。\n滿級屬性：風元素攻擊+4165\n                 火元素攻擊+4165\n                 水元素攻擊+4165\n                 雷元素攻擊+4165\n滿級技能：被控制時，立即解除控制狀態並在接下來3秒內免疫控制，此效果每60秒最多觸發一次。[-]"
item_ext_desc[17270] = "[ffffff]治兵以信，求聖以奇。信不可易，戰無常規。可握則握，可施則施。千變萬化，敵莫能知。[-]\n[e76041]使用：可啟動秘笈《八陣總述》。\n滿級屬性：生命+100000\n                 攻擊+4000\n                 物理防禦+1240\n                 法術防禦+1240\n滿級技能：生命值低於50%時，6秒內增加50%傷害減免，此效果每隔40秒最多觸發一次。[-]"
