item_ext_desc[17305] = "[ffffff]傳記：世有龍，能大能小，能升能隱；大則興雲吐霧，小則隱介藏形；升則飛騰於宇宙之間，隱則潛伏于波濤之內。\n龍吟威嚎召電閃雷鳴，龍尾撼空掀驚濤駭浪。出則化形載物奔騰，入則遁影天地無痕。\n若君心有包藏宇宙之機,吞吐天地之志，青騰躍影，蛟龍化形，甘為君用。[-]\n[e76041]\n使用:可獲得稀有坐騎—躍影。\n[e76041]\n出售:可獲得25本地術殘卷。[-]"
