item_ext_desc[17321] = "[ffffff]傳記：北山之上，多奇獸。有獸焉，面若瑾玉，星辰北斗披身，其狀如馬，其音如濤聲奔騰，雙翼，以金玉為食，見人則飛。\n展翼翱翔，則如流雲，如落星，其疾如風馳電掣，朝夕之間，可行萬里。\n得之，如禦浩瀚星辰，天地暢行。聲勢赫奕，群星讓路，故名奕星。[-]\n[e76041]\n使用:可獲得稀有坐騎—奕星。[-]"
item_ext_desc[17322] = "[ffffff]夜裡風雨聲，花落知多少。[-]\n[e76041]收藏:傷害加深+2%[-]"
item_ext_desc[17327] = "[ffffff]燭光點點，祭奠英靈。[-]\n[e76041]使用：可在地上放置一支持續十分鐘的蠟燭。[-]"
item_ext_desc[17328] = "[ffffff]桃花樓大廚特製美食，芝麻餡，豆沙餡，蛋黃餡……好像還有其他口味。游商正在收購此類道具，根據六龍慶典介面描述，尋找游商兌換好禮吧！[-]\n[e76041]使用：品嘗青團！[-]\n[00ff00]限制：每天僅可使用3次，使用間隔5分鐘。[-]"
item_ext_desc[17332] = "[ffffff]傳記：我公輸一脈自周起，謹承祖師教誨，研習機關偃術，日夜辛勞，未曾懈怠。時逾百年，終集百家之大成，制得一機關偃獸，取星隕之鐵以為骨，西南不燃之木以為身，內注北海鮫人之膏油，燃之，可令周身覆火，百年不熄。蒙祖師恩典，百煉成鋼，偃獸化靈，攻城破甲，戰無不勝，得之可定乾坤[-]\n[e76041]\n使用:可獲得稀有坐騎—鋼牙。[-]"
