item_ext_desc[17336] = "[ffffff]清明節活動中所獲得的稱號。[-]\n[e76041]使用：可獲得稱號“清明雨上”\n主動屬性：物理攻擊+400，法術攻擊+400\n被動屬性：物理攻擊+200，法術攻擊+200[-]"
item_ext_desc[17340] = "[ffffff]傳記：地之所載，六合之間，四海之內，照之以日月，經之以星辰，紀之以四時，要之以太歲，天地有序，各有司之。極北之山，定昏，可聞嚎聲四起，\n月夜之下，有影穿行，此夜遊神也，為天帝候夜，司北山紀序。聞其聲，不敢會其面，會其面，踟躇不敢言，故世人不知其形，不解其名，\n此間一二，皆傳聞矣。[-]\n[e76041]\n使用:可獲得稀有坐騎—夜神。[-]"
item_ext_desc[17341] = "[ffffff]傳記：一朝風起潮難平，世有琳琅照夜影。西海之南，流沙之濱，赤水之後，黑水之前，有大山，名曰昆侖之丘，有神，名西王母。昆侖頂峰巨雲垂天，不見日光，\n西王母以雪為材，以豹為形，造神獸琳琅，琳琅周身亮如金輪，於昆侖之巔日夜奔騰，自此，昆侖如亮長明之燈，日夜不熄。[-]\n[e76041]\n使用:可獲得稀有坐騎—琳琅。[-]"
item_ext_desc[17342] = "[ffffff]傳記：章帝章和元年，西域長史班超擊莎車，大破之。月氏國遣使獻扶拔、獅子，世人未嘗見，奇之。其形似虎，正黃，有髯耏，尾端茸毛大如鬥。\n帝心甚悅，特使專人飼之，帝嘗言，此物珍異威猛，世間少有，當歸英豪。時逾百年，風雲變幻，蛟龍失水，唯獅之珍異未曾變，天懸地隔，令人唏噓。[-]\n[e76041]\n使用:可獲得稀有坐騎—獅純。[-]"
