item_ext_desc[17359] = "[ffffff]傳記：自平王起，蕞爾小國林立，夾萬乘之間，研長技以自保。襄王二十四年，令國巧匠禦木為兵，制一木甲獸。長二尺八寸，\n重八斤六兩，磁榫驅之，纖巧靈活，迅捷如電，輕盈若雲，嘗用以刺敵情，報憂患。因其形如狐，故後世稱其為雲狐。[-]\n[e76041]\n使用:可獲得稀有坐騎—雲狐。[-]"
