item_ext_desc[17377] = "[ffffff]傳記：大荒之北，有熊。性兇悍，以百獸為食，好獨居。元年五月，天帝命飛禽走獸各選其王，以為領袖，百獸歡騰，奔相走告，設擂臺，勝者為王，熊族亦然。北之熊，勇猛無雙，於大荒之北脫穎而出，決戰南之熊，二獸爭鬥數百回合，勝負難分，惺惺相惜，互為兄弟，共治熊族。[-]\n[e76041]\n使用:可獲得稀有坐騎—熊大。[-]"
item_ext_desc[17378] = "[ffffff]傳記：大荒之南，有熊。性溫順，喜食百穀，好群居。元年五月，天帝命飛禽走獸各選其王，以為領袖，百獸歡騰，奔相走告，設擂臺，勝者為王，熊族亦然。南之熊，通謀略，於大荒之南脫穎而出，決戰北之熊，二獸爭鬥數百回合，勝負難分，互為兄弟，共治熊族。[-]\n[e76041]\n使用:可獲得稀有坐騎—熊二。[-]"
