item_ext_desc[17399] = "[ffffff]我喊你一聲，你敢答應麼？[-]\n[e76041]使用：可獲得新法器——鴻蒙[-]"
item_ext_desc[17401] = "[ffffff]傳記：日月星辰，萬物序之。冥境昭暗，何以維之？自有生滅，天地如是。追溯太古，何由考之？起自鴻蒙，生於湯穀，居於扶桑，隕於虞淵。其身如昭昭白日，耀耀輝光，其魂如幽幽冥火，魔焰焚心，化而為豹，冷焰燃身，窺其平生形貌，可知萬物自長由生，興衰之九則。已矣哉！[-]\n[e76041]\n使用:可獲得稀有坐騎—冷焰。[-]"
item_ext_desc[17538] = "[ffffff]傳記：遙在西南，有翠雲山，煙霞宿潤，苔蘚新青，林棲彩鳳，水隱蒼龍，有仙子居其中。仙子以碧玉為骨，琉璃作衣，制得玲瓏寶扇，揮之可呼風喚雨。然仙子刁蠻乖戾，為試寶扇，於林間焚大火，置百姓性命於不顧，扇化靈，逸之，仙子悔過，晚矣，此後百年再不得見。[-]\n[e76041]使用:可獲得稀有坐騎—青碧。[-]"
item_ext_desc[17539] = "[ffffff]累計消費活動中所獲得稱號。[-]\n[e76041]使用：可獲得稱號“申國公”\n主動屬性：生命+1000，法術防禦+20\n被動屬性：生命+500，法術防禦+10[-]"
