item_ext_desc[17541] = "[ffffff]芳與澤其雜糅兮，羌芳華自中出。[-]\n[e76041]收藏:水元素防禦 +100[-]"
item_ext_desc[17542] = "[ffffff]勇往直前活動稱號。[-]\n[e76041]使用：可獲得稱號“鴻鵠之志”。\n主動屬性：物理攻擊+800，法術攻擊+800\n被動屬性：物理攻擊+400，法術攻擊+400[-]"
item_ext_desc[17544] = "[ffffff]傳記：西山經華山之首，曰錢來之山，西三百里，曰陰山。有獸焉，曰天狗，其狀如狸而白首，其音如榴榴，可以禦凶。天狗所止地盡傾，餘光燭天為流星，長數十丈，其疾如風，其聲如雷，其光如電。世人未嘗得見，只聞是長風嘯月，霧漫塵寰，心有畏懼，惴惴不敢雲。\n[-]\n[e76041]\n使用:可獲得稀有坐騎—嘯月。[-]"
item_ext_desc[17545] = "[ffffff]這是一個神秘的禮匣，裏面似乎有很多好東西。[-]\n[e76041]使用：隨機獲得3級寶石禮包、4級寶石禮包、2級保底符、3級保底符、高級鎖定符、上古兵卷、精華囊·人。更有概率獲得稀有坐騎芊芊、稀有坐騎破天。[-]"
item_ext_desc[17547] = "[ffffff]一個似乎有著傳承的遺物，聽說打開能獲得很多好東西。[-]\n[e76041]打開後概率獲得夜明珠、寶玉囊·人、魂魄包·人、魂魄包·地、光羽囊·人、光羽囊·地、精華囊·人、通靈神冊、高級鎖定符，有較小概率獲得全新稀有坐騎青碧和秘笈“孟德新書”。每包必得龍紋金元。[-]"
item_ext_desc[17548] = "[ffffff]傳記：北有寒山，趠龍赩只。代水不可涉，深不可測只。水下有魚，身長不知幾千里，居北境極寒之地，破冰而生，長於虞淵，逆行若水，翻尾起浪，覆尾成洪，巨浪滔天，因其振滔洪水，上薄空桑，天帝降責，囚於星漢，其身星光燦燦，匿行雲海中，抬頭可見。[-]\n[e76041]使用:可獲得稀有坐騎—閬淵。[-]"
item_ext_desc[17549] = "[ffffff]傳記：能贏，能贏，全部都能打贏！我看著圖鑒前面那些看起來兇神惡煞的坐騎，認真估量著我們之間的實力差距。沒有一個能打的。等將軍把我放出來，我就把它們全部打倒，一個不留！什麼？小毛驢？我才不是一般的毛驢！我是驥驁，驥驁，驥驁！等著吧！讓你看看我的威力！[-]\n[e76041]使用:可獲得稀有坐騎—驥驁。[-]"
