item_ext_desc[17616] = "[ffffff]傳記：自張騫使西域，絲綢之路連接了不同語言，不同膚色的人。滾滾黃沙下，掩埋了無數旅人的印記，有人為財而去，有人為情而來。相傳，大秦有一女子，戀上賽裏斯使者，為尋戀人，隻身前往絲國，途中為匈奴人所害，其魂魄化為羊，項上系鈴，徘徊於大漠間，只盼與戀人再次相遇。[-]\n[e76041]使用:可獲得稀有坐騎—妮娜。[-]"
