item_ext_desc[17628] = "[ffffff]傳記：京郊孫家，以養豬為業。某日得一只奇豬，通體粉嫩，伶俐精秀，能通人語，取名玲瓏。孫家長子孫念之與玲瓏交情甚厚，如親如朋。前線吃緊，念之代其父從徭役，遠赴邊境，此去數年，杳無音信。玲瓏銜一束鮮花，於家門前日日等候，盼其歸來。[-]\n[e76041]使用:可獲得稀有坐騎—玲瓏。[-]"
