item_ext_desc[17630] = "[ffffff]大喬稀有兌換商店可兌換物品。[-]\n[e76041]使用：可獲得馬草*100。[-]\n[00ff00]限制：每日可使用龍紋金元兌換3次。[-]"
item_ext_desc[17635] = "[ffffff]傳記：天下不可無制，矩不正，不可以為方；規不正，不可以為員；身者，事之規矩也。有神獸曰石司，制律法，司寰宇，掌六合，石身而三首，三首各司其職，一首司明，二首司德，三首司法，公正嚴明，石面無私。石司日行穹宇，夜宿黃泉，和道三世，作刑六界，故敬畏之。[-]\n[e76041]使用:可獲得稀有坐騎—石司。[-]"
item_ext_desc[17636] = "[ffffff]傳記：天下不可無制，矩不正，不可以為方；規不正，不可以為員；身者，事之規矩也。有神獸曰石紀，監王道，行教化，法萬物，石身而三首，三首各司其職，一首紀明，二首紀德，三首紀法，公正嚴明，石面無私。石紀日行穹宇，夜宿黃泉，和道三世，作刑六界，故敬畏之。[-]\n[e76041]使用:可獲得稀有坐騎—石紀。[-]"
item_ext_desc[17637] = "[ffffff]打開後必定獲得1個龍紋金元，隨機獲得魂魄包•人、魂魄包•地、光羽囊•人、光羽囊•地、精華囊•人、通靈神冊、高級鎖定符、寶玉囊•人、夜明珠。必定獲得龍旗，綁定狀態隨機，用於參加端午節活動。更有概率獲得全新坐騎石司、稀有坐騎驥驁。[-]"
item_ext_desc[17638] = "[ffffff]打開後可隨機獲得3至4級寶石禮包、2至3級保底符、高級鎖定符、龍紋金元、夜明珠、魂魄碎片。概率獲得龍旗，用於參加端午節活動。更有幾率獲得稀有坐騎噗噗和稀有坐騎淩月。[-]"
