item_ext_desc[17657] = "[ffffff]傳記：北有寒山，曰鐘山。鐘山之神銜燭以照太陰，蓋長千裏，視為晝，瞑為夜，吹為冬，呼為夏。太陰之境稱居冥國，國在寒冰之下，冰雪萬物。有獸名惑心，形似羊，雙翼，其音如嬰孩，誘人而食，其食者可七魄不朽。修道者嘗尋其蹤跡，以求得魂魄不朽之術。[-]\n[e76041]使用:可獲得稀有坐騎—惑心。[-]"
item_ext_desc[17658] = "[ffffff]無邊的暗夜，空氣中彌漫著血的氣息。[-]\n[e76041]使用：可獲得稀有神羽幻化-暗夜之息。[-]"
item_ext_desc[17659] = "[ffffff]數此卻無卿傲世，看來唯有我知音。[-]\n[e76041]收藏:暴擊傷害+2%[-]"
item_ext_desc[17660] = "[ffffff]對花對酒，落梅成愁，十裏長亭水悠悠。[-]\n[e76041]收藏:風元素防禦+100[-]"
item_ext_desc[17662] = "[ffffff]傳記：居冥境內，冰雪覆之萬物，孕成百獸，皆以冰為骨，以雪為皮，喜霜寒。居冥以南，曰昌寧之山，其上少草木，多山石。有獸焉，形似狐，雙翼，展翼而飛，倏忽千萬裏。性高潔，嘗匿冰晶石林中，不多見。其音如清風穿竹，細雨潤田，聞之可心神寧靜，忘卻憂愁，故人稱其為寧韻。\n[-]\n[e76041]使用:可獲得稀有坐騎—寧韻。[-]"
item_ext_desc[17663] = "[ffffff]一個神秘的禮匣，打開似乎能獲得很多好東西。[-]\n[e76041]使用1：必定獲得1個龍紋金元。\n使用2：隨機獲得3級隨機寶石、4級隨機寶石、5級隨機寶石、6級隨機寶石、靈妖魂魄、通靈神冊、3級寵物口糧。更有概率獲得全新稀有坐騎寧韻和稀有坐騎悍勇。[-]"
