item_ext_desc[17676] = "[ffffff]傳記：凡世間萬物，陰陽相對，有盛則有衰，有茂則有疏。居冥境中，草木繁盛，飲食豐饒之地謂之居；淒冷荒蕪，環境惡劣之地謂之冥。冥界百獸相屠以求自保，生而凶煞。有獸謂之寒戮，形似狼，周身亦覆冰晶，銳利如槍刃，為居冥境中一方霸主，自是張狂，睥睨太陰。[-]\n[e76041]使用:可獲得稀有坐騎—寒戮。\n[e76041]出售:可獲得25本地術殘卷。[-]"
item_ext_desc[17677] = "[ffffff]墨影如羽，輕眉淺笑。[-]\n[e76041]使用：可獲得稀有神羽幻化-墨影璃裳。[-]"
item_ext_desc[17722] = "[ffffff]傳記：妖怪者，蓋精氣之依物者也。氣亂於中，物變於外，形神氣質，表裏之用也，本於五行，通於五事，消息升降，化動萬端。鴆者，毒鳥也，其羽化酒，飲之即死。鴆之影修而為靈，脫凡體，匿行跡於山川水泊中，布散毒沼之氣，生人不敢近。[-]\n[e76041]使用:可獲得稀有坐騎—鴆影。[-]"
