item_ext_desc[17753] = "[ffffff]這是一個神秘的禮盒，裏面似乎有很多好東西。[-]\n[e76041]使用：隨機獲得4級寶石禮包、3級寶石禮包、春秋遺物·勝戰、春秋遺物·敵戰、3級隨機銘文、寶玉、精華囊·人。更有概率獲得稀有坐騎盈秋、稀有坐騎朱蛤。[-]"
item_ext_desc[17755] = "[ffffff]傳記：整片沙漠，沒有比我跑得更快的動物了！啦啦啦啦，我，就是速度之王，是這片沙漠的大名鳥！停停停，那是什麼東西，竟然跑得比我快，還不用休息？！被超過了我還怎麼出名？魔什麼駝車？誰駝的車？我不管，我也要變成魔駝車，我也要駝車。你們誰也別想超過我！[-]\n[e76041]使用:可獲得稀有坐騎—奇諾。[-]"
