item_ext_desc[17765] = "[ffffff]傳記：如果讓凡人掌握了雷電之力，那麼天上的神明將永遠得不到安寧，因為他們得到一點力量都會賣弄他的威風；而神是慈悲的，他用雷電去懲罰作惡之人，不會傷害路邊一朵可憐的野花。權力如同雷電，如果當權者沒有神的慈悲，那就讓我用雷電來懲罰他們吧！。[-]\n[e76041]使用:可獲得稀有坐騎—尼祿。[-]"
