item_ext_desc[17782] = "[ffffff]傳記：冉冉青煙，妙香拂慮，燈影無照，心向禪道。永平年間，有事木工者，技藝超絕，善制機關獸，其獸兇猛如虎，血戮屠殘，以一敵百，時人無不畏之。機關獸本無善惡，罪在驅使者，木工自知罪重，自後暮鼓晨鐘，不問世事，求不生不死之寂靜安穩。[-]\n[e76041]使用:可獲得稀有坐騎—寂滅。[-]"
item_ext_desc[17783] = "[ffffff]取天地之精華，鑄法器以鳳璃。[-]\n[e76041]使用：可獲得新法器——鳳璃[-]"
item_ext_desc[17784] = "[ffffff]迷迷糊糊的小喜鵲，在背包中嘰嘰喳喳叫個不停。[-]\n[e76041]把它交給鵲仙吧，好搭起鵲橋，讓牛郎織女想相見。[-]"
item_ext_desc[17785] = "[ffffff]喜鵲掉落的一根羽毛，在陽光下泛著五彩斑斕的光澤，似乎會帶來好運。[-]\n[e76041]獲取：七夕活動開啟期間，完成九龍鼎、火燒敵營、刺探、無間道等任務均可獲得鵲之羽。\n使用：玄兒正在收集這種羽毛，可以向他換到不少好東西。[-]"
item_ext_desc[17786] = "[ffffff]夕窗香思發，風影欲篝紗。[-]\n[e76041]收藏:雷元素防禦+100[-]"
item_ext_desc[17787] = "[ffffff]日暮沙漠陲，力戰煙塵裏。[-]\n[e76041]收藏:風元素防禦+100[-]"
item_ext_desc[17789] = "[ffffff]傳記：江山一望多少年，夢裏還鄉魂不知。綿綿烽火接連天，萬卷家書無蹤還。人生如寄，紙短情長，烽闕玲瓏，內藏玄機。春秋時，魯為楚所滅，大軍壓境，屍橫遍野，哀嚎聲不絕於耳。樓宇宮闕皆焚，黑雲遮天，不見五指。公輸後人制機關烽闕，警後世莫忘此景，莫棄此仇。[-]\n[e76041]使用:可獲得稀有坐騎—烽闕。[-]"
item_ext_desc[17790] = "[ffffff]我願乘風化彩霞，萬丈虹光披金甲；\n靜看伊人舞芳華，燭下緋影俏江南。[-]\n[e76041]使用：可獲得稀有神羽幻化-虹光緋影。[-]"
item_ext_desc[17792] = "[ffffff]傳記：嘿！你是新來的船長嗎？別傻站著，快坐上來吧，時間不等人，我這就帶你回船上去！海上還有好多好玩新鮮的東西等著你領我們去看呢！水手們，水手們，水手們！都打起精神，我們的船長來了，帶著好酒好菜，收起錨，揚起帆，我們要遠航了！[-]\n[e76041]使用:可獲得稀有坐騎—祿力。[-]"
item_ext_desc[18081] = "[e76041]翠帷雙卷出傾城，龍劍破匣雙月明。[-]"
