item_ext_desc[18131] = "[ffffff]傳記：蝶舞翩翩，花語鳥言，盈盈盛放，餘音繞梁。昔在幼時，始齔韶年，兩小無知，笑語盈盈。時如奔流，白駒過隙，牆內佳人，院外少年，紙鳶寄情，歌樂傳意，竹馬青梅，今夢如故。[-]\n[e76041]使用:可獲得稀有坐騎—故夢。[-]"
item_ext_desc[18132] = "[ffffff]傳記：英雄少年，志在江山，背井離鄉，功成不返。紅箋小字，訴盡平生，鴻雁在雲，如魚在水，此情難寄，此意難平。猶記當年，寒蟬淒切，對長亭晚，相顧無言，蝶舞如故，花香依然，物是人非，只歎流年。[-]\n[e76041]使用:可獲得稀有坐騎—流年。[-]"
item_ext_desc[18172] = "[ffffff]一個神秘的禮匣，打開似乎能獲得很多好東西。[-]\n[e76041]使用1：必定獲得1個龍紋金元。\n使用2：必定獲得5個迷糊的喜鵲。\n使用3：隨機獲得坐騎包•地、通靈神冊、通靈神章、上古兵策、上古兵卷、上古兵書、魂魄碎片、小妖魂魄、靈妖魂魄。更有概率獲得全新稀有坐騎故夢和稀有坐騎尼祿。[-]"
item_ext_desc[18173] = "[ffffff]這是一個神秘的禮盒，裏面似乎有很多好東西。[-]\n[e76041]使用：隨機獲得4級寶石禮包、3級寶石禮包、3級保底符、2級保底符、高級鎖定符、上古兵卷、精華囊•人。更有概率獲得稀有坐騎望舒、稀有坐騎姿韻。[-]"
