item_ext_desc[18184] = "[ffffff]傳記：陌上桑桑，其如畫。喜卷金鈴，笑意盈盈，金光貴氣四散，身影難辨，身影難辨。異域遠渡，卻不隨俗，中土風情未見，總是新鮮，總是新鮮。且看桑陌自在遊，王城宮築，京郊小路，嚮往人間喧囂處，駝鈴聲響，我蹄聲長，天下焉能識我耶？[-]\n[e76041]使用:可獲得稀有坐騎—桑陌。[-]"
