item_ext_desc[18474] = "[ffffff]傳記：孝桓帝時，眾仙與會東海，降於海濱酒肆，掌櫃備佳餚侍之。觥籌交錯間，有女子攜一怪物騰雲而至。坐定，女子雲：接侍以來，已見東海三為桑田,今東海又淺於往者，見龍子擱於淺灘，故助之，取名玄奕。他仙笑言：如此，東海行複揚塵也，此子甚幸。[-]\n[e76041]使用:可獲得稀有坐騎—玄奕。[-]"
item_ext_desc[18475] = "[ffffff]荼蘼已謝情未了，紛紛擾世何時消。[-]\n[e76041]使用：可獲得稀有神羽幻化-雀翎。[-]"
