item_ext_desc[18510] = "[ffffff]傳記：奸佞當道，蠻夷入境，此內憂外患之時，實當肅清政治，內懲國賊，外禦強敵，重振我上國之威嚴。然聖上年少，聽信奸佞。忠臣良將，有心治國，無力回天。將軍遠征塞外，風沙埋忠骨，其心不死，其魂化為戰馬，遠望國土，怨不得平。[-]\n[e76041]使用:可獲得稀有坐騎—戰魂。[-]"
item_ext_desc[18511] = "[ffffff]神龍祭祀活動稱號。[-]\n[e76041]使用：可獲得稱號“神龍使者·十七”\n主動屬性：生命+3000，物理防禦+60\n被動屬性：生命+1000，物理防禦+20[-]"
