item_ext_desc[18514] = "[ffffff]打開後獲得紫色品質的聖級寵物——青龍寶寶。[-]\n[e76041]青龍寶寶是聖級寵物，必然能夠提升本職業對應的元素屬性攻擊，初始可獲得3個3級以上寵物技能，整體屬性比神級寵物有很大幅度提升。[-]\n[00ff00]打開後將無法在拍賣行交易。[-]"
item_ext_desc[18525] = "[ffffff]傳記：風聲鶴唳，草木萋萋，疆場鐵馬複軍行。弦月漸滿，風綠兩川，桑田古路人未還。功名利祿，過眼雲煙，多少年，只見功成名將無數，也見馬革裹屍為國死。戎馬一生，昭昭心願，求得是，蕩平賊寇天下安。[-]\n[e76041]使用:可獲得稀有坐騎—戎昭·聖。[-]"
item_ext_desc[18526] = "[ffffff]傳記：遙遙無盡，盼有榮歸，將軍沙場秋點兵。星河兩漢，家鄉路遠，錦書難寄無複還。生生死死，過眼雲煙，多少年，只見功成名將無數，也見馬革裹屍為國死。戎馬一生，昭昭心願，求得是，早日還鄉報平安。[-]\n[e76041]使用:可獲得稀有坐騎—戎昭·神。[-]"
item_ext_desc[18527] = "[ffffff]銀鞍照白馬，颯遝如流星。[-]\n[e76041]收藏:傷害減免+2%[-]"
