item_ext_desc[18547] = "[ffffff]一個神秘的劍匣，隱隱能聽到裏面傳來的聲音。[-]"
item_ext_desc[18548] = "[ffffff]一個神秘的寶箱，裏面似乎裝著一些不錯的東西。[-]"
item_ext_desc[18552] = "[ffffff]傳記：力量是什麼？有人力大無窮，扛鼎百斤，戰敗為寇；有人型瘦體弱，手無縛雞之力，但能指揮三軍，談笑間，檣櫓灰飛煙滅。我雖然金牌加身，但仍抵不過第二種人。為了變得更強，我只能遠渡重洋，尋找真正的力量。[-]\n[e76041]使用:可獲得稀有坐騎—赤炎·聖。[-]"
item_ext_desc[18553] = "[ffffff]傳記：上、你們都上，我才不怕你們！想我縱橫草原十五年，從來沒遇到過一個勢均力敵的對手，這次來中原，就是想見識一下山外是不是有還有山，天外是不是還有天，袋鼠外面，是不是還有別的袋鼠！[-]\n[e76041]使用:可獲得稀有坐騎—赤炎·神。[-]"
item_ext_desc[18554] = "[ffffff]傳記：世有靈騎，其名青輝，周身青焰繚繞，面若惡鬼修羅，令人望而生畏，然其性溫和，生於三途川上，長於彼岸花海，不需眠，不需休，不需飲，不需食。曆冥火，戰修羅，百劫成靈，渡世人苦海間。[-]\n[e76041]使用:可獲得稀有坐騎—青輝。[-]"
item_ext_desc[18556] = "[ffffff]一個神秘的禮匣，打開似乎能獲得很多好東西。[-]\n[e76041]使用1：必定獲得1個龍紋金元。\n使用2：必定獲得1個國之髓。\n使用3：隨機獲得3級隨機寶石、4級隨機寶石、5級隨機寶石、6級隨機寶石、靈妖魂魄、通靈神冊、3級寵物口糧、4級寵物口糧、5級寵物口糧。更有概率獲得全新稀有坐騎“長明·聖”和稀有坐騎“繪池·聖”。[-]"
item_ext_desc[18557] = "[ffffff]這是一個神秘的禮盒，裏面似乎有很多好東西。[-]\n[e76041]使用：隨機獲得4級寶石禮包、3級寶石禮包、春秋遺物•勝戰、春秋遺物•敵戰、3級隨機銘文、寶玉、精華囊•人。更有概率獲得稀有坐騎“竹趣”、稀有坐騎“蒼禦”。[-]"
