item_ext_desc[18565] = "[ffffff]尊敬的天使大人，您是喜歡喝甜的還是鹹的？[-]\n[e76041]使用：可獲得稀有神羽幻化-嗜血天使。[-]"
item_ext_desc[18567] = "[ffffff]傳記：先有天機後有地，鴻萌初世畛崖際。蒼莽六界千萬年，一朝等得清濁辨。吞星摘月倒乾坤，傾山覆海翻天地。欲知此身何處去，且問盤古從何意。其實……我才不會說它叫鴻萌只不過是因為長得比較萌。[-]\n[e76041]使用:可獲得稀有坐騎—鴻萌。[-]"
item_ext_desc[18568] = "[ffffff]六龍爭霸三周年慶集字活動兌換稱號。[-]\n[e76041]使用：可獲得稱號“三載相伴”。\n主動屬性：物理攻擊+600，法術攻擊+600\n被動屬性：物理攻擊+300，法術攻擊+300[-]"
