item_ext_desc[18573] = "[ffffff]傳記：秋近天寒風去暖，公孫樹黃，雁南飛忙。恰是閒暇登高時，憑欄遙看，天高遠闊，星漢迢迢，牛郎織女兩相望。有鳥盻瑤，落羽無歸，一雙孤翅，禽飛、樹枯、葉黃。只待春歸，天暖、花開、歸鄉。[-]\n[e76041]使用:可獲得稀有坐騎—盻瑤。[-]"
item_ext_desc[18574] = "[ffffff]傳記：在遙遠的地方，大地金黃，綿延無邊，與藍色的天空相接，那是一片被稱作沙漠的地方。在沙漠的最深處，埋藏著無數寶藏，有遠古的亡靈守護。尊敬的勇士啊，你是否願意與我一同去未知的遠方冒險，尋找傳說的寶藏？[-]\n[e76041]使用:可獲得稀有坐騎—斐亞。[-]"
item_ext_desc[18575] = "[ffffff]一個神秘的禮匣，打開似乎能獲得很多好東西。[-]\n[e76041]使用1：必定獲得1個龍紋金元。\n使用2：隨機獲得坐騎包•地、通靈神冊、通靈神章、上古兵策、上古兵卷、上古兵書、魂魄碎片、小妖魂魄、靈妖魂魄。更有概率獲得全新稀有坐騎“斐亞”和稀有坐騎“豚豚”。[-]"
