item_ext_desc[18597] = "[ffffff]一個神秘的禮匣，打開似乎能獲得很多好東西。[-]\n[e76041]使用1：必定獲得1個龍紋金元。\n使用2：隨機獲得坐騎包•地、通靈神冊、通靈神章、上古兵策、上古兵卷、上古兵書、魂魄碎片、小妖魂魄、靈妖魂魄。更有概率獲得全新稀有坐騎“焱奕”和稀有坐騎“斐亞”。[-]"
item_ext_desc[18598] = "[ffffff]這是一個神秘的禮盒，裏面似乎有很多好東西。[-]\n[e76041]使用：隨機獲得4級寶石禮包、3級寶石禮包、3級保底符、2級保底符、高級鎖定符、上古兵卷、精華囊•人。更有概率獲得稀有坐騎“海棠”、稀有坐騎“晴洺”。[-]"
item_ext_desc[18600] = "[ffffff]傳記：生存還是毀滅？這對我來說不是一個問題。我自無盡的業火中來，穿越佈滿荊棘的路，忍受了狂暴的命運無情的摧殘，忍受了那鞭打和嘲弄，又在苦難中重生，我，就是命運！[-]\n[e76041]使用:可獲得稀有坐騎—焱奕。[-]"
