item_ext_desc[18620] = "[ffffff]傳記：長風破浪會有時，直掛雲帆濟滄海。我再說一遍，長風破浪會有時，直掛雲帆濟滄海！所以船長啊，只要咱們沿著渭水一路向西，總有一天會開到海上去的，我經驗豐富，不會騙你的。[-]\n[e76041]使用:可獲得稀有坐騎—封禹。[-]"
