item_ext_desc[18635] = "[ffffff]傳記：將軍快看！是沒見過的新鮮玩意！好像是從什麼不列什麼顛傳過來的圖紙，經過本朝能工巧匠歷時數十年潛心打造，史無前例，獨一無二，行如清風穿林，可比那飛騎車輿強上許多！[-]\n[e76041]使用:可獲得稀有坐騎—浩塵。[-]"
