item_ext_desc[18646] = "[ffffff]傳記：神女降世，留禦坐於人間。觀其形，翩若驚鴻，婉若游龍，髣髴兮若輕雲之蔽月，飄飄兮若流風之回雪，所行處，留金光燦燦，銀星點點，輕行搖影，足往神留，遺情想像，顧望懷愁。[-]\n[e76041]使用:可獲得稀有坐騎—浮盻。[-]"
item_ext_desc[18647] = "[ffffff]傳記：一紙相思，兩處別愁，忍不住三言兩語，滾滾愁情，四方來襲。明心見性，照見五蘊皆空，六根清淨，心非取相，拋卻七情。人非聖賢，縱有八鬥之才，怎敵那良辰美景，九十春光？百般愁怨，化作千萬思緒，飛越千城來寄。[-]\n[e76041]使用:可獲得稀有坐騎—千城。[-]"
item_ext_desc[18655] = "[ffffff]紫鸞無近遠，黃雀任翩翾。[-]\n[e76041]使用：可獲得稀有神羽幻化-紫鸞翩翾。[-]"
item_ext_desc[18656] = "[ffffff]疏影橫斜水清淺，暗香浮動月黃昏。[-]\n[e76041]收藏:暴擊傷害+2%[-]"
item_ext_desc[18658] = "[ffffff]傳記：黃帝出鴻蒙，斬蚩尤，教四方，平天下。功成名就，雲遊四海。乘天黿渡東洋，見帝國，名印加，有神秘精怪，沐風浴光而生，飲露食泥而漲，力大無窮，果實甘甜，養一方之土，育一城之民，眾人感其恩惠，祭之拜之，視為祖獸。[-]\n[e76041]使用:可獲得稀有坐騎—加祖。[-]"
item_ext_desc[18659] = "[ffffff]一個神秘的禮匣，打開似乎能獲得很多好東西。[-]\n[e76041]使用1：必定獲得1個龍紋金元。\n使用2：隨機獲得3級隨機寶石、4級隨機寶石、5級隨機寶石、6級隨機寶石、東周卡包•無雙、三國卡包•無雙、3級寵物口糧、4級寵物口糧、5級寵物口糧。更有概率獲得全新稀有坐騎“加祖”和稀有坐騎“焱奕”。[-]"
