item_ext_desc[18671] = "[ffffff]傳記：唯及渡舫增飛願，帝政君心達意時。舟行江河，舵掌清波，展翼輕搖，逐浪江海。青波翠庭，小樓煙雨，過而不入。此行不為江山走，欲上蓬萊攬飛鳥，瓊樓玉宇，皎皎明月，一去殷勤為探看。[-]\n[e76041]使用:可獲得稀有坐騎—青雀舫·聖。[-]"
item_ext_desc[18672] = "[ffffff]傳記：舊時多逸客，舟行江河，舵掌清波，展翼輕搖，倏忽間，踏遍千里江山，欲遊八荒六合。青波翠庭，小樓煙雨，盡入眼底，為盡遊興，一朝諭令通濟渠，怎管那鰥寡煢獨，百姓的坎坷！[-]\n[e76041]使用:可獲得稀有坐騎—青雀舫·神。[-]"
item_ext_desc[18673] = "[ffffff]一個神秘的禮匣，打開似乎能獲得很多好東西。[-]\n[e76041]使用1：必定獲得1個龍紋金元。\n使用2：必定獲得1個火雞骨頭。\n使用3：隨機坐騎包•地、4級保底符、3級保底符、上古兵策、上古兵卷、上古兵書、魂魄碎片、小妖魂魄、靈妖魂魄。更有概率獲得全新稀有坐騎“青雀舫·聖”和稀有坐騎“加祖”。[-]"
