item_ext_desc[18681] = "[ffffff]各位父老鄉親兄弟姐妹，今天米婭初到貴寶地，不料沉迷貴地美食，盤纏全部吃光，故在此賣藝，望各位有錢的捧錢場，沒錢的捧人場！先謝過大家,大恩大德，我來生做熊做馬，報答各位！[-]\n[e76041]使用:可獲得稀有坐騎—米婭。[-]"
