item_ext_desc[18690] = "[ffffff]傳記：曹魏得巨象，相欲知其重，幼子沖以船土之法得，相喜其聰智，賜幼象予沖，沖曰：“世人常說幼時了了，大未必佳，望象名曰了了，常警醒兒臣莫要自得，望父王恩准”，丞相大喜，稱其謙遜，賜象名：了了。[-]\n[e76041]使用:可獲得稀有坐騎—了了。[-]"
