item_ext_desc[18701] = "[ffffff]傳記：說起來我是真的倒楣。聽說賽裡斯有聖誕老人發禮物，特地偷偷從家裡趕過來看看，結果就打個盹的功夫，天上“哐當”砸下來那麼大個的一艘船！誰幹的，到底是誰幹的！？[-]\n[e76041]使用:可獲得稀有坐騎—覆焉·神。[-]"
item_ext_desc[18702] = "[ffffff]傳記：說起來我也是真的倒楣。從拉普蘭德大老遠開船來賽裡斯，一路上搶、一路上辛辛苦苦搜了那麼點寶藏，就出去抽根煙的功夫，我的船呢？我的寶藏呢？我剛停這的，那麼大個的船呢！？[-]\n[e76041]使用:可獲得稀有坐騎—覆湮·聖。[-]"
