item_ext_desc[18733] = "[ffffff]傳記：新羅王子金喬覺，看破紅塵，攜白犬浮海來華，削髮為僧，偕同苦修七十五載，日夜相隨。白犬曉佛理，通人性，避邪惡，善聽人心，可辨世間萬物。地藏偈贊雲：“稽首本然淨心地，無盡佛藏大慈尊”，故名諦聽。[-]\n[e76041]使用:可獲得稀有坐騎—諦聽。[-]"
