item_ext_desc[18760] = "[ffffff]傳記：北國風霜多凜冽，苦寒一夜，枯木生花。湖映孤亭，月照軒窗，書卷盈箱篋，鏡奩滿紅妝。百無聊賴獨倚欄，忽見金光灑天，綠意拂面，驚起方覺夢一場，徒留綠葉滿地，如嗅春意。[-]\n[e76041]使用:可獲得稀有坐騎—嗅春。[-]"
