item_ext_desc[18768] = "[ffffff]傳記：漠北有神獸，狼首而馬身，其鬃如獅，其角如犀，口生利齒，黑身金紋，踏焰而行，可以禦凶。其聲厲如鴞，然其性忠厚，善戰而能人言，天下治則隱，天下亂則見，常擇豪傑而相伴，以供驅馳，或化人形為忠臣良將，救民於水火，故名曰丹心。[-]\n[e76041]使用:可獲得稀有坐騎—丹心。[-]"
