item_ext_desc[18783] = "[ffffff]傳記：數九飛雪得天地恩寵，乃生神識，化為一雪人，性情溫厚，體態豐腴。京郊百姓苦於嚴寒，雪人憐之，故身負寶匣，踏雪橇，馳于原野，遇人則以禮相贈。西域商賈甚異之，以其為神祇，呼其名曰珊塔。[-]\n[e76041]使用:可獲得稀有坐騎—珊塔。[-]"
item_ext_desc[18784] = "[ffffff]傳記：什麼？你要去塞北，害怕雪太大沒法趕路？包在我身上！我可是土生土長的北方狗，祖上是強壯的森林狼，這麼點小雪才擋不住我！你就安安心心的坐在車上吧，看我一騎絕塵，踏雪如飛！[-]\n[e76041]使用:可獲得稀有坐騎—飛飛。[-]"
