item_ext_desc[18816] = "[ffffff]傳記：這裡好美的景致，讓鹿不禁想吟詩一首！北國風光，千里冰封，萬里雪飄。 望長城內外，惟餘莽莽；大河上下，頓失……唉？我的朋友們呢？可惡！我的朋友們被帶到哪去了？[-]\n[e76041]使用:可獲得稀有坐騎—迷鹿。[-]"
