item_ext_desc[18851] = "[ffffff]傳記：山巔寒，立神壇。受天命，報天成。順民心，薦樂聲。志上達，歌下迎。祈佳歲，佑豐稔。浩浩九州，威威華夏，禮敬山川，拜謝滄海，萬世奮飛，天下志同。[-]\n[e76041]使用:可獲得稀有坐騎—寒嘯·神。[-]"
item_ext_desc[18852] = "[ffffff]傳記：山巔寒，立聖壇。饗日月，貢八荒。承眷命，牧蒼生。奏讚歌，舞善曲。興百業，滿福緣。浩浩九州，威威華夏，禮敬山川，拜謝滄海，萬世奮飛，天下志同。[-]\n[e76041]使用:可獲得稀有坐騎—寒嘯·聖。[-]"
item_ext_desc[18853] = "[ffffff]傳記：踏雲留影月下魂，半點星光半掩痕。兒時舊夢乘風去，不見清風載夢歸。春半還家孤影人，煢煢踽踽獨徘徊。醉裡看花霜照影，飛虹展翼載故人。半醉半醒一夢間，縱是癡心也團圓。[-]\n[e76041]使用:可獲得稀有坐騎—飛虹。[-]"
item_ext_desc[18854] = "[ffffff]傳記：路上堵車實在是太嚴重了，絕對不是因為我沉迷採花耽誤了行程。如果沒在春節前回家，請記得為我準備棗泥豆沙紅果五仁三十一種口味風味湯圓，我們一起鬧元宵。[-]\n[e76041]使用:可獲得稀有坐騎—逐光。[-]"
