item_ext_desc[18901] = "[ffffff]傳記：報告！村民們在長江邊上發現一個怪獸，身長丈餘，披鱗覆甲，大嘴一張，可以吞下一個人！軍師說這怪物叫鼉，生在長江裡，凶得很，但是經過屬下一頓狠揍，它被馴得服服帖帖，保證能帶您跋山涉水，成為一只好坐騎！[-]\n[e76041]使用:可獲得稀有坐騎—潛淵。[-]"
