item_ext_desc[19008] = "[ffffff]傳記：雪落天寒染塵寰，一山歸去一山殘。深淵遠嘯驚徹骨，震落飛花霜雪染。猩目橫眉千秋歲，金甲罩身時荏苒。仰望幽空明月彎，俯見鏡湖深入潭。此身不畏孤寂寥，願護林山一世間。[-]\n[e76041]使用:可獲得稀有坐騎—雪鬃。[-]"
