item_ext_desc[19030] = "[ffffff]傳記：我曾經暢遊淵海，見魚兒成群，珊瑚如林，與龍宮太子手談對弈。我也曾經翱翔天際，穿越雲海，與飛鳥齊驅。如今造訪人間，只聽世人有言：北、北北冥有魚，其名為鯤，鯤之大，一鍋燉、燉不下。[-]\n[e76041]使用:可獲得稀有坐騎—雲瀾。[-]"
item_ext_desc[19031] = "[ffffff]傳記：嘎嘎嘎，切克嘎，我是這裡最帥的鴨。場下的各位看官老爺，請跟著我的節奏一起搖擺，舉起手來，大聲地唱，如果我是迪傑，丞相會愛我嗎？曹操會愛我嗎？阿瞞會愛我嗎？[-]\n[e76041]使用:可獲得稀有坐騎—迪傑。[-]"
