item_ext_desc[19060] = "[ffffff]傳記：臨滄海而遠望兮，桑田千頃而獨留。托鴻雁以寄思兮，往者而不可與期。此身生而無盡兮，命定煢煢而悵惘。願禦風而暢行兮，又無羽翼而高翔。故承濤而載波兮，隨龍行者以歸潮。[-]\n[e76041]使用:可獲得稀有坐騎—承鈞。[-]"
