item_ext_desc[19076] = "[ffffff]傳記：公輸世家，以機關偃術、奇巧之技盛名於世。志在天下者無不敬之，奉之。然嫉恨者亦不在少數，與取而代之。公輸先人制機甲無雙，金甲覆身，刀槍不入，以庇後世子孫。[-]\n[e76041]使用:可獲得稀有坐騎—無雙。[-]"
item_ext_desc[19077] = "[ffffff]傳記：星河遙歎九重天，銀漢兩去望不穿。漢宮繾綣春宵度，馬嵬一別生死間。巧畫難留紅顏俏，掩面淚流感嫿仙。點墨仙鶴載君王，乘夜飛渡奈何岸。亦真亦幻淚闌珊，蓬萊仙島續前緣。[-]\n[e76041]使用:可獲得稀有坐騎—嫿仙。[-]"
