item_ext_desc[19111] = "[ffffff]傳記：將軍以為我所背何物？氣球？非也。將軍以為我所戴何物？帽子？非也。莊周賜我四朵彩色祥雲，祝我騰飛萬里；養由基賜我無相法鏡，助我眼觀千里。我蟄伏於此，臥薪嚐膽，為的是天下大亂時，平戰亂，定乾坤。[-]\n[e76041]使用:可獲得稀有坐騎—戲斑。[-]"
