item_ext_desc[19123] = "[ffffff]傳記：禦風馳行狩獵場，穹頂為倉地為疆。虎獸豺狼不足懼，威如落葉隨風去。飛雪揚沙草木折，日曝郊野水焦涸。凡人閉戶祈天意，百獸遊走尋蔭庇。粗毛刺花骨查牙，風獵迎難踏危揚。[-]\n[e76041]使用:可獲得稀有坐騎—風獵。[-]"
