item_ext_desc[19149] = "[ffffff]傳記：你有沒有聽過一首民歌？江南可採蓮，蓮葉何田田。魚戲蓮葉間。魚戲蓮葉東，魚戲蓮葉西，魚戲蓮葉南，魚戲蓮葉北。但其實，魚並沒有玩，它們在很認真地拉著蓮葉！[-]\n[e76041]使用:可獲得稀有坐騎—憐影·神。[-]"
item_ext_desc[19150] = "[ffffff]傳記：水陸草木之花，可愛者甚蕃。予獨愛蓮之出淤泥而不染，濯清漣而不妖，中通外直，不蔓不枝，香遠益清，亭亭淨植，可遠觀而不可褻玩焉。出入平安！魚兒如是說。[-]\n[e76041]使用:可獲得稀有坐騎—憐影·聖。[-]"
item_ext_desc[19151] = "[ffffff]傳記：行雲染墨素纖塵，冰蓮飛渡九重門。凡間錦繡欲何從，去來羽問花不知。天地逍遙憑去處，凡塵阡陌掩花痕。神仙自在無暖意，不及人間溫情深。[-]\n[e76041]使用:可獲得稀有坐騎—莫塵。[-]"
