item_ext_desc[19191] = "[ffffff]傳記：桃花潭水深千尺，不及胡蘿蔔好吃。天長地久有時盡，胡蘿蔔綿綿無絕期。花開堪折直須折，胡蘿蔔堪吃直須吃。春色滿園關不住，一地胡蘿蔔鑽出來。將軍你看見我的胡蘿蔔了嗎？[-]\n[e76041]使用:可獲得稀有坐騎—靈素。[-]"
