item_ext_desc[19197] = "[ffffff]傳記：清鈴裹帶綹靈寰，躍影扶風葉不安。金甲綬帶刀光冷，劈川斬江累飲泉。身在蓬萊望九州，漂泊一去忘流年。神風驃馬不足行，影葉歸林臥景亭。[-]\n[e76041]使用:可獲得稀有坐騎—隱葉。[-]"
item_ext_desc[19198] = "[ffffff]一個神秘的禮匣，打開似乎能獲得很多好東西。[-]\n[e76041]使用1：必定獲得1個龍紋金元。\n使用2：隨機獲得3級隨機寶石、4級隨機寶石、5級隨機寶石、6級隨機寶石、東周卡包•無雙、三國卡包•無雙、3級寵物口糧、4級寵物口糧、5級寵物口糧。更有概率獲得全新稀有坐騎“隱葉”和稀有坐騎“風獵”。[-]"
