item_ext_desc[19204] = "[ffffff]傳記：建安二十年，我奉曹丞相之命前往竇家池為戰士們派發禮物。戰火紛飛，路途險峻，我克服重重困難來到此地，絕對不是迷路才到這的。附：現求一名好心人帶我去竇家池，必有重謝！[-]\n[e76041]使用:可獲得稀有坐騎—淺悠。[-]"
item_ext_desc[19205] = "[ffffff]傳記：西元二一五年五月，天氣晴，無風，適合飛行。魔法掃帚帶本喵來到了一個完全陌生的地方，語言不通，文字不通，街上的人穿的是什麼奇怪的衣服，袍、襜褕、襦、裙、裾都是什麼喵？[-]\n[e76041]使用:可獲得稀有坐騎—巫夢。[-]"
