item_ext_desc[19238] = "[ffffff]傳記：古時一舉人，赴京中途於村落休憩，與借宿之女暗生情愫，奈何另日趕考，匆忙留書一封，怎料女子為家人所迫，下嫁他方。舉人歸來，悔之晚矣，親手制“求凰”，以示心意，後人傳念。[-]\n[e76041]使用:可獲得稀有坐騎—求凰·神。[-]"
item_ext_desc[19239] = "[ffffff]傳記：古有“求凰”之念傳遞，世人以之拜念求得婚約得成，經久之後賦予其些許靈智，被其選上之人必得心念婚姻，直至今日金時，騎乘之人，無不應那句——“身無彩鳳雙飛翼，心有靈犀一點通”。[-]\n[e76041]使用:可獲得稀有坐騎—求凰·聖。[-]"
