item_ext_desc[19246] = "[ffffff]傳記：很多時候，斑寶更喜歡在巢穴裡休息，但是它不得不外出，身為工蜂，它需要收集花粉和花蜜，照顧蜂王，守護蜂巢，沒有休息的時間。“為什麼我要一直這麼努力？”，某一天，它突然產生了這樣的疑問，於是它離開了巢穴，飛向了更加自由的天空。[-]\n[e76041]使用:可獲得稀有坐騎—斑寶。[-]"
