item_ext_desc[19254] = "[ffffff]傳記：思居很小的時候就有一個闖蕩江湖的夢想，可惜它太戀家了，還沒走出幾步，就會想起它溫暖的小窩，柔軟的小床，還有它的好朋友們。一想到要離開這些，思居就感到太捨不得了！於是它想了個好辦法，那就是背著它的小窩和朋友們，一起去旅行！[-]\n[e76041]使用:可獲得稀有坐騎—思居。[-]"
item_ext_desc[19255] = "[ffffff]一個神秘的禮匣，打開似乎能獲得很多好東西。[-]\n[e76041]使用1：必定獲得1個龍紋金元。\n使用2：隨機獲得3級隨機寶石、4級隨機寶石、5級隨機寶石、6級隨機寶石、東周卡包•無雙、三國卡包•無雙、3級寵物口糧、4級寵物口糧、5級寵物口糧。更有概率獲得全新稀有坐騎“思居”和稀有坐騎“巫夢”。[-]"
item_ext_desc[19256] = "[ffffff]柳葉鳴蜩綠暗，荷花落日紅酣。[-]\n[e76041]收藏:水元素防禦+100[-]"
item_ext_desc[19258] = "[ffffff]傳記：東風一夜花千樹，逐繡球，銜錦緞。冰糖葫蘆香滿路，嬉鬧正歡，笑語不斷，一夜魚龍舞。披金戴紅踏雪去，同福攜樂尋蹤來。眾裡尋它千百度，驀然回首，五花肉卻在，燈火闌珊處。[-]\n[e76041]使用:可獲得稀有坐騎—旺卿。[-]"
