item_ext_desc[19280] = "[ffffff]傳記：曾有一富商，癡迷那剔透的月色，又苦於其虛無縹緲，無法觸摸，於是取極北之地不化的寒冰，請能工巧匠打造為一輪彎月的模樣，取名瓊華。怎想工匠最後一銼完畢之時，那瓊華便愈發晶瑩，最終化為清亮的光芒，回歸天空。[-]\n[e76041]使用:可獲得稀有坐騎—瓊華·神。[-]"
item_ext_desc[19281] = "[ffffff]傳記：那是嫦娥玉簪上的一抹流光，帶著星星做的步搖，悄悄隨著落霞和晚風，墜入凡塵，化為人們夢中幽微的倩影。無數人循著它曾經的蹤跡，苦苦求而不得，最終只剩心頭那片永恆潔白的月色。“人道海水深，不抵相思半。”[-]\n[e76041]使用:可獲得稀有坐騎—瓊華·聖。[-]"
