item_ext_desc[19389] = "[ffffff]傳記：舊時戰亂，有一江南女子，已七年未見參軍的夫君一面，思念愈發深重，每逢七夕，她就用梧桐木精心雕刻成鵲鳥模樣，供奉在香案前，希望七姐能讓這只鳥兒帶著她的思念，飛向遠方身處邊關的夫君。[-]\n[e76041]使用:可獲得稀有坐騎—惜巧·神。[-]"
item_ext_desc[19390] = "[ffffff]傳記：承載著思念和愛意的木鳥得到了神仙的垂憐，七姐的淚珠落在它身上，讓它化為一隻真正的鳥兒乘風而飛。流轉的晚霞和晨曦托起鳥兒的羽翼，助它飛越九十九重山河，最終將女子的思念帶給遠方的良人。[-]\n[e76041]使用:可獲得稀有坐騎—惜巧·聖。[-]"
item_ext_desc[19391] = "[ffffff]一個神秘的禮匣，打開似乎能獲得很多好東西。[-]\n[e76041]使用1：必定獲得1個龍紋金元。\n使用2：必定獲得5個迷糊的喜鵲。\n使用3：隨機獲得魂魄包•人、魂魄包•地、光羽囊•人、光羽囊•地、精華囊•人、通靈神冊、高級鎖定符、寶玉囊•人、夜明珠。更有概率獲得全新稀有坐騎湍君·聖和稀有坐騎諦麟·聖。[-]"
item_ext_desc[19392] = "[ffffff]這是一個神秘的禮盒，裡面似乎有很多好東西。[-]\n[e76041]使用：隨機獲得4級寶石禮包、3級寶石禮包、3級保底符、2級保底符、高級鎖定符、上古兵卷、精華囊•人。更有概率獲得稀有坐騎“鋼牙”、稀有坐騎“冷焰”。[-]"
