item_ext_desc[19405] = "[ffffff]傳記：曾有一鼠修行千年而得碩大體型，一步可以躍千里。據說他行了無數日夜，去到海的另一頭，在一個史書裡完全沒有記載的國度學習他們的語言和文化，學成歸來後的他一身西裝革履，還給自己起了外國名字，成為了族裡見識最廣的鼠！[-]\n[e76041]使用:可獲得稀有坐騎—派克。[-]"
