item_ext_desc[19414] = "[ffffff]從思勤布下的迷陣中找到的香水，散發著淡淡的異香，似乎有奇異的效果，偶爾會從瓶子裡聽到若有若無的“嘎嘎”聲。[-]\n[e76041]變身道具。\n冷卻時間：10秒。[-]"
item_ext_desc[19416] = "[ffffff]傳記：如果你想請人調查些什麼，找我就對了。我雖然不敢自稱中原最好的偵探，但也小有名氣。不要著急，請坐，來，喝了這杯紅茶，將事件的經過向我慢慢訴說。記住，不要放過任何一件小事，因為線索往往隱藏在最容易被忽略的細節中！[-]\n[e76041]使用:可獲得稀有坐騎—華森。[-]"
