item_ext_desc[19436] = "[ffffff]傳記：東海有紫玉，溫潤通透，輕如紫霞，飄飄而欲飛。取一丈見方之玉，雕琢為舟。其狀如元寶，金披翠冠，貴氣盈盈，富麗堂皇，榮華無雙。得之可以聚天下財，日進鬥金，乘之可以平步青雲，如日方升，實屬稀世之寶！[-]\n[e76041]使用:可獲得稀有坐騎—盈寶。[-]"
item_ext_desc[19437] = "[ffffff]油紙傘撐起細雨如絲，朦朦朧朧又是一方江南。[-]\n[e76041]使用：可獲得新法器——煙雨。[-]"
item_ext_desc[19438] = "[ffffff]打開後獲得紫色品質的聖級寵物——金毫靈貓。[-]\n[e76041]金毫靈貓是聖級寵物，必然能夠提升本職業對應的元素屬性攻擊，初始可獲得3個3級以上寵物技能，整體屬性比神級寵物有很大幅度提升。[-]"
item_ext_desc[19439] = "[ffffff]思勤贈予的大禮包，鼓鼓囊囊的，似乎包著許多好東西。[-]\n[e76041]使用1：必定獲得24個小妖魂魄，1個地術殘卷和1個變身道具“奇異香水”。\n使用2：隨機獲得20馬草或100馬草，有可能獲得變身道具“珍稀異香”。[-]"
item_ext_desc[19441] = "[ffffff]誰能春獨愁，對此徑須飲。[-]\n[e76041]收藏:風元素防禦+100[-]"
item_ext_desc[19443] = "[ffffff]傳記：漫漫櫻華，飄飄裙袂，初晨朱筆點紅妝。花乘流水傳春信，日暮東風暗香遠。喈喈金鈴，錚錚鐘鼓，麻衣如雪弄清影。輕歌巧韻祈豐年，悠悠繞梁不絕音。[-]\n[e76041]使用:可獲得稀有坐騎—麻衣。[-]"
