item_ext_desc[19452] = "[ffffff]傳記：相傳南海深處居住著蛟人，他們紡織蛟綃，馴養蛟龍。這只珍獸自南海中來，周身環繞煙波氣泡，健壯溫馴，披鱗覆甲，淡淡的青光變幻流轉，如同海水潮起潮落，頗具靈氣。漁民甚異之，都以為它是蛟龍，只要騎上它，就可以暢遊深海，前去尋找傳說中鮫人的故鄉。[-]\n[e76041]使用:可獲得稀有坐騎—聽瀾。[-]"
item_ext_desc[19453] = "[ffffff]傳記：昔年中原鬧鼠患，糧食顆粒無收，農民們無計可施，絕望中向山神祈禱。誰知第二天，自山中跑出一隻巨大的白狐，毛色如同清冷的月光，當人們都以為它要像傳說中的妲己那樣危害世間時，白狐卻只是在受災的村子裡遊蕩了一圈，氾濫成災的老鼠就全都嚇破了膽，消失無蹤。[-]\n[e76041]使用:可獲得稀有坐騎—觀月。[-]"
item_ext_desc[19454] = "[ffffff]一個神秘的禮匣，打開似乎能獲得很多好東西。[-]\n[e76041]使用1：必定獲得1個龍紋金元。\n使用2：隨機獲得坐騎包•地、大量光羽、3級保底符、上古兵策、上古兵卷、上古兵書、魂魄碎片、小妖魂魄、靈妖魂魄。更有概率獲得全新稀有坐騎“聽瀾”和稀有坐騎“華森”。[-]"
