item_ext_desc[19476] = "[ffffff]傳記：雲鬢花顏，綾羅輕幔，幾支珠與翠，佳人巧笑媚千行。幽幽暗香，瀟瀟細雨，一柄油紙傘，為伊消得人憔悴。[-]\n[e76041]使用:可獲得稀有坐騎—薇雨·神。[-]"
item_ext_desc[19477] = "[ffffff]傳記：香腮冰潔，美目流盼，靈秀自相成，凝眸似水驚鴻影。青絲浸墨，豐唇朱染，深夏煙波裡，纖妍窈窕羞薔薇。[-]\n[e76041]使用:可獲得稀有坐騎—薇雨·聖。[-]"
