item_ext_desc[19484] = "[ffffff]傳記：一名來自西域的美女商人獻上一隻狀如田鼠的巨大珍獸，珍獸身上披掛著用紅纓裝飾的異國鐵甲。根據無名氏所著的《西方諸國查考》記載，這只珍獸來自一個名為羅馬的國家，是該國進行“角鬥”活動時使用的戰獸，戰力可敵一百精兵。若能將其編入軍中，必將使我軍如虎添翼！[-]\n[e76041]使用:可獲得稀有坐騎—列奧。[-]"
item_ext_desc[19489] = "[ffffff]一枚雕刻著精緻鳥紋的鑄鐵錢幣，散發著淡淡的光澤，在中原十分罕見。[-]\n[e76041]獲得：2019年雙十一活動開啟期間，通過“六龍慶典”中“誠心祈緣”介面進行簽到獲得。\n使用：2019年雙十一活動開啟期間，集齊六枚“西域鐵錢，可以”通過“六龍慶典”中“誠心祈緣”介面兌換專屬稱號。[-]\n[ffff00]“這樣東西是兌換大獎的唯一憑證，還請將軍妥善保管，遺失不補哦。”——段瑢[-]"
item_ext_desc[19490] = "[ffffff]涉江采芙蓉，蘭澤多芳草。[-]\n[e76041]收藏:傷害減免+2%[-]"
item_ext_desc[19494] = "[ffffff]傳記：在西方國度的傳說裡，有一種如獅子般龐大的鷹頭巨獸，擁有司掌風雨的神力。當這巨獸飛上天空時，太陽都被它的羽翼遮蔽，頃刻便會烏雲密佈，風雨交加。而當它收斂翅膀，落回地上時，天空又會霎時放晴。人們稱這巨獸為“幽嵐”，敬畏著它的神力。[-]\n[e76041]使用:可獲得稀有坐騎—幽嵐·神。[-]"
item_ext_desc[19495] = "[ffffff]傳記：西方曾有無數小國，各國之間戰爭頻發。某年一個國家鬧了旱災，戰事吃緊，眼看就要被吞併。王子不甘於滅國的命運，獨自前去尋找傳說中司掌風雨的巨獸，並願意獻上性命換取巨獸的協助。巨獸被王子的誠懇感動，招來風雨緩解了旱災。最終王子成為了國王，國家也在巨獸的守護下長久興盛。[-]\n[e76041]使用:可獲得稀有坐騎—幽嵐·聖。[-]"
item_ext_desc[19496] = "[ffffff]傳記：我曾馱著一匹匹絲綢，踏著一座座山峰，走在天與沙的邊界線上，細嫩的綠草是我的枕席，蜿蜒的河流是我的床幔。我可以帶你沿著絲綢之路前往西方遙遠的國度，去看神秘的獅身人面像，欣賞落日餘暉裡的金字塔。這正是“駝鈴悠悠，前路漫漫”！[-]\n[e76041]使用:可獲得稀有坐騎—牧塵。[-]"
