item_ext_desc[19524] = "[ffffff]傳記：你可曾聽說西南險峻的山嶺深處，有一種壯猛如熊的食鐵之獸？哼哼哼，說的就是本寶寶！我可是國寶，怎麼樣，是不是很厲害？還不快把鮮嫩的竹筍獻上來！嗚嗷！不要捏本寶寶的耳朵！嗚……我認輸！放過我的耳朵行不行？我可以把我最寶貝的小竹椅讓給你坐。[-]\n[e76041]使用:可獲得稀有坐騎—圓圓。[-]"
item_ext_desc[19525] = "[ffffff]傳記：聽說人類寫下無數詩句讚美秋日，要我說，詩裡的景色也只不過是驚鴻一瞥，真正的秋天美景只有我才知道。當你能舒服地躺在家中，看著窗外的秋風裡，蘑菇在萌發，青苔在滋長，天高雲淡，腐草為螢，那時你也會覺得，在真正的自然面前，讚美的詩句竟然如此貧瘠與俗氣！[-]\n[e76041]使用:可獲得稀有坐騎—居萌。[-]"
