item_ext_desc[19600] = "[ffffff]傳記：桀桀桀……讓本大人來猜猜你的口袋裡有幾顆糖？一顆，兩顆？統統放進這盞南瓜燈裡！快點快點，“不給糖果就搗亂”！桀桀桀，收了你的糖，你就是本大爺罩著的人了。穿上你最嚇人的衣服，一起去讓那些膽小鬼驚聲尖叫吧！[-]\n[e76041]使用:可獲得稀有坐騎—海德。[-]"
item_ext_desc[19601] = "[ffffff]傳記：“竹板這麼一打呀，咱誇誇狗不理包子，它薄皮兒、大餡兒、十八個褶兒，它就像一朵花呀~”這位客官請留步，聽聽我的吆喝，這狗不理包子可是我們家祖傳的手藝，吃了一個還想吃，根本停不下來，許仲康大人吃了都說好！[-]\n[e76041]使用:可獲得稀有坐騎—柴柴。[-]"
item_ext_desc[19602] = "[ffffff]打開後獲得紫色品質的聖級寵物——葉楓。[-]\n[e76041]葉楓是聖級寵物，必然能夠提升本職業對應的元素屬性攻擊，初始可獲得3個3級以上寵物技能，整體屬性比神級寵物有很大幅度提升。[-]"
