item_ext_desc[19632] = "[ffffff]傳記：《西方諸國查考》中記載著這樣一種奇獸：“南國有鳥，腿細長，羽色如茜草，居於湖海之畔，飛時萬鳥齊鳴，遮天蔽日，赤翼似火，故名茜羽。”據說此鳥象徵著忠貞與深情，得之可以增長桃花運，使人情路順利，覓得佳緣。所以這奇獸前來中原，想必是為了向那些單身的將軍們送去祝福吧！[-]\n[e76041]使用:可獲得稀有坐騎—茜羽。[-]"
