item_ext_desc[19645] = "[ffffff]傳記：我在去往遠方大陸的船上遇見一個異國探險家，他送給我一塊可以計時的“懷錶”，裡面纖巧精細的機關令我佩服不已。我仿照著它重新製作了一塊，並用金線編織的蝴蝶進行裝飾。可惜以我的技術做不出那樣小巧的零件，但即使體積增大了不少，它依舊是我最得意的傑作！——來自某位元工匠的筆記。[-]\n[e76041]使用:可獲得稀有坐騎—青韶·神。[-]"
item_ext_desc[19646] = "[ffffff]傳記：我在返回家鄉的船上遇見了一個中國工匠，他向我講述了一對名為梁山伯與祝英台的眷侶，因為不能在一起，雙雙鬱鬱而終、化為蝴蝶的傳說。我醉心於東方人含蓄而淒美的愛情故事，於是請他為我的懷錶也刻上蝴蝶，我相信人與人之間的愛可以超越時間，成為不朽的傳奇。——來自某位元探險家的旅行日誌。[-]\n[e76041]使用:可獲得稀有坐騎—青韶·聖。[-]"
item_ext_desc[19647] = "[ffffff]一個神秘的禮盒，打開似乎能獲得很多好東西。[-]\n[e76041]使用1：必定獲得1個龍紋金元。\n使用2：必定獲得10點雙十一貢獻值。\n使用3：隨機獲得魂魄包·人、魂魄包·地、光羽囊·人、光羽囊·地、精華囊·人、通靈神冊、高級鎖定符、寶玉囊·人、夜明珠。更有概率獲得全新稀有坐騎“潮兮·聖”和稀有坐騎“長明·聖”。[-]"
