item_ext_desc[19663] = "[ffffff]傳記：南溟以南有山，人稱霆山，山高萬仞。一日夜裡，天上降下火雨，一顆彗星落下。隨著大地劇烈的震顫，巍峨的霆山被彗星夷為平地，只餘一塊巨大的精鐵。這塊巨鐵重數千斤，卻能懸浮于空中，能人巧匠將其煉化為鐵水，重新鑄造成坐騎，只贈予絕世英雄。[-]\n[e76041]使用:可獲得稀有坐騎—雷鳴。[-]"
