item_ext_desc[19670] = "[ffffff]傳記：歡迎來到中原馬戲之夜！我，小丑奇樂，奉遠方女王的命令，為你們帶來最驚險刺激的馬戲表演。頭頂蘋果躍過熊熊燃燒的火圈？空中飛人翻跟頭八周半？只要你們想看，我就會統統表演！但是現在，先請各位從我的尾巴上抽一張牌吧，我將展示我的絕學，小丑讀心術！[-]\n[e76041]使用:可獲得稀有坐騎—奇樂。[-]"
item_ext_desc[19671] = "[ffffff]傳記：昔有軒轅，涿鹿一戰，匡時濟世，拓土建邦，功澤百世，德潤千秋。今有玹鳶，誕於昆侖，承天靈慧，載地厚德，縱橫萬里，光耀九州。軒轅擇益友，玹鳶尋明君，癡心一往，永不相負！[-]\n[e76041]使用:可獲得稀有坐騎—玹鳶。[-]"
