item_ext_desc[19683] = "[ffffff]傳記：從幽幽的磷火中誕生出的巨龍，連吐息出的青焰都冰冷徹骨，如同自冥界歸來的怪物。巨龍盤踞在城牆之上，看守著神明賜予人們的金蘋果，只要不去刻意打擾它，它就不會傷害人類。“請每三個月為它洗一次澡，並餵食新鮮的鹿肉。”《龍類辨認及飼養手冊》上是這樣寫的。[-]\n[e76041]使用:可獲得稀有坐騎—萊頓·神。[-]"
item_ext_desc[19685] = "[ffffff]傳記：巨龍的翼翅扇出疾風，佈滿利齒的口中噴出火焰，一次次驅散那些意圖染指金蘋果的宵小之徒。有時疲憊的巨龍會趴在青石城牆上休息，但它的眼睛仍會注視周遭的一切，千載萬載，永不停息！“萊頓喜歡金閃閃的東西，請不要試圖從它的巢中偷走任何金屬物品！” 《龍類辨認及飼養手冊》上是這樣寫的。[-]\n[e76041]使用:可獲得稀有坐騎—萊頓·聖。[-]"
item_ext_desc[19686] = "[ffffff]一個神秘的禮盒，打開似乎能獲得很多好東西。[-]\n[e76041]使用1：必定獲得1個龍紋金元。\n使用2：必定獲得1個火雞骨頭。\n使用3：隨機獲得魂魄包·人、魂魄包·地、光羽囊·人、光羽囊·地、精華囊·人、通靈神冊、高級鎖定符、寶玉囊·人、夜明珠。更有概率獲得全新稀有坐騎“踏雪·聖”和稀有坐騎“潮兮·聖”。[-]"
