item_ext_desc[19698] = "[ffffff]傳記：蜀中多山，地勢險峻，重巒疊嶂，飛流如織。山川險，農人無地為耕，蜀道難，商賈無路通行，積貧積弱，民苦之久矣。蜀相孔明制金石巨蠍，平蜀山，疏渠壑，開良田，築城塞，移山倒海，墾地千里，營天府之國。民皆稱道，爭相觀望，謂之蝕川。[-]\n[e76041]使用:可獲得稀有坐騎—蝕川。[-]"
