item_ext_desc[19735] = "[ffffff]傳記：楚有善箜篌者，其名為濛。濛常攜琴泛舟于漢水之上，且行且彈，所經之處，餘音繞梁三日而不絕也。楚王好音樂，欲使濛為入宮琴師，濛弗從，遂逃秦矣。楚王命人尋之，不見其人，只得其琴，其聲悠悠如細雨，故謂之箜濛。[-]\n[e76041]使用:可獲得稀有坐騎—箜濛·神。[-]"
item_ext_desc[19736] = "[ffffff]傳記：楚王得名琴箜濛，奏樂七日，而廢朝政。楚妃樊姬憂之，諫曰：“桀醉於妺喜之瑟，故夏亡。紂醉於靡靡之音，故商亡。今君醉於箜濛，豈非凶兆也？”楚王大悟，遂藏箜濛，勤于朝政，揮師平亂，立威定霸，使楚大出於天下。[-]\n[e76041]使用:可獲得稀有坐騎—箜濛·聖。[-]"
