item_ext_desc[19793] = "[ffffff]傳記：東海有鳥焉，其名芙瑤，以琅軒美玉為食，其羽燦若流金，鳴聲錚錚而不懼人，營翡翠珍珠之巢，蠻夷巫祝以之為神鳥。芙瑤雙足健碩，幼時無翼，行於地，七年方生翼而能飛，故謂之曰：“一朝羽翼成，直上九萬里。”[-]\n[e76041]使用:可獲得稀有坐騎—芙瑤。[-]"
item_ext_desc[19794] = "[ffffff]這是一個神秘的禮盒，裏面似乎有很多好東西。[-]\n[e76041]使用：隨機獲得4級寶石禮包、夜明珠、器靈囊·地、魂魄包·人、高級鎖定符、寶珠囊·人、寶珠囊·地。更有概率獲得稀有坐騎“浩塵”、稀有坐騎“戲斑”。[-]"
item_ext_desc[19795] = "[ffffff]日神東君，太陽初升[-]\n[e76041]使用：可獲得稀有神羽幻化-東曦幻化。[-]"
item_ext_desc[19796] = "[ffffff]一個神秘的禮盒，打開似乎能獲得很多好東西。[-]\n[e76041]使用1：必定獲得1個龍紋金元。\n使用2：必定獲得1個粟米。\n使用3：隨機獲得魂魄包·人、魂魄包·地、坐騎包·人、坐騎包·地、精華囊·人、通靈神冊、高級鎖定符、寶玉囊·人、夜明珠。更有概率獲得全新稀有坐騎“隨風”和稀有坐騎“輝夜·聖”。[-]"
item_ext_desc[19797] = "[ffffff]打開後獲得紫色品質的聖級寵物——憨大狼。[-]\n[e76041]憨大狼是聖級寵物，必然能夠提升本職業對應的元素屬性攻擊，初始可獲得3個3級以上寵物技能，整體屬性比神級寵物有很大幅度提升。[-]"
item_ext_desc[19798] = "[ffffff]樽前一曲歌，歌裡千重意。[-]\n[e76041]收藏:火元素防禦+100[-]"
item_ext_desc[19799] = "[ffffff]石徑入丹壑，松門閉青苔。[-]\n[e76041]收藏:水元素防禦+100[-]"
item_ext_desc[19800] = "[ffffff]了然絕世事，此地方悠哉！[-]\n[e76041]收藏:雷元素防禦+100[-]"
item_ext_desc[19801] = "[ffffff]尋芳不覺醉流霞，倚樹沉眠日已斜。[-]\n[e76041]收藏:暴傷減免+2%[-]"
item_ext_desc[19802] = "[ffffff]關門不鎖寒溪水，一夜潺湲送客愁。[-]\n[e76041]收藏:傷害加深+2%[-]"
item_ext_desc[19803] = "[ffffff]九天閶闔開宮殿，萬國衣冠拜冕旒[-]\n[e76041]使用：可獲得稀有神羽幻化-華胥琉熒。[-]"
item_ext_desc[19806] = "[ffffff]傳記：傳記傳說在遙遠崇山的深林中，居住著能夠幻化成人形的孔雀精靈，他們個個能歌善舞，過著遠離喧囂的平靜生活。偶爾的，深林中來了迷路的登山者或砍柴人，他們便會化為孔雀，發出清脆的鳴聲，帶領迷路者重新找到回家的方向。[-]\n[e76041]使用:可獲得稀有坐騎—雲翎。[-]"
item_ext_desc[19807] = "[ffffff]傳記：東海之濱有一青苔石島，上有雕樑畫棟，唯冬月十五可見。有好事者乘船而登之，欲探究竟。方登島，忽而山搖地動，波濤乍起，有獸長吟，現一巨龜，石島乃其背。好事者大驚，落荒而逃，複而觀之，巨龜乃潛如海，不再現也。[-]\n[e76041]使用:可獲得稀有坐騎—千崇。[-]"
item_ext_desc[19808] = "[ffffff]藍色妖姬情人節排行榜獎勵[-]\n[e76041]使用：可獲得永久特效稱號“死心塌地”。\n主動屬性：物理攻擊+4000，法術攻擊+4000\n被動屬性：物理攻擊+2000，法術攻擊+2000[-]"
item_ext_desc[19809] = "[ffffff]藍色妖姬情人節排行榜獎勵[-]\n[e76041]使用：可獲得永久特效稱號“至死不渝”。\n主動屬性：物理攻擊+4000，法術攻擊+4000\n被動屬性：物理攻擊+2000，法術攻擊+2000[-]"
item_ext_desc[19820] = "[ffffff]傳記：過年最期待的是什麼？年夜飯？逛廟會？錯！當然是放煙花！兩萬響的大地紅聲震九霄，十七色的禮花彈光耀四海！什麼？還嫌不過癮？那就只能拿出秘密武器——浩息了！你看這火紅色的特製大煙花，乘上它，一飛沖天，摘星攬月，與銀河肩並肩！[-]\n[e76041]使用:可獲得稀有坐騎—浩息。[-]"
item_ext_desc[19821] = "[ffffff]傳記：左慈收到一本稀罕的畫冊，上面記述著一種貌如窮奇，卻有著鷹的喙與爪的異獸。老神仙覺得著實有趣，便用泥土和羽毛捏成這怪獸的樣子。誰知，泥模剛剛做好，一根脫落的絨毛飛進老神仙的鼻子，惹他打了個大噴嚏，一口仙氣噴在模型上，將那模型變成了活物。[-]\n[e76041]使用:可獲得稀有坐騎—沐風·神。[-]"
item_ext_desc[19822] = "[ffffff]傳記：西有異獸，似鷹而生獅身，其身白如雪，其翼緋如霞。此乃日神東君座下之獸，以雷霆閃電為食，吐息則生煙雲，櫛風沐雨，不知疲憊，忠誠不屈。此獸若振翅而飛，巨翼伸展，則紅霞漫天，若收斂雙翼，行於雲上，則天光大亮。——摘自《西夷異獸錄》[-]\n[e76041]使用:可獲得稀有坐騎—沐風·聖。[-]"
item_ext_desc[19823] = "[ffffff]傳記：嘎嗷！沒錯，我，就是兇猛的年獸！最喜歡的是玩球，曬太陽和吃東西，最討厭起早早。嘎嗷！什麼？你問是不是在哪見過我？怎，怎麼可能！我可是聽說人們慶祝新年時會準備好吃的，才偷偷跑出來的！閒話少說，再不快點，好吃的可要被吃光了！沖鴨！[-]\n[e76041]使用:可獲得稀有坐騎—沖鴨。[-]"
item_ext_desc[19824] = "[ffffff]金風玉露一相逢，便勝卻人間無數[-]\n[e76041]使用：可獲得稀有神羽幻化-初夢傾顏。[-]"
