item_ext_desc[19841] = "[ffffff]傳記：爆竹聲中一歲除，春風送暖入……入年糕！哎呀，詩句好難記，但是使命我可不會忘記，玉皇大帝命我來為大家送福啦。庚子新歲，正是韶華。新的一年裡，我會努力把連連的好運，綿綿的幸福，穩穩的健康，多多地搬進將軍家裡。這正是星樞呈瑞，鼠兆豐年！[-]\n[e76041]使用:可獲得稀有坐騎—應瑞。[-]"
