item_ext_desc[19866] = "[ffffff]傳記：居住在山中的人們之間流傳著這樣一個傳說：若是在野外遭遇狂風乍起，那就是你踏入了颶梟的領地。那是一種巨大的貓頭鷹，翅膀能長到丈餘長，每一次拍打都將掀起颶風。它是森林與崇山的守護者，只有敬畏自然的人才會受到颶梟的歡迎。[-]\n[e76041]使用:可獲得稀有坐騎—颶梟。[-]"
