item_ext_desc[19890] = "[ffffff]傳記：蘿貝一直覺得自己與眾不同。它出生在一個農民的蘿蔔田裡，卻大得像一棵樹。農民看見它，以為自己種出了千年人參。當他準備把蘿貝從地裡拔出來的時候，蘿貝用力一蹦，跳了出來，兩條又短又粗的小腿跑得飛快，一溜煙就沒了蹤影，只剩下目瞪口呆的農民。[-]\n[e76041]使用:可獲得稀有坐騎—蘿貝。[-]"
