item_ext_desc[19894] = "[ffffff]傳記：有獸翔於九天，與獬豸為伍，其名犴裔，好訟而能辨，乃忠魂義魄化而為虎形，以警世人。秦時衛鞅變法，犴裔乃現，諫曰：“言之以法，行之以公。”鞅從之，後新法初成，秦強而出於天下，始有傳言稱：“犴裔現，天下興。”[-]\n[e76041]使用:可獲得稀有坐騎—犴裔。[-]"
item_ext_desc[19895] = "[ffffff]一個神秘的禮匣，打開似乎能獲得很多好東西。[-]\n[e76041]使用1：必定獲得1個龍紋金元。\n使用2：隨機獲得坐騎包•地、大量光羽、3級保底符、上古兵策、上古兵卷、上古兵書、魂魄碎片、小妖魂魄、靈妖魂魄。更有概率獲得全新稀有坐騎“芳心”和稀有坐騎“青黛”。[-]"
item_ext_desc[19896] = "[ffffff]這是一個神秘的禮盒，裡面似乎有很多好東西。[-]\n[e76041]使用：隨機獲得4級寶石禮包、夜明珠、器靈囊·地、魂魄包·人、高級鎖定符、寶珠囊·人、寶珠囊·地。更有概率獲得稀有坐騎“烽闕”、稀有坐騎“玄奕”。[-]"
