item_ext_desc[19902] = "[ffffff]傳記：孤雲伴月寥星點，棄筆從戎已七年。金戈鐵馬關山度，破斧沉沙長河岸。長亭一別故鄉遠，不見梓裡意難安。塞外北風卷旌旗，飛雁銜書入寒天。尺素盡道相思苦，夜來難寐衷腸述。征蓬難反歸無期，佳人空候古道邊。三千青絲終成雪，此情難卻寄雲嫣。願為紫霞越昆侖，再話桑麻阡陌間。\n[-]\n[e76041]使用:可獲得稀有坐騎—雲嫣。[-]"
