item_ext_desc[19910] = "[ffffff]傳記：雪華一直盼望著春天，因為冬天裡，大地一直都被白雪覆蓋著，漫長又寂靜。只有春天剛剛來到時，她才能踩著冬的尾巴，和自己的好朋友燕兒見上一面，聽它講述從大洋彼岸帶回來的故事，然後和其他雪花一起，回歸天空的懷抱，化作春雨，化作薄霧。[-]\n[e76041]使用:可獲得稀有坐騎—雪華。[-]"
