item_ext_desc[19917] = "[ffffff]傳記：我誕生於蒲公英的花海中，各色的野花裝點起我的冠冕，輕盈的白絨是我的披風，我在一片生機勃勃中啟程，而無盡的旅途是我的歸宿。我將為蒼莽的大地送來春天的消息，也會和柔暖的風一起托著你，飛上天空，去看遠方未知的景色。[-]\n[e76041]使用:可獲得稀有坐騎—蒲仙。[-]"
item_ext_desc[19918] = "[ffffff]傳記：想當年唐僧西行的時候，遇見了俺們住的這片海，在他發愁怎樣渡海時，俺就主動請纓前去幫忙。龍王說俺幫助唐僧渡海有功，就賜了這金椅和金傘。唉呀！師父別念了！俺可沒說謊！你要是也想試試，就坐上來，俺帶你去海上兜兜風！[-]\n[e76041]使用:可獲得稀有坐騎—楓意。[-]"
