item_ext_desc[19923] = "[ffffff]傳記：我收到的幾封信上說，耶誕節的時候只有小孩子能收到禮物，長大就收不到了。這怎麼行呢？聖誕明明是讓所有人都快樂的節日。雖然慶典早已過去，但我仍決定拿上禮物，再度出發。懷著美好心願的人們啊，我會乘著初曉時分的晨光，將禮物輕放在你們床頭。[-]\n[e76041]使用:可獲得稀有坐騎—初曉。[-]"
