item_ext_desc[19930] = "[ffffff]傳記：想知道我的拿手好戲？那本魔術師就來表演一番。看見我手中的魔杖了嗎？它是我的傳家寶，有著可以讓胡蘿蔔快速生長的神奇魔力！不信你看，先把種子埋進土裡，然後跟著我左手右手畫圈圈，一起念：“胡蘿蔔呀胡蘿蔔，長快快呀長快快！”[-]\n[e76041]使用:可獲得稀有坐騎—秋趣。[-]"
