item_ext_desc[19950] = "[ffffff]傳記：我家旁邊搬來一個奇怪的人類，他終日在山間遊歷，偶爾還會吟詩踏歌。他最喜歡的事情就是掀起窗簾，看山水俊秀，草木蔥蘢，有時他也會看我舉著小葉傘，坐在絨絨的青苔上和蝴蝶一起唱歌，每當這時，他便會感慨一句:“何陋之有？”[-]\n[e76041]使用:可獲得稀有坐騎—苔痕。[-]"
item_ext_desc[19951] = "[ffffff]傳記：世人之夢，奇詭瑰麗，有獸形似馬，名謂“宿魘”，其鬃燦燦若星漢，其聲隆隆如冬雷，以夢為食，晝伏夜出。宿魘曾為星君，與貘相爭，戰於天帝夢中，天帝醒，怒而降罪與宿魘，奪其神力，貶為走獸，需侍明君八千載，方可重歸其位。[-]\n[e76041]使用:可獲得稀有坐騎—宿魘。[-]"
