item_ext_desc[19988] = "[ffffff]傳記：巴山有獸，音如擊石，形如赤豹，體紅如山桃，世人以之為猙。非也，此乃桃猙，能禦風，曾受武侯所托引東風至赤壁。此獸冬而伏，驚蟄而醒，穀雨時現，食霜雪，吞濕邪，驅寒氣於關外，引熏風至蜀中，其所行處群花爛漫，萬物蘇生，乃大吉之瑞獸。[-]\n[e76041]使用:可獲得稀有坐騎—桃猙。[-]"
