item_ext_desc[19993] = "[ffffff]別看我是個盒子，但我能給你不一樣的驚喜。[-]\n[e76041]使用:可獲得限時永久時裝—白陌鶯歌。[-]"
item_ext_desc[19998] = "[ffffff]傳記：商時帝辛暴虐無度，使異獸運木石，由蜀山至朝歌，興瓊台玉宇。此獸頭若銅盾，生犀角，身負鱗甲，有萬鈞之力，可日行八百，其壽無人可知。而後武王滅商，又經秦漢，朝代興亡，更迭無數，唯此獸獨存至今，以為見證。[-]\n[e76041]使用:可獲得稀有坐騎—異角。[-]"
item_ext_desc[19999] = "[ffffff]傳記：諦麟原是蓬萊仙人座下的金瞳玄鬃玉獅子，生性好動無畏。一日，它追逐煙霞於雲上，衝撞了仙人的丹爐，誤食尚未煉好的仙丹，成為長著銳利雙角的兇惡怪獸，因而被貶下凡。但仙人憐愛玉獅子，於是施下仙術，若諦麟能在抑制凶性，煉去雙角，便能重歸蓬萊。[-]\n[e76041]使用:可獲得稀有坐騎—諦麟·神。[-]"
item_ext_desc[20000] = "[ffffff]傳記：因成為惡獸而被貶下凡的諦麟為重回蓬萊，百年間輔佐數位豪傑征戰天下，平定禍亂，見證了無數英雄事蹟，凶性也隨之慢慢褪去。當它終於有資格回歸仙境時，諦麟卻拒絕了前來迎接它的仙人，因為在它已被凡人英雄們的堅韌與忠義感動，決意留在凡間，繼續為英雄而戰。[-]\n[e76041]使用:可獲得稀有坐騎—諦麟·聖。[-]"
item_ext_desc[20001] = "[ffffff]傳記：三千世界，能大能小，方圓變化，玄而又玄。有一世界，寄身書中，山川鳥獸，宣紙所成。折頁為山，傾墨為淵，聚簡為木，點絹為花，鐘靈毓秀，精巧無雙。曾有散仙，名姓未諳，以此為居，而築洞天，不問世事，不染紅塵，暢遊紙境，一夢千年。[-]\n[e76041]使用:可獲得稀有坐騎—箋境。[-]"
