item_ext_desc[20024] = "[ffffff]傳記：古者奚仲作車，乘杜作乘馬，使人可遠行。恒公時，齊商得奚仲之車，然舊車已朽，幾近腐土。故齊商命百工修葺整頓，重鑄輪軸，鎏以黃金，飾以美玉，鑲以紫晶，綴以絲綢。齊商以此車獻恒公，恒公大悅，名之曰“覓旅”。[-]\n[e76041]使用:可獲得稀有坐騎—覓旅。[-]"
item_ext_desc[20025] = "[ffffff]一個神秘的禮匣，打開似乎能獲得很多好東西。[-]\n[e76041]使用1：必定獲得1個龍紋金元。\n使用2：隨機獲得坐騎包•地、4級保底符、3級保底符、上古兵策、上古兵卷、上古兵書、魂魄碎片、小妖魂魄、靈妖魂魄。更有概率獲得全新稀有坐騎“覓旅”和稀有坐騎“初曉”。[-]"
