item_ext_desc[20029] = "[ffffff]傳記：秉燭夜遊小園間，暗香嫋嫋淺似煙。嬋娟斜照清如練，亭亭玉立水中仙。嫣然持扇半遮面，錦繡搖曳香風遠。雲舒雲卷蓮息漫，蛾眉未笑意已濃。忽而雲起遮明月，不見明月不見仙。[-]\n[e76041]使用:可獲得稀有坐騎—蓮息。[-]"
item_ext_desc[20030] = "[ffffff]傳記：西漢末時光武帝帶兵出征，然而連月的梅雨使糧草受潮，正危急時，斥候發現了巨大的蜂巢，其中盈滿蜂蜜。光武帝命軍隊在此暫歇，采蜜充饑，又命人將蜂蜜晾成大塊蜜糖，作為軍糧攜帶。此舉不僅化解了糧草危機，也使蜜糖成為了備受漢軍喜愛的美食。[-]\n[e76041]使用:可獲得稀有坐騎—蜜語。[-]"
item_ext_desc[20031] = "[ffffff]試拂鐵衣如雪色，聊持寶劍動星文[-]\n[e76041]使用：可獲得稀有神羽幻化-銅身鐵臂。[-]"
