item_ext_desc[20050] = "[ffffff]傳記：月英改進了她的機關木鳥，用密不透風的油紙替代笨重的實木，讓機關鳥變得輕盈無比，飄逸靈動。月英驕傲地叫它“仙羽”，並附上一封信：“如果想回臥龍崗看看，就請乘著它來吧，我讓我先生試過了，絕對安全！”[-]\n[e76041]使用:可獲得稀有坐騎—仙羽。[-]"
