item_ext_desc[20058] = "[ffffff]傳記：極南有山，名玄山，山多黑石，不生草木。山中有龍，名為玄灼，赤焰鬃，玄鐵鱗，能吞火，所行處萬物盡焚。昔玄灼與應龍為敵，戰於大荒，大荒為龍炎所焚，火借風勢，三月不熄，其中神通，不可估量。[-]\n[e76041]使用:可獲得稀有坐騎—玄灼。[-]"
