item_ext_desc[20064] = "[ffffff]傳記：相傳古時候有一位才學過人的智者，他受夠了世間無休止的戰火，決定隱居。智者在終南山的深林裏蓋起茅廬，春暖躬耕，入冬蝸居，閑時騎著白鹿踏雪而行，肆意於青崖之間。如果有人能找那只白鹿，就能乘著它來到智者的茅廬，那位智者則會將他的智慧盡數傳授。[-]\n[e76041]使用:可獲得稀有坐騎—尋冬。[-]"
item_ext_desc[20065] = "[ffffff]一個神秘的禮匣，打開似乎能獲得很多好東西。[-]\n[e76041]使用1：必定獲得1個龍紋金元。\n使用2：隨機獲得3級隨機寶石、4級隨機寶石、5級隨機寶石、6級隨機寶石、東周卡包•無雙、三國卡包•無雙、3級寵物口糧、4級寵物口糧、5級寵物口糧。更有概率獲得全新稀有坐騎“尋冬”和稀有坐騎“仙羽”。[-]"
