item_ext_desc[20069] = "[ffffff]少年佳節倍多情，老去誰知感慨生。[-]\n[e76041]收藏:風元素防禦+100[-]"
item_ext_desc[20073] = "[ffffff]傳記：雲中有居士，朱冠白羽衣。行吟共踏歌，詩畫兩相宜。才情比金玉，心志堅不移。廣袖舞柔風，清音如佩鳴。扶搖乘雲起，長天垂玄翼。朝辭萬仞山，暮至薄霧裏。仙影尚難尋，行蹤久成迷。結廬煙霞境，逍遙無歸期。[-]\n[e76041]使用:可獲得稀有坐騎—雲居。[-]"
item_ext_desc[20074] = "[ffffff]傳記：端午節素有賽龍舟的習俗，今年也不例外。長江兩岸早早地張燈結綵，用五色旌旗標出賽道，彩綢點綴的龍舟在起點一字排開，還未到開賽之時，擂鼓聲就已經響徹天際，熱鬧非凡。更有小道消息稱，丞相準備了堆成小山的鮮肉粽子，會獎勵給拔得頭籌的龍舟賽手！[-]\n[e76041]使用:可獲得稀有坐騎—爭渡·神。[-]"
item_ext_desc[20075] = "[ffffff]傳記：江上游弋的身影，是龍，還是舟？是龍舟！爭渡！爭渡！當號子聲響起的時候，龍舟成了江上最引人注目的風景。揮灑汗水，讓船槳整齊地劃動，船身則化作遊龍飛馳，龍首劈開白浪和葦葉，目標就是那道鮮紅色的終點線！[-]\n[e76041]使用:可獲得稀有坐騎—爭渡·聖。[-]"
