item_ext_desc[20100] = "[ffffff]傳記：農曆七月時，煞氣最盛，亂邪滋生，危害蒼生。有三尾靈狐，自北嶺深林而出，其聲如嬰兒啼，銜青燈，踏磷火，鎮邪除煞。靈狐若遇邪祟，則以狐火逐之，若遇奸惡，則以利齒相搏。燈火渺遠，磷光朦朧，狐鳴悠悠，遂天下太平。[-]\n[e76041]使用:可獲得稀有坐騎—青尾。[-]"
