item_ext_desc[20106] = "[ffffff]傳記：《經》雲：“氣乘風則散，界水則止。”古人聚之使不散，行之使有止，故謂之“風水”。古者包棲觀象於天，觀法於地，著書立說，行堪輿之術。後者遵伏羲之術，鑄八卦羅盤，丈量星辰之運轉，測繪地理之變化，以求一窺天機。[-]\n[e76041]使用:可獲得稀有坐騎—堪輿。[-]"
