item_ext_desc[20115] = "[ffffff]傳記：西域有獸，身似貓，毛色渾黑，其目赤金，耳長如兔，內生青絨毛。西域人以其為司日之神獸，供之於廟堂，飾之以青石黃金。每逢節日祭禮，巫祝佩玄色長耳頭飾，奉羊奶鮮魚，問蔔於此獸，獸答曰：“喵喵喵！”[-]\n[e76041]使用:可獲得稀有坐騎—琉砂。[-]"
