item_ext_desc[20137] = "[ffffff]傳記：東海有島，盛產黑石，終年赤炎環繞，寸草不生。島上有凶獸，形似豹，身通黑，四足踏火。千餘載前大能鎮凶獸於島上，故此獸長眠已久，只因其獸魂兇悍，八百年一醒，醒則焚風降世，夜空盡燃，故名之曰燼夜。[-]\n[e76041]使用:可獲得稀有坐騎—燼夜。[-]"
item_ext_desc[20138] = "[ffffff]傳記：東海廣遠，生靈奇異，煙波浩渺，可納百川。海中一鯨，身長十丈，引頸長吟，聲傳萬裏，偶得龍氣，化形半靈，頭生二角，身被青鱗，舒翅為浪，曳尾成濤，遇浪則遊，遇風而飛，暢行天地，無束無拘。[-]\n[e76041]使用:可獲得稀有坐騎—敖遊。[-]"
item_ext_desc[20139] = "[ffffff]一個神秘的禮匣，打開似乎能獲得很多好東西。[-]\n[e76041]使用1：必定獲得1個龍紋金元。\n使用2：隨機獲得坐騎包•地、4級保底符、3級保底符、上古兵策、上古兵卷、上古兵書、魂魄碎片、小妖魂魄、靈妖魂魄。更有概率獲得全新稀有坐騎“敖遊”和稀有坐騎“琉砂”。[-]"
