item_ext_desc[20144] = "[ffffff]傳記：蜀山天池，內生蓮花，其葉若鏤金，瓣似白玉，亭亭玉立，靈韻天成。池中有亭，內有神鼓蓮官，鼓身乃千年寒冰所成，蒙以鼉龍之皮。鼓者需擊之以楠木槌，三緩三急，成則池中蓮花皆綻，香漫蜀山。[-]\n[e76041]使用:可獲得稀有坐騎—蓮官。[-]"
