item_ext_desc[20161] = "[ffffff]傳記：人類整天 “小丑魚”，“小丑魚”地叫我，你們摸著良心講，我醜嗎？看我這身橙白相間的鱗片，圓潤豐滿的身軀，還有扇子一樣的鰭和小巧可愛的尾巴，誰見了都要對我讚不絕口。你也是呀，既然坐在我的小籃筐裏，就多誇誇我吧！[-]\n[e76041]使用:可獲得稀有坐騎—魚美。[-]"
item_ext_desc[20162] = "[ffffff]傳記：南華有麂，身白而尾蹄紫，食仙草，飲花露，周身電光環繞。其角堅實，五行屬金，以其鑄劍，皆為神兵。因其偶現於南疆，故南疆獵戶爭相狩之，現世所存雷麂已罕如廖星，為天下所禁獵。[-]\n[e76041]使用:可獲得稀有坐騎—雷鹿。[-]"
