item_ext_desc[20176] = "[ffffff]傳記：珠玉藏於汪洋，因難求而珍，求之需潛五洋，下九淵，取百蚌只為一珠。賢能居於莽蒼，因少伯樂而隱，訪之需遍河山，踏原野，蜀山三顧只為一人。故選賢舉能若深海尋珠，不可因知難而退，而需一心求索，慧眼以識。[-]\n[e76041]使用:可獲得稀有坐騎—凝珠。[-]"
