item_ext_desc[20181] = "[ffffff]傳記：南蠻多急水灘塗，夷族一支居於水岸，族人以捕魚為業，敬畏湍流。其紋乃蒼色麒麟，喙似白玉，角若硨磲，名為湍君。夷族以此麒麟為水神，開河時祭之，請湍君護佑，以求風平浪穩，漁獲滿倉。[-]\n[e76041]使用:可獲得稀有坐騎—湍君·神。[-]"
item_ext_desc[20182] = "[ffffff]傳記：水麒麟湍君乃東方青龍後嗣，以溪水江河為居，喜激流瀑布。湍君天生神通，號令百川，其常戲於巨浪之間，偶現於江上，狂風急濤相伴左右，江水如騰龍而起，直沖天際，百米之內無人能近，故夷族奉之為水神。[-]\n[e76041]使用:可獲得稀有坐騎—湍君·聖。[-]"
