item_ext_desc[20203] = "[ffffff]傳記：月初霽，風弄柔枝搖倚。淇水岸，花到荼蘼，才歎時光短如隙。登高遠望去，恨不能常在。曾憶，袂裳系。夏晚巧折枝，輕綴籃裏。夜雨驟急落零一地。醒且來探，只剩憐惜。謹記，短春熙，念舊歲如寂夢。花謝明還再開，人卻無回往昔，豈能兒戲？[-]\n[e76041]使用:可獲得稀有坐騎—菀夏。[-]"
