item_ext_desc[20220] = "[ffffff]傳記：南華仙人近來得到一個寶貝，乍看是普通的畫卷，畫面用琉璃色塗開成水面，平平無奇，但展開之後那藍色就成了畫卷上一汪池水，從中開出荷花。仙人對這畫卷愛不釋手，時常拿給仙友們展示，卻在某天騰雲駕霧時，畫卷不小心脫手，從此遺落凡間。[-]\n[e76041]使用:可獲得稀有坐騎—繪池·神。[-]"
item_ext_desc[20221] = "[ffffff]傳記：南疆一個獵戶在山中拾得一幅神奇的畫卷，疑是仙界遺寶，展開畫卷時，琉璃色畫出的水面就會長出荷花。獵戶決定獨佔這個寶貝，於是把它偷偷埋藏進莊稼地裏。可當他第二天再來時，發現農田變成了連綿的荷塘，不管怎麼尋覓，都再找不到那幅畫卷了。[-]\n[e76041]使用:可獲得稀有坐騎—繪池·聖。[-]"
item_ext_desc[20222] = "[ffffff]不知今夕夢，到蜀到錢塘[-]\n[e76041]收藏:風元素防禦+100[-]"
item_ext_desc[20224] = "[ffffff]傳記：東海漁民傳言海中有嘯聲，疑是螭龍。好事者潛而尋之，見一獨角巨鯨，浮游自在，行若乘風，時而長吟，歌韻靈動悠揚，似得帝江之傳。此獸偶現於洋上，聲傳百里，然無人能見其真身，故皆曰：“異獸通靈，非有緣者不能近。”[-]\n[e76041]使用:可獲得稀有坐騎—鯨歌。[-]"
