item_ext_desc[20237] = "[ffffff]傳記：昆侖山深處有一眼溫泉，以之沐浴可以延年益壽，治癒百病。但那泉水嬌貴，離了水源便會失去奇效，除非用開採自昆侖山中的無暇蒼玉打造成的容器盛放，才不會失去原本的效力。自古以來無數君王與富豪一擲千金，只為一沐清泉。[-]\n[e76041]使用:可獲得稀有坐騎—清沐。[-]"
item_ext_desc[20238] = "[ffffff]傳記：東吳水軍操練於海，忽有巨獸自洋中躍出，掠過戰船之上。此獸背闊數丈，兩翼寬廣，形似鵬鳥而面目混沌，一尾修長且飾以金環，額生利角，其聲隆隆若狂濤擊岸，其勢洶洶似怒風翻雲。眾軍士大驚，皆以其為吉兆，而士氣昂揚，實力大增。[-]\n[e76041]使用:可獲得稀有坐騎—飛鰩。[-]"
item_ext_desc[20239] = "[ffffff]早起見日出，暮見棲鳥還。[-]\n[e76041]收藏:暴擊傷害+2%[-]"
item_ext_desc[20240] = "[ffffff]天地一逆旅，同悲萬古塵[-]\n[e76041]使用：可獲得稀有神羽幻化-魔瞳幻化。[-]"
item_ext_desc[20241] = "[ffffff]一個神秘的禮匣，打開似乎能獲得很多好東西。[-]\n[e76041]使用1：必定獲得1個龍紋金元。\n使用2：隨機獲得坐騎包•地、4級保底符、3級保底符、上古兵策、上古兵卷、上古兵書、魂魄碎片、小妖魂魄、靈妖魂魄。更有概率獲得全新稀有坐騎“飛鰩”和稀有坐騎“敖遊”。[-]"
item_ext_desc[20242] = "[ffffff]門掩落花春去後，窗涵殘月酒醒時。[-]\n[e76041]收藏:暴傷減免+2%[-]"
