item_ext_desc[20244] = "[ffffff]行過淇園天未曉，一痕殘月杏花香。[-]\n[e76041]收藏:雷元素防禦+100[-]"
item_ext_desc[20245] = "[ffffff]別看我是個盒子，但我能給你不一樣的驚喜。[-]\n[e76041]使用:可獲得永久時裝—花間梨落。[-]"
item_ext_desc[20250] = "[ffffff]傳記：自混沌初開，即有野獸偶得機緣，開啟靈智，而後修行千年，方成精怪。有一白羚，食冰漱玉，聽雷而啟智，乃成靈獸，其身被珠璣，其淚為琥珀，額生金毛可織為絹，水火不侵，乃天下罕有之珍材。[-]\n[e76041]使用:可獲得稀有坐騎—凜風。[-]"
item_ext_desc[20251] = "[ffffff]傳記：又是一年中秋將至，洛陽百姓紛紛采買天燈以放飛祈福。城東作坊的一個手藝人突發奇想，造了一只丈餘高的大燈，再用四根鎏金鐵索栓上一只花梨木船，人乘上去就會隨著燈飛上高空，遍覽洛陽盛景。一時間，這只巨大的天燈成為佳話。[-]\n[e76041]使用:可獲得稀有坐騎—長明·神。[-]"
item_ext_desc[20252] = "[ffffff]傳記：洛陽的能工巧匠為了慶祝中秋而建造了一只足以載人的巨大天燈，飾以珠玉和絹花。當乘著它飛上雲端時，腳下便是洛陽城的萬家燈火，頭上星辰仿佛觸手可及，遠山青黛連綿似潑墨。十五的明月升起來，月光與燈光交融，燈如月，月如燈。[-]\n[e76041]使用:可獲得稀有坐騎—長明·聖。[-]"
item_ext_desc[20253] = "[ffffff]傳記：燕有樵夫打柴為生，偶遇一黃犬，著赤、青二色衣裝，足系金鈴。樵夫甚異，隨其行，入山二三裏，乃見一篷，形似軍中營帳，內有熊、獅、虎、犬等各類走獸十餘，又有雀、雉、鷂、鷹等珍奇飛禽若干，皆奇裝異服，追逐遊戲，熱鬧非常。[-]\n[e76041]使用:可獲得稀有坐騎—奇遇。[-]"
