item_ext_desc[20286] = "[ffffff]傳記：墨門偶得一隕鐵，通白如玉，熔煉百日方鑄為車，輔以機關奇術，無需牛馬牽引而能行於地，無需帆槳桅杆而能浮於水，無需翼翅羽毛而能翔於天。墨子大喜，乘之而遊四方，海內各處不消半日即達，追星逐月，迅疾若電，故謂之“追星”。[-]\n[e76041]使用:可獲得稀有坐騎—追星。[-]"
