item_ext_desc[20296] = "[ffffff]傳記：薑太公垂竿於水岸，得一怪魚，其狀如囊，身被棘刺，雙目渾圓，鰭短似摺扇。太公以指觸之，此魚忽大張其口，吞水入腹，魚身鼓起若蹴鞠，棘刺皆立。太公大驚，使怪魚脫手，魚入溪而去，不見其蹤。太公喟然歎曰：“得失在天也！”[-]\n[e76041]使用:可獲得稀有坐騎—吞吞。[-]"
item_ext_desc[20297] = "[ffffff]這是一個神秘的禮盒，裏面似乎有很多好東西。[-]\n[e76041]使用1：必定獲得1個龍紋金元。\n使用2：隨機獲得坐騎包•地、大量光羽、3級保底符、上古兵策、上古兵卷、上古兵書、魂魄碎片、小妖魂魄、靈妖魂魄。更有概率獲得全新稀有坐騎“吞吞”和稀有坐騎“飛鰩”。[-]"
item_ext_desc[20298] = "[ffffff]2021年重陽節活動獎勵稱號。[-]\n[e76041]使用：可獲得稱號“九九重陽·五”。\n主動屬性：物理攻擊+800，法術攻擊+800\n被動屬性：物理攻擊+400，法術攻擊+400[-]"
item_ext_desc[20317] = "[ffffff]傳記：昔時仙蹤尚可尋，每逢子夜，群星當空，眾星君馭車行於寰宇，天馬引車，天河為轍，浩浩蕩蕩，蔚為壯觀。偶有流星隕地，乃星君寶車現於世，乘之可日行千里，所過處星漢燦爛，曰“疑是銀河落九天”！[-]\n[e76041]使用:可獲得稀有坐騎—星途。[-]"
item_ext_desc[20318] = "[ffffff]傳記：人們都說我有一身紅紅的鱗片，一條金色的尾巴，是能帶來好運氣的“錦鯉”，因此，總有人為了爭奪我而絞盡腦汁。但他們不知道的是，我在等待一位勇武帥氣的主人，一位救世渡人的英雄，而我會用我的力量祝福那人一生幸運。[-]\n[e76041]使用:可獲得稀有坐騎—紅韻。[-]"
