item_ext_desc[20336] = "[ffffff]一枚雕刻著精緻龍紋的黃金錢幣，頗具西域風情。[-]\n[e76041]獲得：2021年雙十一活動開啟期間，通過“六龍慶典”中“誠心祈緣”介面進行簽到獲得。\n使用：2021年雙十一活動開啟期間，集齊六枚“西域金元”，可以通過“六龍慶典”中“誠心祈緣”介面兌換專屬稱號。[-]\n[ffff00]“這樣東西是兌換大獎的唯一憑證，還請將軍妥善保管，遺失不補哦。”——段瑢[-]"
