item_ext_desc[20353] = "[ffffff]傳記：螺生東海之底，百歲而為靈。偶有千年巨螺，得海之靈犀，蘊萬般玄妙。其身長丈餘，其色如碧水，其輝似點點星辰。若得其殼，則三尺內可聞濤聲陣陣，浪聲汩汩，如親臨海濱，故名之曰“潮兮”。[-]\n[e76041]使用:可獲得稀有坐騎—潮兮·神。[-]"
item_ext_desc[20354] = "[ffffff]傳記：楚有歌雲：“潮兮潮兮，可聞其聲兮，逐浪於嶼兮，問道於天兮。”潮兮乃東海一螺，其形大若車，重千斤，能逐浪而遊，翩翩舞於海，若鴻毛浮風。此螺頗具靈韻，人可乘之渡海，尋蓬萊之世外仙境，訪瀛洲之煙波微茫。[-]\n[e76041]使用:可獲得稀有坐騎—潮兮·聖。[-]"
item_ext_desc[20355] = "[ffffff]羽書速驚電，烽火晝連光。[-]\n[e76041]使用：可獲得稀有神羽幻化-舞火幻化。[-]"
