item_ext_desc[20365] = "[ffffff]傳記：有旅者自西歸，謂其鄉人曰：“行至太行以西廿萬裏，時九月中，逢西戎節慶，路人皆做魍魎之扮相遊於市，狀若百鬼夜行。其中最為可怖者乘一浮車，著素衣白裳，面目森嚴，磷火相繞，此人以飴贈吾，曰：‘請與吾等同樂！’”[-]\n[e76041]使用:可獲得稀有坐騎—幽火。[-]"
item_ext_desc[20366] = "[ffffff]傳記：吳人夜寐，夢其化為一巨魚，徜徉深海，尋訪龍宮。龍王攜眾水族相迎，贈以明珠，獻以珊瑚，相邀宴飲，金盤盛珍饈，玉杯滿瓊漿，龍女舞長袖，絲竹不絕聲。忽聞雞鳴，吳人驚起而長嗟，萬千宮殿散若煙霞，夢中繁華只餘無盡嚮往。[-]\n[e76041]使用:可獲得稀有坐騎—遠夢。[-]"
