item_ext_desc[20373] = "[ffffff]傳記：我的家在極北之地的大海裏，那裏遍佈冰山，魚蝦成群，永遠不愁吃喝。你別不信，在我的家族中，我可是速度最快的海豹，外號“豹子頭靈聰”，連黑白花的虎鯨都追不上我的尾巴。只要有我帶路，就算你想去北極，也都是小意思啦！[-]\n[e76041]使用:可獲得稀有坐騎—靈聰。[-]"
item_ext_desc[20376] = "[ffffff]傳記：請問去京郊的路怎麼走？我要去那裏的大山深處尋找罕見的藍色冰雪花。不過聽人說，京郊的山高水遠，風雪滿途，半路還總是能聞見香噴噴的烤紅薯味……不對不對，我才沒有只想著吃呢！就算知道路上有這麼多困難，也沒什麼能擋住我的腳步！[-]\n[e76041]使用:可獲得稀有坐騎—踏雪·神。[-]"
item_ext_desc[20377] = "[ffffff]傳記：我本來是要去京郊的大山深處，尋找生長在那裏的藍色冰雪花。但我最終決定留下，因為在這一路上，我遇見了許多朋友，聽到無數聞所未聞的傳說。不過，最重要的是……哎呀，烤紅薯實在是太好吃了！老闆，請再來一斤！[-]\n[e76041]使用:可獲得稀有坐騎—踏雪·聖。[-]"
