item_ext_desc[20389] = "[ffffff]傳記：想拿走我所有的財寶？可別天真了！雖然我長著寶箱的樣子，擔著寶箱的工作，但我可是大名鼎鼎的寶箱怪，從古至今趕跑的尋寶者能從王城排到天門關！誰敢在我眼皮子底下打寶貝們的主意，我就嗷嗚一口在誰手上留一個大牙印！[-]\n[e76041]使用:可獲得稀有坐騎—守財。[-]"
item_ext_desc[20390] = "[ffffff]傳記：冰泉消雪春池暖，楊堤初有飛還燕。碧葉水中生，新荷隱隱紅。料峭風吹雨，濃雲鎖蒹葭。只道霧非霧，不識花非花。[-]\n[e76041]使用:可獲得稀有坐騎—非花。[-]"
