item_ext_desc[20399] = "[ffffff]傳記：淮南冬暖，臘月尚不寒，駕小輦尋花於溪澗。至途中，薄雲稍聚，纖雨滴落油紙傘，回首相望，霧裏亭臺半遮面。細嗅輕風，暗香嫋嫋。雨過初晴，煙收塵斂，終得見，山花爭豔。采一支，攜而歸去，且待明春再相見！[-]\n[e76041]使用:可獲得稀有坐騎—輕輦。[-]"
