item_ext_desc[20405] = "[ffffff]傳記：巴國有山，終年燃火，有熔岩自地裂處出，所經處金石具焚，寸草不生，唯黑石獨存。山周數裏，皆化作焦土，未有生靈敢近。有一旱螺螄，以黑石築其甲，無懼焦熱，餓啖烈火，渴飲熔漿。欲入火山之地，唯有乘之而行。[-]\n[e76041]使用:可獲得稀有坐騎—熔戎。[-]"
item_ext_desc[20408] = "[ffffff]傳記：東極隅有女和月母之國，國中有司月之神，手持白玉彎月符，神通可以調節月亮的運轉。白晝時，月符寂靜無光，到了夜裏，月神便點亮月符，將它送上天空，成為高懸的明月。千萬年時光轉瞬而逝，月亮在月神的管理下準確地運行著，從不曾有疏漏。[-]\n[e76041]使用:可獲得稀有坐騎—輝夜·神。[-]"
item_ext_desc[20409] = "[ffffff]傳記：女和月母之國的月神司掌月亮的運行，日復一日地將月符送上天空，化作照亮夜色的明月。有時候，月神也會端坐明月之上，遠遠地望著被月光照耀的大地，遙想是否有人會在不經意間抬頭，將月神的身影與清澈的月色一併映入眼簾。[-]\n[e76041]使用:可獲得稀有坐騎—輝夜·聖。[-]"
