item_ext_desc[20435] = "[ffffff]打開後獲得紫色品質的聖級寵物——貂寶。[-]\n[e76041]貂寶是聖級寵物，必然能夠提升本職業對應的元素屬性攻擊，初始可獲得3個3級以上寵物技能，整體屬性比神級寵物有很大幅度提升。[-]"
