item_ext_desc[20438] = "[ffffff]傳記：鳳凰棲梧桐，翩翩影自孤。霓翅披煙雲，鳴若擊玉珠。紫氣自東來，白羽拂晨霧。九天伴紅霞，瑤池飲甘露。浴火幾輪回，清心築傲骨。乘風三萬裏，豈在一朝暮！[-]\n[e76041]使用:可獲得稀有坐騎—披霞。[-]"
item_ext_desc[20439] = "[ffffff]願螭龍之駕，思想昆侖居。[-]\n[e76041]收藏:傷害加深+2%[-]"
