item_ext_desc[20444] = "[ffffff]2021元月簽到稱號。[-]\n[e76041]使用：可獲得稱號“攜手2021”\n主動屬性：物理攻擊+1500，法術攻擊+1500\n被動屬性：物理攻擊+300，法術攻擊+300[-]"
item_ext_desc[20446] = "[ffffff]傳記：沖啊，沖啊！沒什麼能阻擋我風馳電掣的輪胎！高山？越過去！激流？越過去！這點困難都克服不了，我還怎麼能通過墨子的考驗，到達墨家禁地呢？什麼，你說我跑反了？墨門的方向在另一邊？哎呀，管不了那麼多了，反正地球是圓的，繼續跑下去，就總有一天會到達！[-]\n[e76041]使用:可獲得稀有坐騎—暢行。[-]"
