item_ext_desc[20454] = "[ffffff]一年滴盡蓮花漏。碧井酴酥沉凍酒[-]\n[e76041]使用：可獲得稀有神羽幻化-赤羽驚春。[-]"
item_ext_desc[20457] = "[ffffff]傳記：每一棵小草都有一個飛天夢。我時常羡慕蒲公英的種子能借著絨毛隨風飄蕩，也偶爾希望自己能有鳥兒般強健的翅膀，可惜我生來只是平凡的青菜。但這又如何？我還有我的滑翔翼和風帆，依舊可以一躍而起，沖向藍天！[-]\n[e76041]使用:可獲得稀有坐騎—隨風。[-]"
item_ext_desc[20458] = "[ffffff]傳記：暫無。[-]\n[e76041]使用:可獲得稀有坐騎—冰焰。[-]"
item_ext_desc[20459] = "[ffffff]無由見顏色，還自托微波。[-]\n[e76041]收藏：暴擊傷害+2%[-]"
