item_ext_desc[20475] = "[ffffff]炯如銀河墮片月，群星錯落流璿璣[-]\n[e76041]使用：可獲得稀有神羽幻化-珠鸞幻化。[-]"
item_ext_desc[20478] = "[ffffff]傳記：有龍自東海而出，征伐四方，百戰不殆，最終歸隱於西方大山深處的萬水之源。傳說此龍的居所乃是一方天池，充盈著它吐息出的濕氣，雲霧繚繞。無數追尋著傳說而來、試圖尋找龍的人都無功而返，只能望山興歎曰：“龍乘是氣，茫洋窮乎玄間！”[-]\n[e76041]使用:可獲得稀有坐騎—歸流。[-]"
item_ext_desc[20479] = "[ffffff]傳記：歡迎乘坐雪國號雪人車！沒錯，拉車的不是馬，也不是雪橇犬，而是真正的雪人哦！它會帶你穿越雪國漫長的永夜，追尋絢麗的極光。不用擔心迷失方向，你看，雪人帽頂上的明燈會照亮前進的方向！[-]\n[e76041]使用:可獲得稀有坐騎—領航。[-]"
item_ext_desc[20480] = "[ffffff]燭龍棲寒門，光曜猶旦開。[-]\n[e76041]收藏:暴傷減免+2%[-]"
item_ext_desc[20494] = "[ffffff]傳記：蘇南有溪，名曰黛溪，溪中有魚，雅號“青黛”。其頭渾圓，其體雍容，其尾青碧，搖曳而遊，形若孔雀。好魚者趨之若鶩，紛紛捕魚溪中，使其影絕，黛溪亦無人問津。數十載過，有人偶見青黛再現於溪中，三兩成群，生生不息。[-]\n[e76041]使用:可獲得稀有坐騎—青黛。[-]"
item_ext_desc[20495] = "[ffffff]傳記：賣酒啦，香噴噴的屠蘇酒。客官，來杯酒吧，雖然冬日的寒意尚未消退，但回春的柔風正在路上，歸還的燕兒也已啟程。既然春天觸手可及，何不用一杯美酒暖暖身子，舒展窩了一冬的筋骨，準備迎接新一年的到來呢？[-]\n[e76041]使用:可獲得稀有坐騎—屠蘇。[-]"
item_ext_desc[20496] = "[ffffff]傳記：自古以來，避世隱居者追求的都是枕石漱流、恬淡於浩然之域的生活。然而，有奇人隱者突發異想，欲枕流漱石。於是隱者在泉邊築起茅廬，與汩汩泉聲相伴入眠。隱者在睡夢裏，以泉水為車，以荷花搭棚，金魚做馬，枕流而行。[-]\n[e76041]使用:可獲得稀有坐騎—枕泉·神。[-]"
item_ext_desc[20497] = "[ffffff]傳記：有散仙居於泉邊，自號“枕泉居士”，以蓮花金魚為車馬。有善辯者謂其曰：“流非可枕也。”居士答曰：“所以枕流，欲洗其耳。洗耳恭聽，則能虛懷若谷，不致剛愎自用！”善辯者曰：“然也！”[-]\n[e76041]使用:可獲得稀有坐騎—枕泉·聖。[-]"
item_ext_desc[20498] = "[ffffff]傳記：菇子和她的兄弟姐妹們誕生於一片莽莽蒼蒼的大森林，那裏有成片的、高聳入雲的松樹，還有清澈見底的溪流，是個適合居住的好地方。但菇子認為自己應該擁有更加精彩的菇生，於是她鼓起勇氣，踏上前往遠方的路。[-]\n[e76041]使用:可獲得稀有坐騎—菇子。[-]"
item_ext_desc[20499] = "[ffffff]傳記：啟稟將軍！有農戶傳言稱有一座大山憑空出現在京郊，山上還有一座白色的要塞。屬下正要去查看時，忽然一陣地動山搖，原來那山是一只巨大的赑屃。此等巨獸，恐怕只有請將軍您出手，才能將它才能降服了！[-]\n[e76041]使用:可獲得稀有坐騎—千鈞·神。[-]"
item_ext_desc[20500] = "[ffffff]傳記：啟稟將軍！京郊背負要塞的巨大赑屃已經被降服，屬下在它背上放好了馬鞍，隨時聽憑將軍調遣，有此物助戰，勝利指日可待！不過這麼一個大家夥，要蓋多大的馬廄才能放得下它和它要吃的草料啊……[-]\n[e76041]使用:可獲得稀有坐騎—千鈞·聖。[-]"
