item_ext_desc[20569] = "[ffffff]傳記：天有玄機，秘而不言，道生空明處，氣催萬物蘇，春風化雨，芳草萋萋，新綠上枝頭。天有璿璣，飛翼踏雲，威容鎮河山，光輝耀九州，時年方始，星宿歸位，前途正光明。[-]\n[e76041]使用:可獲得稀有坐騎—璿璣。[-]"
item_ext_desc[20571] = "[ffffff]傳語風光共流轉，暫時相賞莫相違[-]\n[e76041]使用：可獲得稀有神羽幻化-惜華幻化。[-]"
item_ext_desc[20573] = "[ffffff]傳記：相傳千年之前，天地間遍佈靈氣，奇事多發。一對仙侶在湖邊種下桃樹，豐沛的靈氣和細心的呵護讓桃樹開出晶瑩剔透的花，香飄百里，明豔無雙。傳說被人折下的桃枝會化為飛椅，將折枝者送到愛人面前。正所謂”花開堪折直須折，莫待無花空折枝”！[-]\n[e76041]使用:可獲得稀有坐騎—芳心。[-]"
item_ext_desc[20574] = "[ffffff]巴陵一望洞庭秋，日見孤峰水上浮。[-]\n[e76041]收藏：水元素防禦+100[-]"
