item_ext_desc[20579] = "[ffffff]竹外一枝斜，想佳人，天寒日暮[-]\n[e76041]使用：可獲得稀有神羽幻化-蒼華蛻霜。[-]"
item_ext_desc[20582] = "[ffffff]傳記：海底有一只珍珠貝，每天晚上都會張開貝殼，透過深沉的藍色海水仰望星空。它渴望成為星辰，與其他星星一起玩耍嬉戲、照亮夜空，卻苦惱自己不會飛翔。於是星星告訴它：“海水會倒映星空，從海面上看的時候，你早已和我們同在。”[-]\n[e76041]使用:可獲得稀有坐騎—星衡。[-]"
item_ext_desc[20583] = "[ffffff]傳記：塞上草場廣茂，自古產良駒，其中數駿馬浣紗最為名貴。其身潔白如雪，其行迅疾如電，身軀厚重堅實，鳴聲清脆嘹亮。策馬賓士，輕盈靈動，馬鬃迎風翻飛，如獵獵旌旗舞於風，又似縹緲輕紗浣於溪，故得其名。[-]\n[e76041]使用:可獲得稀有坐騎—浣紗。[-]"
item_ext_desc[20584] = "[ffffff]獨坐岩之曲，悠然無俗紛。[-]\n[e76041]收藏:傷害減免+2%[-]"
item_ext_desc[20585] = "[ffffff]坐看彩翮長，舉意八極周[-]\n[e76041]使用：可獲得稀有神羽幻化-冠絕幻化。[-]"
item_ext_desc[20587] = "[ffffff]傳記：一天，住在大草原上的粉兔兔問它的好朋友藍兔兔道：“你說，月亮是什麼味道的呢？”藍兔兔認為月亮是胡蘿蔔味的，粉兔兔卻說應該是香草味的。它們為此爭論不休，最終決定結伴而行，去尋找月亮升起的地方，親自嘗一嘗月亮的味道，找出答案。[-]\n[e76041]使用:可獲得稀有坐騎—躍兔。[-]"
item_ext_desc[20588] = "[ffffff]卷華藏紛霧，振褐拂埃塵。[-]\n[e76041]收藏:暴擊傷害+2%[-]"
item_ext_desc[20589] = "[ffffff]城頭鐵鼓聲猶振，匣裏金刀血未幹[-]\n[e76041]使用：可獲得新法器-荒魂。[-]"
item_ext_desc[20591] = "[ffffff]傳記：蜀中被幽深的高山密林環繞，難見日月。有時在那不見星光的漆黑之夜，便會聽見林間響起一聲淒厲的狼嚎。緊接著，嚎聲開始從四方傳來，此起彼伏。那是群狼回應狼王的呼喚，向其他生靈宣示著，誰才是此處的主宰。[-]\n[e76041]使用:可獲得稀有坐騎—哮夜。[-]"
