item_ext_desc[20603] = "[ffffff]傳記：稟報官老爺，就說那天俺上山拾柴，忽的，林中傳來撼天動地的咆哮，竄出一只青色大老虎。那老虎生得奇怪，鬼魅一般，長了兩只長角，還帶翅膀。俺嚇得扭頭就跑，那大老虎非但沒有追過來，反而還悠哉悠哉吃起地上的草，您說奇怪不奇怪！[-]\n[e76041]使用:可獲得稀有坐騎—冥爪。[-]"
item_ext_desc[20604] = "[ffffff]傳記：各位看好了，今天我將展示我高超的游泳技術。看我完美的入水姿勢——噗嚕嚕！哎呀，我怎麼沉底了？就算我的身體是由泥土塑造，烈火煉成，可我也是出淤泥而不染的一條魚呀，怎麼可能浮不起來呢！[-]\n[e76041]使用:可獲得稀有坐騎—不染。[-]"
