item_ext_desc[20644] = "[ffffff]傳記：好像有許多人都很怕我，每次看到我就跑得老遠。這樣吧，下次再遇到他們時，我給他們唱一支歌：嗡嗡嗡，嗡嗡嗡，我是忙碌的小蜜蜂~大家看到我請別怕，我可愛，我勤勞~你們遇到我請不要害怕，新鮮的蜜糖請嘗嘗吧~[-]\n[e76041]使用:可獲得稀有坐騎—覓蜜。[-]"
item_ext_desc[20645] = "[ffffff]傳記：暫無。[-]\n[e76041]使用:可獲得稀有坐騎—清歌。[-]"
