item_ext_desc[20648] = "[ffffff]打開後獲得紫色品質的聖級寵物——葉叢。[-]\n[e76041]葉叢是聖級寵物，必然能夠提升本職業對應的元素屬性攻擊，初始可獲得3個3級以上寵物技能，整體屬性比神級寵物有很大幅度提升。[-]"
item_ext_desc[20649] = "[ffffff]打開後獲得紫色品質的聖級寵物——初至。[-]\n[e76041]初至是聖級寵物，必然能夠提升本職業對應的元素屬性攻擊，初始可獲得3個3級以上寵物技能，整體屬性比神級寵物有很大幅度提升。[-]"
item_ext_desc[20651] = "[ffffff]傳記：我本天地一野鶴，翩翩逍遙塵世間。浮波東海聽白浪，閑時牧雲南山巔。青羽拂風輕起舞，白衣飄然百事明。如今回首朝天去，不管人間得自由。[-]\n[e76041]使用:可獲得稀有坐騎—指玄。[-]"
item_ext_desc[20652] = "[ffffff]夜來攜手夢同遊，晨起盈巾淚莫收。[-]\n[e76041]收藏:傷害減免+2%[-]"
item_ext_desc[20653] = "[ffffff]清水出芙蓉，天然去雕飾[-]\n[e76041]使用：可獲得稀有神羽幻化-清水芙蓉。[-]"
item_ext_desc[20658] = "[ffffff]傳記：我是春日新花的第一抹紅，我是盞中沉香的第一縷韻。我將我的思念凝成金枝，愛慕結為玫瑰，頭戴風霜雨露，披掛日月光華，日日夜夜守候在川流不息的街口，靜靜等待，只為在某個瞬間，你一抬頭，能看見綻放的花朵。[-]\n[e76041]使用:可獲得稀有坐騎—沉薰。[-]"
item_ext_desc[20659] = "[ffffff]傳記：曾有巨鷹，青背赤頸，金冠羽衣，氣度超凡。立夏時節，巨鷹棲於昆侖山巔，待到白露則南歸。百姓見之則大喜，以其為吉獸，問之，則曰：“有鵬自遠方來，不亦樂乎？”[-]\n[e76041]使用:可獲得稀有坐騎—傲空。[-]"
item_ext_desc[20660] = "[ffffff]傳記：在西北的大山中有這樣一段傳說：純白的鹿被同族疏遠，上仙垂憐於它，給白鹿開啟靈智。得到機緣的白鹿腳踏金光，自由地飛馳於山林之間，穿梭在古樹與藤蔓中。偶爾的，進山打柴的樵夫能聽見林中傳出清亮的歌聲，遙遠縹緲，那是神秘的白鹿正在輕輕歌唱。[-]\n[e76041]使用:可獲得稀有坐騎—吟溪·神。[-]"
item_ext_desc[20661] = "[ffffff]傳記：在西北的大山中有這樣一段傳說：深林中有一只通靈的白鹿，曾經受到上仙指點，頗為神異。但白鹿有靈，從未有人得見其真身，就連每天進山打柴的樵夫們，也只在林間聽見聽見過縹緲輕柔的歌聲。樵夫們都說，那一定是白鹿所唱的歌，畢竟歌聲是如此自由而悠揚。[-]\n[e76041]使用:可獲得稀有坐騎—吟溪·聖。[-]"
