item_ext_desc[20684] = "[ffffff]傳記：我是誰？我是穿梭於林海的旅者，也是馳騁於荒原的遊俠。我如熱愛生命一樣熱愛冒險，也如熱愛寶藏一樣熱愛自然。我的故事將流傳於漫山遍野，當有人問起我的名字，我就能背起行囊，瀟灑轉身，酷酷地說上一句：“在下乃飛翔的傳奇，飛鼠莫莫是也！”[-]\n[e76041]使用:可獲得稀有坐騎—莫莫。[-]"
item_ext_desc[20685] = "[ffffff]傳記：擔心自己在新年不夠亮眼？擔心與機緣和好運失之交臂？那就叫上本喵吧，保准帶你一飛沖天，成為全中原最高、最帥、最閃耀的靚仔！看到本喵那一丈寬的巨大前爪了嗎？絕對沒有人會忽略它的！這正是“喵爪一揮，財源廣進”！[-]\n[e76041]使用:可獲得稀有坐騎—招喵。[-]"
item_ext_desc[20686] = "[ffffff]歸人望煙火，稚子候簷隙。[-]\n[e76041]收藏:暴傷減免+2%[-]"
