item_ext_desc[20704] = "[ffffff]傳記：獅生於野而為王，牛羊畏之，豺豹敬之。有黑獅，其身如幽夜，潛行於重重樹影，凝視於莽蒼眾生，長髯赤目，披掛金甲，伺機而出，疾馳如風，利爪揮落，百發百中。此乃獅中霸者，生而自由，桀驁不羈，獨遊於世間，且戰且行。[-]\n[e76041]使用:可獲得稀有坐騎—瞬影。[-]"
