item_ext_desc[20708] = "[ffffff]傳記：怎麼，盯著我看得如此出神？也罷，畢竟我是出身於塗山氏的狐狸，我族常年隱於深山，無人知曉也正常。不過，可別將我和那些尋常狐妖混為一談，我一爪子就能把它們全都收拾得服服帖帖。什麼，你說想摸摸我的尾巴？我想想……如果你向我供上鮮果，倒也不是不行。[-]\n[e76041]使用:可獲得稀有坐騎—煙魅。[-]"
