item_ext_desc[20727] = "[ffffff]傳記：呼嚕嚕，呼嚕嚕！聽見了嗎，那是我的引擎在轟鳴，那是我的血液在燃燒！我早已按捺不住飛馳的心，思緒像離弦之箭沖上九霄。賽道在腳下，終點線在前方，我只需要奔跑，不停奔跑！我堅信自己終將超過狂風，躍過流星，貼地飛行，豬突猛進！[-]\n[e76041]使用:可獲得稀有坐騎—飛馳。[-]"
