item_ext_desc[20734] = "[ffffff]傳記：黃海有河豚，河豚之大，一鍋燉不下。有時候，漁人們會從海中釣起幾丈長的河豚，鼓起來像一只圓潤的大皮球。這時候，漁人們就會給大河豚披金掛彩，慶賀一番。當然，大多時候釣起的都是不足一掌的小魚，還是把它們放生比較好。別忘了溫馨提示：不可以用河豚擦鞋哦！[-]\n[e76041]使用:可獲得稀有坐騎—逐波·神。[-]"
item_ext_desc[20735] = "[ffffff]傳記：黃海有河豚，河豚之大，可以吃半年。除了吃以外，偶爾也會有漁人突發奇想，給圓鼓鼓的河豚套上鞍，乘著這大氣球一樣的魚漂洋過海，踏浪逐波。至於控制方向的方法，據說是要靠掛著胡蘿蔔的釣竿才行。不過，河豚真的會吃胡蘿蔔嗎？[-]\n[e76041]使用:可獲得稀有坐騎—逐波·聖。[-]"
