item_ext_desc[20743] = "[ffffff]傳記：所謂俠者為何物？是避世隱居，不問天下事？亦或是寄情詩酒，遊樂山水間？非也。俠乃強者、義者，禦風而行，仗劍天涯，誅四方邪祟，救萬民於水火。故為俠者，急公好義，遇事必求速戰速決，而後拂袖去，深藏功與名！[-]\n[e76041]使用:可獲得稀有坐騎—禦風。[-]"
