item_ext_desc[20762] = "[ffffff]傳記：炎炎夏日，酷暑難耐？不如跟隨我一起去海邊！陽光、沙灘和海浪環繞，潛入深海，探尋瑰麗的魚兒和珍珠，保准你能將炎熱的煩惱忘得一乾二淨。什麼？放不下一身寶貴的裝備，又怕游泳會浮不上來？別擔心，給你這個游泳圈，帶上它，就算穿著全套鐵甲也不怕沉底！[-]\n[e76041]使用:可獲得稀有坐騎—炎炎。[-]"
