item_ext_desc[20775] = "[ffffff]百葉雙桃晚更紅，窺窗映竹見玲瓏。[-]\n[e76041]收藏:火元素防禦+100[-]"
item_ext_desc[20778] = "[ffffff]傳記：天宮謂何處，飛仙枕雲端。夢中瓊樓宇，近在咫尺間。我欲乘風渡，璨然淩霄漢。抬手摘星辰，直上九重天。扣天門，遊天宮，問天河，訪天星，攬日月，踏寰宇，敢與天公試比高！[-]\n[e76041]使用:可獲得稀有坐騎—問天。[-]"
item_ext_desc[20779] = "[ffffff]傳記：天有司霞之獸，其身赤紅，鬃若流火，鳴聲似鶴唳，奔騰如駿馬。其騰飛之時，霞漫千裏，浩浩蕩蕩，蔚為壯觀。常言道“朝霞不出門，晚霞行千裏”，故而其可以觀天相，通雨時，每逢驟雨將至，則示以霞，護佑一方農人商旅。[-]\n[e76041]使用:可獲得稀有坐騎—麟霞。[-]"
item_ext_desc[20780] = "[ffffff]十裏碧蕪幽步，一支丹杏柔情[-]\n[e76041]使用：可獲得稀有神羽幻化-曙光仙子。[-]"
item_ext_desc[20789] = "[ffffff]傳記：哢噠，哢噠，這是我奔跑的腳步聲。梧桐木和玄鐵鑄就了我的身軀，讓我能不眠不休地跑上幾個日夜，雖然天空對我這沉重的軀體來說過於遙遠，但我仍有一顆鳳凰般遨遊世界的心。就讓我用這雙機關腿，載著你去往遠方吧！[-]\n[e76041]使用:可獲得稀有坐騎—桐雀。[-]"
item_ext_desc[20790] = "[ffffff]傳記：神仙偶爾也想體驗一把垂釣的樂趣，可惜天上不像凡間，只有清風薄雲，沒有能讓魚兒棲息的水面。這可怎麼辦是好呢？一位聰慧的仙子拿起剪刀，將紅紙裁成鯉魚模樣，吹一口仙氣，放在空中，剪紙乘風而動，栩栩如生。這下在天上終於也能釣魚了！[-]\n[e76041]使用:可獲得稀有坐騎—錦湛。[-]"
item_ext_desc[20791] = "[ffffff]濁醪任冷難辭醉，黃菊因暄卻未開。[-]\n[e76041]收藏:傷害減免+2%[-]"
