item_ext_desc[20800] = "[ffffff]傳記：聽，那遠方的天空中，翻滾著一聲聲沉悶的雷鳴，藍色的閃電在潑墨似的烏雲裏若隱若現，蒸騰出白色的水汽。那是沉睡的巨獸打著呼嚕，每一次胸膛起伏的呼吸都撼天動地。這巨獸即將醒來，待到那時，睡獅一醒，吼聲驚四海，雄威撼八方。[-]\n[e76041]使用:可獲得稀有坐騎—醒時。[-]"
