item_ext_desc[20818] = "[ffffff]傳記：後羿射九日，餘一矢，玄鐵鏃，飛鴻翎。其之一射，似龍騰於野，利箭穿雲，而浩氣如虹。欲使此箭，需萬石弓，為人中英傑可禦。此箭一發，馳騁萬裏，墜似星落九天，鋒芒畢露，銀河相隨，一箭即中，從未有失。[-]\n[e76041]使用:可獲得稀有坐騎—墜雲。[-]"
item_ext_desc[20819] = "[ffffff]風急天高猿嘯哀，渚清沙白鳥飛回。[-]\n[e76041]收藏:暴擊傷害+2%[-]"
item_ext_desc[20821] = "[ffffff]傳記：人類都說“宰相肚裏能撐船”，你看看我這胖胖的小肚子，是不是特別有當宰相的潛力？偷偷告訴你，我可是吃竹子長大的，虛懷若竹那說的就是我。我的小肚子裏可不僅能撐船，還能充氣！當它充滿熱騰騰的空氣時，我就會變得輕飄飄，軟綿綿，晃晃悠悠，可以飛天！[-]\n[e76041]使用:可獲得稀有坐騎—若竹。[-]"
