item_ext_desc[20843] = "[ffffff]傳記：帝王出行，儀仗甚繁。公卿引路，太僕駕車，將軍護衛，列陣兩旁，大小車輛，並駕齊驅，旌旗如雲，鼓樂如雷。帝王乘車，金輪玉輿，華蓋相擁，富麗堂皇。端坐車上，睨視臣子眾生，坐擁江山社稷，此帝王霸氣，天下無二。[-]\n[e76041]使用:可獲得稀有坐騎—帝星。[-]"
item_ext_desc[20844] = "[ffffff]傳記：世人知魚生於水，卻不知我生於冰。能在冰中暢遊的魚，全天下除了我以外，恐怕也很難發現第二個了吧？每當陽光穿過冰層，就會被分散成五顏六色的光芒，層層疊疊像萬花筒般炫目，置身其中，就像是進入夢中世界。可惜這等美景只有我看得到，什麼時候能有個人來陪我一起欣賞呢？[-]\n[e76041]使用:可獲得稀有坐騎—寒魄。[-]"
