item_ext_desc[20855] = "[ffffff]傳記：號外！號外！城外出現一只來路不明的白貓，每天在城門口小樹林中閒逛。城中居民給這只貓投餵食物，發現它越長越大，最初只有普通貓咪的大小，現在已經超過了一只小馬，而且根本停不下來！有專家稱，大家應該對它持謹慎態度，因為它可能不是一只真正的貓……[-]\n[e76041]使用:可獲得稀有坐騎—靈軒·神。[-]"
item_ext_desc[20856] = "[ffffff]傳記：號外！號外！城外出現的不明大貓近日被發現翻牆溜進城裏。城中侍衛本來打算將這只大貓捉起來，卻發現它所到之處，老鼠竟被吃得一乾二淨，城中的衛生環境也連日變好。大貓由於捉鼠有功，現已被封為禦前一品捕鼠官，可喜可賀！[-]\n[e76041]使用:可獲得稀有坐騎—靈軒·聖。[-]"
