item_ext_desc[20868] = "[ffffff]傳記：在人們的夢中有這樣一匹駿馬，頭上長著細長的獨角，穿梭在森林斑駁的光影之間。它來無影，去無蹤，只在最深的沉夢中現身，留下驚鴻般的一瞥，隨即又像破曉時分的晨霧那樣悄然離去。或許會有人用紙折出它的身影，但這究竟是虛妄的幻想，亦或是真實的記憶？[-]\n[e76041]使用:可獲得稀有坐騎—幻夢。[-]"
