item_ext_desc[20874] = "[ffffff]傳記：路漫漫兮海滄滄，雲帆高掛將起航。幾經驟雨迎風霜，歷盡狂雷勇踏浪。海角天涯是歸處，看盡波濤遇繁花。此行萬裏終不悔，飄搖自在忘憂傷。[-]\n[e76041]使用:可獲得稀有坐騎—忘憂。[-]"
