item_ext_desc[20894] = "[ffffff]傳記：以銅為鏡，可以正衣冠。以史為鏡，可以知興替。以人為鏡，可以明得失。故君子佩鏡，非自憐容貌俊朗，而為正其行。撫鏡自省，思忠信，樂於學，明己志，映自身，澄澈通明。[-]\n[e76041]使用:可獲得稀有坐騎—明鏡。[-]"
