item_ext_desc[20899] = "[ffffff]傳記：青春總是美好而短暫，就像夜色中閃亮的星辰和斑斕的燈火，破曉時便會不見，只留下悠悠記憶。只可惜，人們總是容易忘卻，記憶也隨著時間蒙塵。而我就是那承載記憶的馬兒，在轉瞬即逝的韶光裏，我奔騰，我旋轉，我飛馳，我回還，只為能讓記憶永遠停駐。[-]\n[e76041]使用:可獲得稀有坐騎—旋憶。[-]"
item_ext_desc[20900] = "[ffffff]傳記：城裏的匠人們最近淘來一張不知出自哪里的設計圖，圖上畫著一個帶翅膀的怪東西，好像叫“飛機”。匠人們按照步驟，用竹片和紙做出這飛機，找了個無風的晴朗日子從城樓頂上放飛，看它雙翼乘風飛翔在青空之上，瀟灑而自由。[-]\n[e76041]使用:可獲得稀有坐騎—青空。[-]"
