item_ext_desc[20907] = "[ffffff]傳記：月照當空，華燈初上，錦衣夜行而為何？夜宴將至，絲竹才興，廣袖曼舞，珍饈玉盤。月華明珠交映，綾羅錦緞如織，駿馬金車引路，鸞鳳蛟龍相迎。仙宮門開，鐘鼓齊鳴，夜宴將至，靜待四海貴客。[-]\n[e76041]使用:可獲得稀有坐騎—夜宴·神。[-]"
item_ext_desc[20908] = "[ffffff]傳記：月照當空，華燈初上，錦衣夜行而為何？夜宴正歡，雅興盎然，觥籌交錯，談笑席間。琴棋書畫鬥豔，詩詞歌賦爭鳴，美酒佳餚不絕，流觴曲水綿延。四海賓客，廣結知己，良辰恒久，此刻夜宴正歡。[-]\n[e76041]使用:可獲得稀有坐騎—夜宴·聖。[-]"
