item_ext_desc[20916] = "[ffffff]傳記：曹丞相近日身體虛乏，心慌氣短，經太醫診斷，此乃富貴病，凡藥不可醫，唯減重輕體可解。遂有能工巧匠贈一浮游飛板，觸動機關，則有七色光芒閃爍，鼓瑟樂聲入耳。隨之舞動，身影翩躚，不出多時即大汗淋漓，身心舒暢。丞相受之，使用數月，身輕體健，再現往日英姿。[-]\n[e76041]使用:可獲得稀有坐騎-翩躚。[-]"
