item_ext_desc[20922] = "[ffffff]傳記：如何制墨？取桐油，焚烈焰，采凝灰，曆千錘，精雕成形，細飾金箔，終成一墨。點染金睛，則化麒麟飛騰。所行之處，潑墨為天地，揮毫作山川，鋪色繪日月，駐筆點鶴仙。海納萬物，沉穩如山者，是為墨魂。[-]\n[e76041]使用:可獲得稀有坐騎-墨魂·神。[-]"
item_ext_desc[20923] = "[ffffff]傳記：如何制墨？取桐油，焚烈焰，采凝灰，曆千錘，精雕成形，細飾金箔，終成一墨。點染金睛，則化麒麟飛騰。所行之處，焦墨作山林，濃墨勾廊簷，清墨結冰雪，淡漠鋪遠山。變化萬千，靈韻天成者，是為墨魂。[-]\n[e76041]使用:可獲得稀有坐騎-墨魂·聖。[-]"
item_ext_desc[20924] = "[ffffff]傳記：那在夜色中賓士而過的是什麼？是潔白無瑕的流光，還是暗香浮動的玉蓮？在月華的映照下，它朦朦朧朧地散發著光輝，輕盈地駛來。纖細的白色藤蔓是它的雕樑畫棟，明亮的黃金飾帶是它的御座冠冕。它似雪，更勝雪，不沾染半點塵埃。[-]\n[e76041]使用:可獲得稀有坐騎-勝雪。[-]"
