item_ext_desc[20958] = "[ffffff]傳記：有鷹居於山之巔，翼丈餘，體如獅，羽色赤青，喙鋒爪利，鳴聲如雷，以豺狼為食。巨鷹一躍，騰飛直上，翼下之風，呼嘯不絕，如利劍劈雲海，似金釵劃天穹。攜飛仙，攬明月，渡浮雲，傲長空。[-]\n[e76041]使用:可獲得稀有坐騎-渡雲。[-]"
item_ext_desc[20959] = "[ffffff]傳記：傳記：暫無。[-]\n[e76041]使用:可獲得稀有坐騎-鈴蘭。[-]"
item_ext_desc[20960] = "[ffffff]傳記：高祖于南山得一鐵劍，長三尺，銘曰\"赤霄\"。其劍通赤，色如瀝血，熾似流火，焚風纏繞。劍中宿一龍魄，故而劍鳴若龍吟，劍風若龍騰，劍光若龍焰。此劍既出，龍形既現，赤光傾天，威懾百里。此帝道之劍，絕世無雙。[-]\n[e76041]使用:可獲得稀有坐騎-赤霄。[-]"
item_ext_desc[20961] = "[ffffff]為近都門多送別，長條折盡減春風。[-]\n[e76041]收藏:雷元素防禦+100[-]"
