item_ext_desc[20975] = "[ffffff]傳記：山不在高，有油則靈。水不在深，有槳就行。摩托萬種，唯我兩栖。陸上跑得快，平原萬里行。渡海訪蓬萊，逆流尋蘭汀。可以逐流雲，探辰星。所及之處皆成路，所見之景盡是情。風馳電掣，無所不行。[-]\n[e76041]使用:可獲得稀有坐騎-戲浪。[-]"
