item_ext_desc[20992] = "[ffffff]傳記：在高懸九天的蛾眉月上，清幽寧靜的廣寒宮中，嫦娥是否也會為寂寥而垂淚？淚珠伴著月光落下，澆灌出純白的月之花。在花盛開的新月夜，將它們一朵朵采下、編織、纏繞，做成潔白無瑕的搖籃。這搖籃搖啊，搖啊，飛向月亮的故鄉。[-]\n[e76041]使用:可獲得稀有坐騎-白瑜。[-]"
