item_ext_desc[21012] = "[ffffff]珠袖輕綃卷翠雲，日暮天寒倚修竹[-]\n[e76041]使用：可獲得稀有神羽幻化-清穀幽蝶。[-]"
item_ext_desc[21014] = "[ffffff]傳記：有書生屢試不中，鬱鬱寡歡，遂隻身一人，對月獨酌，借酒澆愁。醉而夢一仙人駕車自天降，邀其共遊。二人乘車，不懼路遠海闊，瞬息萬里，觀歷史興替，覽天下奇景，憂思愁緒，皆拋於腦後。書生正喜，忽而夢醒，歎曰：\"浪蕩浮生飄搖過，若夢空醒兩袖風。\"[-]\n[e76041]使用:可獲得稀有坐騎-浮生。[-]"
item_ext_desc[21015] = "[ffffff]一枚雕刻著精緻龍紋的和田玉佩，散發著淡淡的光澤，在中原十分罕見。[-]\n[e76041]獲得：光棍節活動開啟期間，通過“六龍慶典”中“誠心祈緣”介面進行簽到獲得。\n使用：光棍節活動開啟期間，集齊六枚“西域龍佩，可以”通過“六龍慶典”中“誠心祈緣”介面兌換專屬稱號。[-]\n[ffff00]“這樣東西是兌換大獎的唯一憑證，還請將軍妥善保管，遺失不補哦。”——段瑢[-]"
item_ext_desc[21024] = "[ffffff]可領取稱號<柱國將軍>。[-]\n[e76041]裝備後可獲得主動屬性\n物理攻擊+4000\n法術攻擊+4000[-]"
