item_ext_desc[21027] = "[ffffff]人言華髮因愁早。勸我消愁惟酒好。[-]\n[e76041]收藏:火元素防禦+100[-]"
item_ext_desc[21031] = "[ffffff]傳記：越是冬意漸濃，越讓人期盼早些春暖。待到百草蘇生、百鳥齊唱時，挽著花籃踏青遊玩，衣袂在春風裡翩翩飛舞，撫摸過香草與鮮花，留下陣陣暗香浮動，直至裝滿竹籃，花香欲溢。唯此真國色，開時動京城。[-]\n[e76041]使用:可獲得稀有坐騎-絕色。[-]"
item_ext_desc[21032] = "[ffffff]傳記：詩人在深秋乘船，沿江順流而下，遊山玩水。至一淺灘，水面驟然開闊，天朗氣清，遠山似畫卷徐徐展開。詩人畫意大興，欲提筆著墨，卻苦於未備畫紙，遂靈機一動，要來船上的紙燈籠，揮筆作畫於其上。山水秀雅，雲出其間，這正是\"江移林岸微，岩深煙岫複\"。[-]\n[e76041]使用:可獲得稀有坐騎-雲岫·神。[-]"
item_ext_desc[21033] = "[ffffff]傳記：一個詩人乘船遊玩時，心為美景所觸動，畫意大興，在船家的紙燈籠上作了一幅山水畫。畫中水闊山秀，林翠竹青，只是看著，就讓人仿佛感覺清風拂面，心生平靜的喜悅。這幅畫隨著燈籠和小船，散發著微光飄過萬水千山，遊過激流與淺灘，將這景色帶向遠方。[-]\n[e76041]使用:可獲得稀有坐騎-雲岫·聖。[-]"
item_ext_desc[21034] = "[ffffff]鳳凰臺上鳳凰遊，鳳去台空江自流[-]\n[e76041]使用：可獲得稀有神羽幻化-青凰幻化。[-]"
