item_ext_desc[21040] = "[ffffff]傳記：滴滴。滴滴。車輛經過，請注意讓行。我的車輪快過汗血寶馬，我的引擎轟若電閃雷鳴，我的旅程乃是道路盡頭。不過，就算是我也要吃飯呀，車是鐵，油是鋼，一頓不加餓得慌。只有吃飽了，我才能帶你看山看水，尋幽訪道呀。[-]\n[e76041]使用:可獲得稀有坐騎-疾風。[-]"
