item_ext_desc[21049] = "[ffffff]傳記：漁民們相傳，在遠洋上有一位名聲遠揚的大船長，他駕駛著黑色的帆船，往返於島嶼之間，行蹤莫測。據說這位船長曾在海上斬殺蛟龍，並于龍腹之中獲一寶劍。這把劍浸潤龍血，通身赤紅，溫熱似活物。得之者稱雄五洋，是為號令萬船之證。[-]\n[e76041]使用:可獲得稀有坐騎-虹銘·神。[-]"
item_ext_desc[21050] = "[ffffff]傳記：漁民們相傳，在遠洋上有一位名聲遠揚的大船長，他曾在海上斬殺蛟龍，並于龍腹之中獲一寶劍。這把劍作為身份與地位的象徵，被船長秘密埋藏在某個不為人知的島上，只留下記載著隻言片語的密函作為線索，留傳世間。據說，找到這把劍的人，終將成為這廣闊海洋上的霸主。[-]\n[e76041]使用:可獲得稀有坐騎-虹銘·聖。[-]"
item_ext_desc[21051] = "[ffffff]傳記：一旅者攀登雪山，不慎失足掉進冰縫，遇到一隻巨獸。這只巨獸以寒冰為胸腹，玄鐵為鱗甲，目光似箭，利爪尖牙，輕而易舉就將旅者叼了起來。就在旅者以為自己即將被巨獸吞吃入腹之際，只見那巨獸輕輕一躍，攀著冰縫嶙峋的崖壁，跳到了地面上，在放下旅者後，悠然離去。[-]\n[e76041]使用:可獲得稀有坐騎-幽玄。[-]"
item_ext_desc[21052] = "[ffffff]集齊100個該道具可合成1個綁定的完整的幽玄。[-]\n[e76041]通過合成獲得的幽玄是綁定的。[-]"
item_ext_desc[21053] = "[ffffff]振衣千仞崗，濯足萬里流[-]\n[e76041]使用：可獲得稀有神羽幻化-松風幻化。[-]"
item_ext_desc[21054] = "[ffffff]出處已不可考，流傳多年仍然散發著典雅的輝光[-]\n[e76041]使用：可獲得全新法器-紫黛。[-]"
item_ext_desc[21057] = "[ffffff]傳記：豹藏于林，其爪鋒芒如刀，其翼光輝似虹。時而隱形匿跡，輕聲緩步，千里尋蹤，只為一擊致命，時而舒展翼翅，躍上九天，比肩流雲，翱翔俯瞰萬山。此為林中霸者，天際之尊，無慮無憂，如豹添翼。[-]\n[e76041]使用:可獲得稀有坐騎-獵翼。[-]"
item_ext_desc[21058] = "[ffffff]傳記：天氣漸漸變冷，我也要抓緊時間儲備過冬糧。蹦蹦，跳跳，到處找找--泥土中未被發現的銀杏果，松針裡悄悄冒出的紅蘑菇，落葉下麵或還許隱藏著胡蘿蔔？只有把我藏食物的小樹洞填得滿滿當當，我才能在下雪的日子裡高枕無憂，呼呼大睡呀。[-]\n[e76041]使用:可獲得稀有坐騎-絨絨。[-]"
item_ext_desc[21059] = "[ffffff]雲中君不見，競夕自悲秋。[-]\n[e76041]收藏:暴傷減免+2%[-]"
