item_ext_desc[10000014] = "[ffffff]打開有機率獲得高級寶石、煉星石、洗煉石、地術殘頁等道具，較低機率能獲得聖誕老人送出的冬季戀歌時裝禮包（永久）。[-]" 
item_ext_desc[10000015] = "[ffffff]打開有機率獲得無字天書殘卷、無字天書、靈羽、馬草及地術殘卷[-]" 
item_ext_desc[10000016] = "[ffffff]天機不可洩露，打開天機福袋，將有機會隨機獲得以下物品：時裝（未打開時非綁定）、中級鎖定符、靈妖魂魄、通牒、寶石禮包等虛寶。較低機率可獲得稀有坐騎千機（非綁定）。[-]" 
item_ext_desc[10000017] = "[ffffff]御龍在天，八荒降臨。打開有機率獲得上古兵策、地術殘卷、神羽、馬草、高級寶石、強化裝備品等超值虛寶。較低機率更可獲得八荒蠻靈翅膀幻化、時裝等稀有物品。[-]" 
item_ext_desc[10000018] = "[ffffff]打開後可獲得盛世國威永久時裝。[-]\n[ff7d00]該禮包可以在拍賣行進行交易。禮包打開後時裝將綁定無法交易。[-]" 
item_ext_desc[10000019] = "[ffffff]遠古青龍的祝福即將消失，你僅有一次機會抓住它，打開後可獲得100綁鑽、馬草*20、神羽*20、東周卡牌.無雙、地術殘卷（綁定）。[-]" 
item_ext_desc[10000020] = "[ffffff]遠古青龍的祝福即將消失，你僅有一次機會抓住它，打開後可獲得400綁鑽、馬草*40、神羽*40、東周卡牌.雙雄、通靈神冊（綁定）*2。[-]" 
item_ext_desc[10000021] = "[ffffff]遠古青龍的祝福即將消失，你僅有一次機會抓住它，打開後可獲得1000綁鑽、馬草*60、神羽*60、東周卡牌.三英、無字天書（綁定）*4。[-]" 
item_ext_desc[10000022] = "[ffffff]遠古青龍的祝福即將消失，你僅有一次機會抓住它，打開後可獲得1300綁鑽、馬草*100、神羽*100、東周卡牌.四傑、地術殘卷（綁定）*6。[-]" 
item_ext_desc[10000023] = "[ffffff]曾經有一包玲瓏福袋在我面前，我沒有打開，如果上天再給我一次機會，我要開開開爆它。神奇的玲瓏福袋將有機會讓你獲得120-888綁鑽。（每日僅可購買6次）。[-]" 
