item_ext_desc[10000126] = "[ffffff]沒錯，我就是一個西瓜。[-]\n[e76041]55級以上的玩家可以考慮把我送給夏日六龍大使。[-]"
item_ext_desc[10000127] = "[ffffff]打開後會獲得一個西瓜，用於夏日繽紛活動。同時有機率獲得綠色韜略果、馬草、虎符、龍符、3級保底符、4級保底符、7級寶石和8級寶石。更有較小機率獲得稀有坐騎暗毀和閃電。[-]"
item_ext_desc[10000128] = "[ffffff]打開後可獲得豐碩獎勵。[-]"
item_ext_desc[10000130] = "[ffffff]打開後有機率獲得4級原石、4級皮料、千媚蓮燈碎片、綠酒、無字天書(綁)、地術殘卷(綁)、汜水關通牒、上古兵策等。有較小機率獲得稀有坐騎赤虹、春熙時裝、松濤如雷、蝶舞翅膀。[-]"
item_ext_desc[10000131] = "[ffffff]2016年限定時裝[-]"
item_ext_desc[10000132] = "[ffffff]2016年限定時裝[-]"
item_ext_desc[10000133] = "[ffffff]打開後可獲得粽子，並可隨機獲得龍符、虎符、春秋遺物、3至6級隨機寶石、2級煉星石和3級煉星石。較小幾率獲得翅膀幻化緋紅女王、稀有坐騎赤虹和仙鹿。[-]"
item_ext_desc[10000134] = "[ffffff]打開可隨機獲得上古兵策、上古兵卷、3級銘文、法器精華或馬草。較小幾率獲得翅膀幻化火烈鳥、稀有坐騎夜襲和千機。[-]"
item_ext_desc[10000135] = "[ffffff]香甜的豆沙中蘊藏著奇妙和驚喜，打開後可獲得：端午粽子*2、100點龍符*5、委託通兌令*2、2級隨機銘文*2、地術殘卷(綁)*1[-]"
item_ext_desc[10000136] = "[ffffff]肥而不膩的新鮮肉粽、吃後口齒留香，打開後可獲得：端午粽子*3、100綁定鑽石、委託通兌令*3、地術殘卷(綁)*2[-]"
item_ext_desc[10000137] = "[ffffff]芳香四溢的艾葉下包裹著的人間美味，打開後可獲得：端午粽子*5、400綁定鑽石、委託通兌令*5、通靈神章(綁)*3[-]"
item_ext_desc[10000138] = "[ffffff]選用天地間七種最具靈性的食材蒸制而成，此粽只應天上有，打開後可獲得：端午粽子*10、888綁定鑽石、委託通兌令*10、無字天書(綁)*5[-]"
item_ext_desc[10000139] = "[ffffff]打開後可隨機獲得豐厚的獎勵。[-]\n[e76041]這是一個神奇的粽子，裡面包裹著各種稀奇古怪的玩意兒……[-]"
