item_ext_desc[10000154] = "[ffffff]糖果家族中的明星，深受孩子和大人的喜愛，打開後可以獲得：傳奇百寶箱*1、50點榮譽值*10、100點龍符*1、地術殘卷(綁)*1[-]"
item_ext_desc[10000155] = "[ffffff]甜甜的味道，還可以吹出透明泡泡的美味糖果，打開後可以獲得：傳奇百寶箱*2、50點榮譽值*20、100點龍符*2、100綁定鑽石、通靈神冊(綁)*2[-]"
item_ext_desc[10000156] = "[ffffff]軟綿柔和，糖漿中帶著滿滿的甜蜜，打開後可以獲得：傳奇百寶箱*3、50點榮譽值*30、100點龍符*3、400綁定鑽石、地術殘卷(綁)*3[-]"
item_ext_desc[10000157] = "[ffffff]一顆包含著神奇能量的糖果，據說吃完能打十個，打開後可以獲得：傳奇百寶箱*4、50點榮譽值*40、100點龍符*4、888綁定鑽石、無字天書(綁)*5[-]"
item_ext_desc[10000158] = "[ffffff]打開後有機率獲得馬草、小妖魂魄、靈妖魂魄、2級煉星石、3級煉星石、無字天書殘卷、地術殘頁、2級保底符、3級保底符、4級保底符等。有較小機率獲得稀有坐騎年獸、萬紫飛鳶翅膀。[-]"
item_ext_desc[10000159] = "[ffffff]打開後有機率獲得2級煉星石、3級煉星石、4級煉星石、2級保底符、3級保底符、4級保底符、100點虎符、100點龍符等。有較小機率獲得稀有坐騎夜襲、法器赤焰龍璧及其碎片。[-]"
item_ext_desc[10000160] = "[ffffff]打開後有機率獲得1級銘文、2級銘文、3級銘文、3級寶石、4級寶石、5級寶石、6級寶石、7級寶石、馬草、地術殘頁（綁定）等。有較小機率獲得稀有坐騎赤虹、稀有坐騎暗毀。[-]"
item_ext_desc[10000161] = "[ffffff]打開後有機率獲得地術殘頁（非綁）、天書殘卷（綁）、通靈神冊（綁）、洗髓丹*5、3級寵物口糧*3、2級隨機銘文、煉妖丹*5等。有較小機率獲得稀有坐騎夜襲、稀有坐騎閃電、稀有時裝朱紅華彩。[-]"
item_ext_desc[10000162] = "[ffffff]打開後有機率獲得3級隨機銘文、夜明珠、靈妖魂魄、小妖魂魄*2、靈羽*20、高級鎖定符、3級保底符等。有較小機率獲得稀有坐騎朱炎、稀有坐騎年獸、稀有法器赤炎龍壁。[-]"
item_ext_desc[10000163] = "[ffffff]打開可隨機獲得馬草、上古兵策、春秋遺物•勝戰、春秋遺物•敵戰、2級銘文、3級銘文、4級銘文。有較小機率獲得稀有時裝消愁、稀有坐騎夜襲或全新坐騎碎片雪月之輝（100個合成雪月坐騎）。[-]\n[e76041]觀雪之純淨，享夜之靜謐。[-]"
item_ext_desc[10000164] = "[ffffff]打開必定獲得1個神秘靈寵蛋碎片。同時可隨機獲得綠色豪傑酒、紫色豪傑酒、屈原卡牌、伍子胥卡牌、闔閭卡牌、夫差卡牌、龍旗（劃龍舟消耗品）。有較小機率獲得紫色品質高級寵物熊貓人（非綁）、斷水時裝（非綁）、雪月之輝碎片（100個合成坐騎）、暗毀坐騎（非綁）。[-]"
item_ext_desc[10000165] = "[ffffff]打開可隨機獲得馬草、上古兵策、春秋遺物•勝戰、春秋遺物•敵戰、2級銘文、3級銘文、4級銘文。有較小機率獲得稀有時裝消愁、稀有坐騎朱炎或坐騎碎片流霜之輝（100個合成流霜坐騎）。[-]"
item_ext_desc[10000166] = "[ffffff]打開可獲得5個3級保底符。[-]"
item_ext_desc[10000167] = "[ffffff]打開可獲得3個4級保底符。[-]"
item_ext_desc[10000168] = "[ffffff]打開後有機率獲得馬草、4級銘文、3級銘文、夜明珠、委託令、2級銘文、上古兵卷、上古兵策等。有較小機率獲得稀有坐騎夜襲、時裝鬥牛、冰離之輝。[-]"
item_ext_desc[10000169] = "[ffffff]打開後必獲得維尼蛋碎片或湯姆蛋碎片之一，同時有幾率獲得流霜之輝、赤焰龍壁碎片、3級銘文、夜明珠、委託令、2級銘文、4級寶石禮包、靈羽、3級保底符，有較小幾率獲得稀有坐騎年獸、時裝斷水。[-]"
item_ext_desc[10000170] = "[ffffff]打開後有機率獲得朱炎之輝（非綁）、雪月之輝（非綁）、5級原石、5級皮料、小妖魂魄、靈妖魂魄、天書殘卷（綁）、夜明珠、精華碎片、高級鎖定符、3級保底符等。有較小機率獲得稀有坐騎朱炎（非綁）、雪月（非綁），稀有時裝消愁（非綁）。[-]"
item_ext_desc[10000171] = "[ffffff]打開後有機率獲得赤虹之輝（非綁）、夜襲之輝（非綁）、5級原石、5級皮料、小妖魂魄、靈妖魂魄、地術殘頁（非綁）、夜明珠、精華碎片等。有較小機率獲得稀有坐騎赤虹（非綁）、夜襲（非綁），稀有翅膀蝶舞（非綁）。[-]"
item_ext_desc[10000172] = "[ffffff]集齊100個該道具可合成1個綁定的完整的朱炎。[-]\n[e76041]通過合成獲得的朱炎是綁定的。[-]"
