item_ext_desc[10000212] = "[ffffff]打開周年紀念禮盒·天，獲得600綁定鑽石、4級寶石禮包*2、馬草*60、2級體力丹*6、通靈神冊(綁)*3[-]"
item_ext_desc[10000213] = "[ffffff]打開周年紀念禮盒·神，獲得1000綁定鑽石、5級寶石禮包*1、馬草*100、2級體力丹*10、無字天書(綁)*5[-]"
item_ext_desc[10000214] = "[ffffff]鴻鵠相隨飛，飛飛適荒裔。[-]\n[e76041]使用之後獲得稀有坐騎—鴻鵠。[-]"
item_ext_desc[10000215] = "[ffffff]使用之後獲得稀有坐騎—曜夜。[-]"
item_ext_desc[10000216] = "[ffffff]靈寵魔盒風，打開後可隨機獲得可心熊寵物蛋、金角象寵物蛋、1-5級寵物口糧、煉妖包·人、煉妖包·地、洗髓丹、天心鑰、5級皮料、5級原石、3級隨機銘文、東周卡包·無雙、高級鎖定符。更有較小幾率獲得紫色品質的全新寵物章魚哥哥、寵物資質永久提升道具龍骨。[-]\n[e76041]寵物大作戰的時代開啟了。[-]"
item_ext_desc[10000217] = "[ffffff]使用之後獲得精美時裝——冰火之歌。[-]"
item_ext_desc[10000218] = "[ffffff]坐騎包天，打開後獲得220棵馬草。[-]"
item_ext_desc[10000219] = "[ffffff]時光魔盒冰，使用之後概率獲得稀有坐騎鴻鵠。[-]"
item_ext_desc[10000221] = "[ffffff]內含黃巾密信*1、煉妖丹*10。[-]\n[e76041]專屬貴族19每日禮包。[-]"
item_ext_desc[10000222] = "[ffffff]內含黃巾密信*1、煉妖丹*20、馬草*66。[-]\n[e76041]專屬貴族20每日禮包。[-]"
item_ext_desc[10000220] = "[ffffff]飛麟福袋。[-]"
item_ext_desc[10000223] = "[ffffff]鋼尾非綁定。[-]"
item_ext_desc[10000224] = "[ffffff]金尾非綁定。[-]"
item_ext_desc[10000225] = "[ffffff]使用後可獲得直掛雲帆翅膀，自由飛翔，無拘無束！[-]"
item_ext_desc[10000226] = "[ffffff]鋼尾坐騎的碎片，100個可合成一隻完整的鋼尾坐騎！[-]"
item_ext_desc[10000227] = "[ffffff]金尾坐騎的碎片，100個可合成一隻完整的金尾坐騎！[-]"
item_ext_desc[10000228] = "[ffffff]打開金尾魔盒有機率獲得：4-7級寶石、5級原石、5級皮料、靈妖魂魄、馬草、靈羽、春秋遺物、夜明珠；有一定機率可獲得稀有坐騎金尾（非綁）、稀有坐騎醉仙（非綁）。金尾魔盒擁有神奇的魔力！[-]"
item_ext_desc[10000229] = "[ffffff]打開精靈魔盒有機率獲得：龍骨（綁定）、洗髓丹、煉妖丹、馬草、3-5級寵物口糧、精華囊·人、上古兵卷、上古兵書、上古兵策、5級寶石等；有一定機率可獲得稀有坐騎銀風（非綁）、稀有寵物南瓜傑克（非綁）、稀有法器波板糖碎片（非綁）。精靈魔盒擁有神奇的魔力！[-]"
item_ext_desc[10000230] = "[ffffff]打開聖誕寶盒必定獲得聖誕襪子*1（每日限量開啟）。同時有機率獲得：4-7級寶石、魂魄碎片、小妖魂魄、靈妖魂魄、春秋遺物、馬草、紫色韜略果；有一定機率可獲得稀有坐騎獅鷲（非綁）、超稀有限定聖誕時裝-冰雪奇緣（非綁）、稀有坐騎醉仙（非綁）。聖誕寶盒擁有神奇的魔力！[-]"
item_ext_desc[10000231] = "[ffffff]打開時光魔盒·火後必定獲得地術殘頁（非綁）、天書殘卷（綁）、通靈神章（非綁）之一。並額外有機率獲得金尾坐騎（非綁）、曜夜之輝（非綁）、謠夜之輝（非綁）、赤虹之輝（非綁）、破山·聖之輝（非綁）、馬草、4-7級寶石等。時光魔盒·火擁有神奇的魔力！[-]"
item_ext_desc[10000232] = "[ffffff]聽說吃了這個雞蛋的人會變得更幸福。打開幸福雞蛋可獲得：全民敦厚紅包*1、上古兵略*5、魂魄碎片*10、3級寶石禮包*1、2級體力丹*10、地術殘卷（綁）*1[-]"
item_ext_desc[10000233] = "[ffffff]聽說吃了這個雞蛋的人會變得更健康。打開健康雞蛋可獲得：全民精緻紅包*1、上古兵略*10、魂魄碎片*20、5級寶石禮包*1、發丘印（小）*1、通靈神冊（綁）*2[-]"
item_ext_desc[10000234] = "[ffffff]聽說吃了這個雞蛋的人會變得更好運。打開好運雞蛋可獲得：300綁定鑽石*1、春秋遺物·攻戰*5、魂魄碎片*40、馬草*40、發丘印（小）*1、地術殘卷（綁）*2[-]"
item_ext_desc[10000235] = "[ffffff]聽說吃了這個雞蛋的人會發大財。打開發財雞蛋可獲得：500綁定鑽石*1、春秋遺物·攻戰*10、天賦精華*100、馬草*60、發丘印（大）*1、通靈神冊（綁）*5[-]"
item_ext_desc[10000236] = "[ffffff]這是一個和平紀念雞蛋，祝願世界永遠和平！打開和平雞蛋可獲得：1000綁定鑽石*1、春秋遺物·攻戰*20、天賦精華*200、馬草*100、龍骨*1、無字天書（綁）*8[-]"
