item_ext_desc[10000263] = "[ffffff]神龍禮包·帝。[-]"
item_ext_desc[10000264] = "[ffffff]打開聖甲魔盒將會獲得以下道具之一（必定獲得一張活動憑證：神龍寶券·甲）：人皇遺篇（綁）、人皇斷篇（綁）、光羽、馬草、4-7級寶石、寶玉、秘隕、魂魄碎片等。有一定機率獲得聖甲坐騎（非綁）、銀風坐騎（非綁）、冬日禮贊時裝（非綁）喔！聖甲魔盒擁有神秘的力量！688包內必出聖甲坐騎。[-]"
item_ext_desc[10000265] = "[ffffff]開啟禮包後可獲得永久的時裝冬日禮贊。[-]"
item_ext_desc[10000266] = "[ffffff]打開蒼嵐之淚將會獲得以下道具之一：人皇遺篇（綁）、人皇斷篇（綁）、光羽、馬草、4-7級寶石、煉妖丹、3級寵物口糧、洗髓丹等。有一定機率獲得駭翼坐騎（非綁）、蒼嵐翅膀（非綁）、古韻清秋時裝（非綁）喔！蒼嵐之淚擁有神秘的力量！688包內必出駭翼坐騎。[-]"
item_ext_desc[10000268] = "一張平淡無奇的圖紙憑證，已過時效，現在看來並沒有什麼用處。"
item_ext_desc[10000269] = "[ffffff]王城某個地方的寶藏之一，打開聖書寶匣後可獲得馬草*50、地術殘卷(綁)*1、無字天書(綁)*1、通靈神冊(綁)*1、人皇遺篇(綁)*1。[-]"
item_ext_desc[10000270] = "[ffffff]虎嘯而穀風至兮，龍舉而景雲往兮。[-]\n[e76041]使用之後獲得稀有坐騎—絕影。[-]"
item_ext_desc[10000271] = "[ffffff]逆鱗幡象生，混沌天地空。[-]\n[e76041]使用之後獲得稀有坐騎—赤影。[-]"
item_ext_desc[10000272] = "[ffffff]快樂的味道，融化在心口，甜甜的。使用之後可以獲得鮮花*288、馬草*28、發丘印(小)*1、地術殘卷(綁)*1。（每日限購一次）[-]"
item_ext_desc[10000273] = "[ffffff]幸福的滋味，融化在心口，美美的。使用之後可以獲得鮮花*588、馬草*58、發丘印(大)*1、通靈神冊(綁)*2。（每日限購一次）[-]"
item_ext_desc[10000274] = "[ffffff]打開福袋必定獲得鮮花*9。同時有機率獲得：馬草、人皇遺篇(綁)、地術殘卷(綁)、通靈神冊(綁)、春秋遺物、精華囊·人、煉妖包·人、4級寶石禮包、祭品禮袋等獎勵；有一定機率可獲得稀有坐騎絕影(非綁)、稀有時裝-斷水(非綁)！520包內必出絕影坐騎。[-]"
item_ext_desc[10000275] = "[ffffff]打開福袋將會獲得以下道具之一：馬草、靈羽、夜明珠、上古兵策、4~7級寶石禮包、5級原石、5級皮料、靈妖魂魄等。有一定機率可以獲得坐騎-星槎(非綁)、坐騎-赤影(非綁)！赤星之影擁有神秘魔力！666包內必出星槎坐騎。[-]"
item_ext_desc[10000276] = "[ffffff]打開福袋將會獲得以下道具之一：人皇遺篇(綁)、人皇斷篇(綁)、馬草、光羽、寶玉、秘隕、魂魄碎片、4~7級寶石禮包、5級寵物蛋口糧等。有一定機率可以獲得坐騎-吉祥(非綁)、坐騎-鋼尾(非綁)！吉祥之光·限擁有神秘魔力！666包內必出鋼尾坐騎。[-]"
item_ext_desc[10000277] = "[ffffff]打開後有機率獲得馬草、3-5級寵物口糧、煉妖丹、坐騎喚醒寶珠、4~5級寶石禮包、3級保底符、無字天書(綁)、人皇斷篇(綁)等。有較小機率獲得全新稀有聖獸坐騎青龍之靈(非綁)、稀有坐騎曜夜(非綁)。打開666個內必出曜夜！[-]\n[e76041]飄若遊雲，矯若驚龍。[-]"
item_ext_desc[10000278] = "[ffffff]打開後有機率獲得馬草、4~6級寶石禮包、春秋遺物、洗髓丹、魂魄碎片、小妖魂魄、靈妖魂魄、高級鎖定符、地術殘卷(綁)、人皇斷篇(綁)。有較小機率獲得全新稀有聖獸坐騎玄武之靈(非綁)、稀有坐騎破山·聖(非綁)。打開666個內必出破山·聖！[-]\n[e76041]太陰化生，統攝萬靈。[-]"
item_ext_desc[10000279] = "小金錢樹的果實，打開後可以獲得50非綁鑽、馬草*10、2級體力丹*2、光羽*1。"
item_ext_desc[10000280] = "中金錢樹的果實，打開後可以獲得200非綁鑽、馬草*15、煉妖丹*10、寶玉*2。"
item_ext_desc[10000281] = "大金錢樹的果實，打開後可以獲得400非綁鑽、馬草*20、3級寶石禮包*1、秘隕*3。"
item_ext_desc[10000282] = "[ffffff]打開禮盒後必定獲得馬草*5，且同時有機率獲得醉仙之輝、雪月之輝、流霜之輝、朱炎之輝、赤虹之輝、夜襲之輝、鋼尾之輝、謠夜之輝等非綁定坐騎碎片之一。[-]\n[e76041]世有伯樂，然後有千里馬。[-]"
item_ext_desc[10000283] = "[ffffff]打開禮盒後必定獲得馬草*10，且同時有機率獲得赤虹之輝、夜襲之輝、破山·神之輝、謠夜之輝、金尾之輝、曜夜之輝、破山·聖之輝、冰離之輝等非綁定坐騎碎片之一。[-]\n[e76041]世有伯樂，然後有千里馬。[-]"
item_ext_desc[10000284] = "[ffffff]打開禮盒後必定獲得馬草*20，且同時有機率獲得鋼尾之輝、破山·神之輝、謠夜之輝、金尾之輝、曜夜之輝、破山·聖之輝、冰離之輝、鴻鵠之輝等非綁定坐騎碎片之一。[-]\n[e76041]世有伯樂，然後有千里馬。[-]"
item_ext_desc[10000285] = "[ffffff]打開后必出龍紋金元，概率獲得4-7級寶石禮包、馬草、光羽、上古兵策、夜明珠、靈妖魂魄、5級原石、5級皮料等。有較小概率獲得稀有坐騎金翼（非綁）、幻朧·聖（非綁），打開888個內必出幻朧·聖[-]"
item_ext_desc[10000286] = "[ffffff]稀有坐騎。[-]\n[e76041]使用後獲得坐騎-幻朧•神[-]"
item_ext_desc[10000287] = "[ffffff]珍貴坐騎。[-]\n[e76041]使用後獲得坐騎-幻朧•聖[-]"
item_ext_desc[10000288] = "[ffffff]自來鼻上無繩索，天地為欄夜不收。使用後獲得坐騎 鎏金木牛（出售後可獲得25本地術殘卷。）。[-]"
