item_ext_desc[10000294] = "[ffffff]一張平淡無奇的圖紙憑證，在活動未結束前，千萬不要出售商店喔！[-]"
item_ext_desc[10000295] = "[ffffff]打開禮包可以獲得馬草*100、暢行丹*5、綠色豪傑酒*5、寶玉*5、地術殘卷(綁)*1。[-]\n[e76041]四月槐花掛滿枝。[-]"
