item_ext_desc[10000298] = "[ffffff]打開後有機率獲得馬草、光羽、4-7級寶石禮包、寶玉、秘隕、魂魄碎片、人皇斷篇(綁)、地術殘卷(綁)等。有較小機率獲得時裝嘉木繁蔭(非綁)、稀有坐騎木牛(非綁)、鎏金木牛(非綁)。[-]\n[e76041]打開666個內必出木牛！[-]"
item_ext_desc[10000299] = "[ffffff]打開後有機率獲得馬草、光羽、4-7級寶石禮包、煉妖丹、洗髓丹、3級寵物口糧、人皇斷篇(綁)、無字天書(綁)等。有較小機率獲得蝶舞幻化(非綁)、稀有坐騎獄焱(非綁)、幽冥(非綁)。[-]\n[e76041]打開666個內必出獄焱！[-]"
item_ext_desc[10000300] = "[ffffff]打開後有機率獲得馬草、3-6級寶石禮包、3-5級寵物口糧、人皇斷篇(綁)、通靈神冊(綁)等。有較小機率獲得紋袞冕服時裝(非綁)、紫玉青鸞幻化(非綁)、稀有坐騎碧空(非綁)、淩月(非綁)。[-]\n[e76041]打開666個內必出碧空！[-]"
