item_ext_desc[10000335] = "[ffffff]打開後有機率獲得馬草、靈羽、3~7級寶石禮包、寶珠囊·人、春秋遺物·混戰、寵物口糧、靈妖魂魄、人皇斷篇(綁)、龍骨等。有較小機率獲得神兵[-][00e104]戰神（7天）[-][ffffff]、坐騎[-][00e104]擎天(非綁)[-][ffffff]、全新幻化[-][00e104]蒼翠雲嵐兌換券(非綁)[-][ffffff]、紫色品質神寵[-][00e104]邱比特(非綁)[-][ffffff]。[-]\n[e76041]666包內必出坐騎擎天。[-]"
