item_ext_desc[10000367] = "[ffffff]打開有較小概率獲得珍稀坐騎萌瑪、二哈，有幾率獲得綠色豪傑酒、綠色押鏢令、紫色封魔帖、紫色韜略果、免戰牌、天賜體力丹、委託通兌令、地術殘卷等，每包必出龍紋金元。[-]"
