item_ext_desc[10000376] = "[ffffff]打開後有較小概率獲得全新坐騎影閃，概率獲得天神祭品、4~5級寶石禮包、無字天書、寶珠囊·人、馬草、上古兵策、上古兵卷、上古兵書。每包必出龍紋金元。[-]"
item_ext_desc[10000377] = "[ffffff]打開後有較小概率獲得全新坐騎鎏光、戰神·7天、戰神·30天，概率獲得寶玉囊·人、煉星囊·人、洗練囊·人、魂魄包·地、2~3級保底符、高級鎖定符、馬草、夜明珠等。[-]"
item_ext_desc[10000378] = "[ffffff]打開後有較小概率獲得珍稀坐騎水雲，概率獲得馬草、靈羽、光羽、免戰牌、天賜體力丹、委託通兌令、心心石、3級保底符、高級鎖定符、紫色封魔帖、紫色韜略果等。[-]"
item_ext_desc[10000379] = "[ffffff]瑤池閬苑，打開後獲得綁定。[-]"
item_ext_desc[10000380] = "[ffffff]打開後概率獲得珍稀名寵海盜船長寵物蛋、鬥牛時裝、龍骨，有較大概率獲得福星彩珠囊、靈妖魂魄、人皇斷篇、地術殘卷、3級寵物口糧、4~6級寶石禮包、寶珠囊·人等。[-]"
item_ext_desc[10000381] = "[ffffff]打開後有較小概率獲得全新時裝侍願、全新坐騎如意。概率獲得鮮肉、稻米、粟米、馬草、3級保底符、4~5級寶石禮包、上古兵卷、上古兵書、上古兵策等。每包必出龍紋金元。[-]"
item_ext_desc[10000382] = "[ffffff]打開後有較小概率獲得全新翅膀靈梟幻化、全新坐騎七彩。概率獲得3~5級寶石禮包、綠色豪傑酒、綠色押鏢令、紫色封魔帖、紫色韜略果、馬草、神羽、寶珠囊·人等。每包必出龍紋金元。[-]"
item_ext_desc[10000383] = "[ffffff]非綁定劍影花馨，打開後獲得綁定。[-]"
item_ext_desc[10000384] = "[ffffff]打開後有較小概率獲得新春限定坐騎旺財、稀有坐騎冥獒，概率獲得捕獸百寶箱、年獸誘餌、新春爆竹（大）、風元寶珠、火元寶珠、水元寶珠、雷元寶珠、精華囊·人、紫色韜略果、高級鎖定符等，每包必出龍紋金元。[-]"
item_ext_desc[10000385] = "[ffffff]好運時節：打開後獲得夜明珠*5，精華囊·人*5，馬草*20，靈羽*20。[-]"
item_ext_desc[10000386] = "[ffffff]龍吟禮包：打開後可獲得綁定綺星蝕月碎片*33，夜明珠*10。[-]"
item_ext_desc[10000387] = "[ffffff]六龍利是：打開後可獲得10綁定鑽石、馬草*18、靈羽*18、綺星蝕月碎片*1。[-]"
item_ext_desc[10000388] = "[ffffff]傲天禮包：打開後可獲得綁定綺星蝕月碎片*66，精華囊*人*20。[-]"
item_ext_desc[10000389] = "[ffffff]綁定綺星蝕月，分解後可獲得夜明珠*20。[-]"
item_ext_desc[10000390] = "[ffffff]綁定綺星蝕月碎片，100個綺星蝕月碎片可合成一個綁定綺星蝕月。[-]"
item_ext_desc[10000391] = "[ffffff]打開後有較小概率獲得全新時裝蘭陵遺裔、絕世戰袍（7天），概率獲得通靈神章、通靈神冊、隨機1~3級銘文、坐騎包·地、神羽包·地、4級保底符、3~4級寶石禮包等。[-]"
item_ext_desc[10000392] = "[ffffff]打開後有較小概率獲得稀有坐騎晴洺、絕世戰袍（15天）,概率獲得黑芝麻、五仁餡料、魂魄碎片、小妖魂魄、靈妖魂魄、上古兵策、上古兵卷、上古兵書、春秋遺物·敵戰、春秋遺物·攻戰等。[-]"
item_ext_desc[10000393] = "[ffffff]非綁定暗淡凋零，打開後獲得綁定。[-]"
item_ext_desc[10000394] = "[ffffff]非綁定暗夜霜衣，打開後獲得綁定。[-]"
item_ext_desc[10000395] = "[ffffff]非綁定盛唐遺韻，打開後獲得綁定。[-]"
item_ext_desc[10000396] = "[ffffff]植樹好禮：打開後獲得鮮花*10，二級寵物口糧*10。[-]"
item_ext_desc[10000397] = "[ffffff]春分時節：打開後獲得國之髓*1，三級保底符*1。[-]"
item_ext_desc[10000398] = "[ffffff]成城斷金：打開後有較小概率獲得全新坐騎姿韻，概率獲得國之髓、3~4級寶石禮包、坐騎包·地、神羽包·地、春秋遺物·敵戰、春秋遺物·攻戰、隨機2~3級銘文、精華囊·人、紫色韜略果等。每包必出龍紋金元。[-]"
item_ext_desc[10000399] = "[ffffff]紫曜魔道，打開後獲得綁定。[-]"
item_ext_desc[10000400] = "[ffffff]打開可隨機獲得寶玉囊·人、煉星囊·人、洗煉包·人、天賦包·人、3~4級寶石禮包、小馬草包、隨機1~2級銘文、精華囊·人、800綁鑽等。有較小幾率獲得全新時裝紫曜魔道。[-]"
item_ext_desc[10000401] = "[ffffff]打開可隨機獲得馬草、靈羽、寶珠囊·人、3~7級寶石禮包、5級原石、5級皮料等。有較小幾率獲得全新翅膀曦凰幻化或稀有坐騎誅仙四劍之【陷仙】。每包必出龍紋金元。[-]"
item_ext_desc[10000402] = "[ffffff]打開可隨機獲得春秋遺物·攻戰、春秋遺物·敵戰、精華囊·人、煉妖包·人、3級寵物蛋口糧、靈羽、馬草、隨機1~2級銘文、紫色韜略果等。有較小幾率獲得全新翅膀渃漓幻化或稀有坐騎誅仙四劍之【戮仙】。888包必出戮仙。[-]"
item_ext_desc[10000404] = "[ffffff]雲棲晚楓，打開後獲得綁定。[-]"
item_ext_desc[10000403] = "[ffffff]百鳥朝鳳兌換券，打開後獲得綁定。[-]"
item_ext_desc[10000405] = "[ffffff]聖誕大禮包：打開可獲得鮮花*20，靈羽*50，馬草*50，20綁定鑽石。[-]"
item_ext_desc[10000406] = "[ffffff]一代名師專屬補償道具。[-]"
item_ext_desc[10000407] = "[ffffff]打開可隨機獲得3~6級寶石禮包、綠色押鏢令、綠色豪傑酒、靈羽、馬草、競猜幣等。更有幾率獲得稀有坐騎姿韻、全新坐騎寒以及坐騎碎片寒之輝。每包必出黃色助威令，打開後可增加1點助威值（計入排行時可能存在5分鐘延時）。[-]"
item_ext_desc[10000408] = "[ffffff]必定獲得一枚坐騎碎片寒之輝，隨機獲得4級寵物口糧、上古兵書、5~9級寶石禮包、大量馬草、大量競猜幣，更有幾率獲得戰神（7天）、稀有坐騎姿韻、全新坐騎寒。每包必出紫色助威令，開啟後增加10點助威值（計入排行時可能存在5分鐘延時）。[-]"
item_ext_desc[10000409] = "[ffffff]集齊100個該道具可合成一個完整的綁定坐騎寒。[-]"
item_ext_desc[10000410] = "[ffffff]寸草春暉：打開後可獲得5級寵物口糧*1，鮮花*33。[-]"
item_ext_desc[10000411] = "[ffffff]打開後隨機獲得上古兵策、上古兵卷、上古兵書、3~5級寶石禮包、寶珠囊·人、3~4級寵物口糧、靈妖魂魄等。有較小幾率獲得海盜船長寵物蛋或稀有坐騎誅仙四劍之【絕仙】。每包必出龍紋金元。[-]"
item_ext_desc[10000412] = "[ffffff]打開後隨機獲得地術殘卷、人皇斷篇、馬草、3級保底符、4~5級寶石禮包、風/火/水/雷元寶珠、煉妖丹、春秋遺物·混戰、4~5級寵物口糧等。有較小幾率獲得坐騎兌換券（噗噗/應龍/破天/絕影四選一）或稀有坐騎誅仙四劍之【誅仙】。每包必出龍紋金元。[-]"
item_ext_desc[10000413] = "[ffffff]非綁定炎龍，打開後獲得綁定。[-]"
item_ext_desc[10000414] = "[ffffff]打開後隨機獲得馬草、靈羽、3~5級寶石禮包、3~5級寵物口糧、靈妖魂魄等。有較小幾率獲得風羽落塵、丘比特寵物蛋或全新坐騎岩琅。每包必出龍紋金元。[-]"
