item_ext_desc[10000416] = "[ffffff]打開後概率獲得4~6級寶石禮包、寶珠囊·人、5級寵物蛋口糧、靈妖魂魄、馬草、煉妖丹、3級保底符等，有較小概率獲得稀有時裝花翎寄羽、全新翅膀幻音幻化、熊貓人寵物蛋。[-]"
