item_ext_desc[10000453] = "[ffffff]嘯月傳說：打開後概率獲得寶玉囊·人、練星囊·人、洗煉包·人、天賦包·人、4~6級寶石禮包、3級保底符，有較小概率獲得全新時裝堇若蒼嵐、珍稀翅膀墨影璃裳、稀有坐騎嘯月。每包必出龍紋金元。[-]"
